P.transport["npc:anastasia-hartwell"] = {
  hash = "b4d21f",
  fullHash = "920d02",
  text = "Anastasia Hartwell. Anastasia Hartwell is a prominent Forsaken mage trainer residing in the Magic Quarter of the Undercity. She guides fledgling and developing spellcasters in mastering the arcane arts and oversees vital magical research and field missions across Lordaeron and beyond. Standing within the dark, echoing chambers of the Undercity's Magic Quarter, Anastasia Hartwell instructs Forsaken and Horde mages in channeling arcane energies. Though the kingdom of Lordaeron fell to ruin, former human practitioners like Anastasia have preserved their scholarly traditions in undeath. She maintains that magic demands strict discipline, warning any traveler she meets that careless incantations will quickly consume the untrained. Beyond fundamental spell instruction, Anastasia directs promising students toward vital field investigations. She sends mages to the Balnir Farmstead in eastern Tirisfal Glades to gather snapdragons that show how far the plague has spread, and into Algernon's alchemist shop in the Apothecarium to capture the invisible creatures of pure magic behind a strange disturbance. Through her tasks, practitioners learn that mastering magic means confronting its dangers directly, even within their own city. Anastasia's connections reach well beyond the borders of Tirisfal. As Horde spellcasters grow in proficiency, she coordinates with fellow trainers in distant lands, such as Deino in Orgrimmar, and directs advanced students toward solitary masters like Tabetha in the swamplands of Dustwallow Marsh. Her guidance ensures that Forsaken mages remain woven into the wider tapestry of the Horde's magical pursuits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_anastasia-hartwell-626df899b278aba8eba1/1-0000.mp3", duration = 92.1338776, start = 0},
  },
}
P.transport["npc:apothecary-johaan"] = {
  hash = "7a9851",
  fullHash = "7a9851",
  text = "Apothecary Johaan. Apothecary Johaan is an alchemist and researcher of the Royal Apothecary Society stationed in Brill. Tasked by his order and Lady Sylvanas, he conducts lethal experiments on local flora and fauna to develop the Forsaken's new plague. Working openly out of the Forsaken settlement of Brill in Tirisfal Glades, Apothecary Johaan represents the scientific ambitions of the newly formed Royal Apothecary Society. Like his colleagues across Lordaeron, Johaan operates under direct orders to craft biological and alchemical weapons capable of securing the Forsaken's fragile future against the living and the Scourge alike.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_apothecary-johaan-a62911fa8f7dd3c23060/1-0000.mp3", duration = 34.4555102, start = 0},
  },
}
P.transport["npc:apothecary-renferrel"] = {
  hash = "c766c8",
  fullHash = "c766c8",
  text = "Apothecary Renferrel. Apothecary Renferrel is a prominent member of the Royal Apothecary Society stationed at the Sepulcher in Silverpine Forest. Tasked with advancing the Forsaken's alchemical endeavors, he coordinates extensive field research into the region's corrupted wildlife and undead threats. Travelers through Silverpine frequently assist him with gathering volatile reagents and investigating dangerous Scourge remnants. Operating out of the Sepulcher, Renferrel serves as one of the Royal Apothecary Society's chief field researchers in Silverpine Forest. While Undercity houses the grand laboratories and high leadership of the society, Renferrel handles the practical, muddy work of securing native biological specimens, refining potent concoctions, and analyzing the grim ecology of Lordaeron's western border.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_apothecary-renferrel-924fe151c15cb17e7de7/1-0000.mp3", duration = 46.2628571, start = 0},
  },
}
P.transport["npc:aramis-hammerhand"] = {
  hash = "0e57d9",
  fullHash = "097c50",
  text = "Aramis Hammerhand. Aramis Hammerhand is an undead holy warrior situated within the desecrated chapel of Deathknell. As a Forsaken paladin trainer, he instructs newly risen dead who seek to reclaim their bond with the Holy Light. Walking this path in undeath requires immense discipline, as wielding such radiant energy inflicts agonizing pain upon their decayed flesh. Standing within the somber walls of Deathknell's chapel, Aramis Hammerhand represents an anomaly among the recently awakened Forsaken. In life, many citizens of Lordaeron answered the call of the Silver Hand, only to perish when the Scourge swept across the north. Aramis survived the fall only to be raised into undeath, yet he chose not to abandon the martial and spiritual teachings of his former existence. Now, he offers guidance to others who refuse to surrender their devotion. For an undead being, channeling the Holy Light is an ordeal of supreme willpower. The power burns necrotic flesh and reawakens long-dead nerves to excruciating pain. Aramis instructs his initiates that holding to this faith requires enduring continual torment. Through tasks like 'A Difficult Path' and 'Rediscovering the Light', he demands that young paladins confront the physical and spiritual costs of wielding a force inherently opposed to their present nature.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_aramis-hammerhand-aa9fe71b1ac156c8a8a3/1-0000.mp3", duration = 74.3967347, start = 0},
  },
}
P.transport["npc:arugal"] = {
  hash = "b4d729",
  fullHash = "6f91d7",
  text = "Arugal. Archmage Arugal is a former wizard of Dalaran who unleashed the feral worgen upon Lordaeron. Overcome by madness and grief, he now rules from the heights of Shadowfang Keep, treating the savage beasts as his beloved children while menacing all of Silverpine Forest. Before the fall of Lordaeron, Arugal was a member of the Kirin Tor, though some peers like Dalar Dawnweaver dismissed him as a charlatan whose weak spellcraft relied heavily on enchanted trinkets. When the Scourge swept across the north during the Third War, Arugal sought a weapon powerful enough to stem the tide. Drawing upon the esoteric research of the late Dalaran mage Ur, Arugal pierced the veil between realms and summoned the worgen into the mortal world. The ravenous beasts tore through the undead legions as intended, but their feral ferocity could not be contained, and their savage hunger swiftly turned against innocent mortals. The summoned horrors slaughtered not only the Scourge but soon turned on the wizards themselves. The beasts then besieged the ancestral seat of Baron Silverlaine, and the keep fell swiftly to claws and fangs, its lord and retainers slain in the massacre. Rather than flee from his monstrous creation, Arugal's mind fractured under the weight of guilt, and he adopted the beasts as his own offspring. Renaming the fortress Shadowfang Keep, Arugal entrenched himself within its ramparts, surrounded by ghostly victims and loyal hound-packs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_arugal-07fddac7424d0b235d8c/1-0000.mp3", duration = 86.3085714, start = 0},
  },
}
P.transport["npc:baine-bloodhoof"] = {
  hash = "f3766e",
  fullHash = "a23dd3",
  text = "Baine Bloodhoof. Baine Bloodhoof is the son of High Chieftain Cairne Bloodhoof and the acting protector of Bloodhoof Village in Mulgore. While his father governs the tribes from the towering heights of Thunder Bluff, Baine directly oversees local defense, investigating encroaching industrial exploitation and defending against feral predators. He serves as an essential bridge between youthful tauren braves and the ancestral wisdom of his clan. Born to Cairne, Baine spent his youth traveling alongside his nomadic people before they claimed the rich grasslands of Mulgore. His early life was marked by the ever-present threat of the centaur clans. Shortly after the Third War, a centaur warband under Khiragg captured young Baine, plunging Cairne into a grief-stricken stupor that nearly shattered the newly founded settlements. It was only through the courage of the champion Rexxar that Baine was liberated from captivity. That rescue restored Cairne's spirit, allowing the tauren to stand with Thrall's Horde against the invading Kul Tirans and secure their foothold on the continent. Rather than lingering in the relative comfort of the capital mesas, Baine chooses to reside among his kin in Bloodhoof Village. As Cairne advances in age, Baine carries an increasing burden of stewardship, representing the next generation of tauren leadership. He directs braves and visiting allies to combat the unruly Palemane gnolls who pester the borders, and keeps a watchful eye on suspicious outside influences threatening Mulgore's natural balance. Beyond territorial border clashes, Baine faces modern encroachers unconcerned with spiritual balance. To the east, the goblin Venture Company cuts deep into the sacred landscape, while dwarven prospectors from Bael Modan dig into ancestral soil at the Bael'dun Digsite. Baine advocates for a firm yet measured response: attempting to warn the miners and destroy their destructive equipment rather than rushing into senseless bloodshed. He warns that the dwarves' violent digging is hurting the spirits of the earth, though the miners refuse to listen.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_baine-bloodhoof-599ceb882240c9680b53/1-0000.mp3", duration = 115.957551, start = 0},
  },
}
P.transport["npc:bethor-iceshard"] = {
  hash = "a5695c",
  fullHash = "d8984b",
  text = "Bethor Iceshard. Bethor Iceshard is a powerful Forsaken mage based in the Magic Quarter of the Undercity. Presiding over the arcane and shadow practitioners within the Temple of the Damned, he commands considerable authority in Sylvanas's realm. Beneath his chilly demeanor lies a past entwined with old friends torn apart by the Scourge. Standing within the Temple of the Damned, Bethor Iceshard oversees the practitioners of the arcane arts and shadow magic in the Undercity. Respected and feared for his intellect and icy resolve, Bethor wields sufficient political and magical weight to give direct instructions to provincial magistrates across Lordaeron. He directs agents of the Forsaken to secure valuable grimoires, investigate arcane anomalies, and stamp out rival powers that threaten the Undercity's dominion. Before the Third War devastated Lordaeron, Bethor was a mortal apprentice studying magic alongside two close companions: Gunther Arcanus and Thule Ravenclaw. As a testament to their fellowship, the three students wove their practice wands together. The Scourge shattered that bond entirely. When death and dark magic swept across the kingdom, Thule Ravenclaw willfully surrendered his soul to the Lich King, Gunther perished and rose on an isolated island in Brightwater Lake, and Bethor succumbed only to later break free as Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bethor-iceshard-3aba2a2ceb11dab5e45e/1-0000.mp3", duration = 75.5983673, start = 0},
  },
}
P.transport["npc:brewmaster-drohn"] = {
  hash = "04d8ab",
  fullHash = "d6a3ab",
  text = "Brewmaster Drohn. Above Ratchet's docks, Brewmaster Drohn tends his brewing craft. The orc lives just uphill from the port, making potent drinks with methods tied to the wandering pandaren Chen Stormstout. Travelers who find discarded kegs across Kalimdor are sent to Drohn's porch. Brewmaster Drohn brews from his home on the hill above Ratchet's goblin docks. Rather than devote himself to combat, the orc has given his craft to brewing. He lives peacefully in the neutral haven established by Gazlowe's Steamwheedle cartel. While many orcs favor coarse grog or simple spirits, Drohn works with rare ingredients, carefully balanced flavors, and methods seldom practiced among his kin. Brewmaster Drohn learned brewing through a mentor who studied under Chen Stormstout, the pandaren wanderer who fought beside Rexxar and the Horde during the founding of Durotar. Chen also taught Drohn to make Trogg Ale. When travelers find Chen's discarded kegs in the wilds, Drohn is the only local authority who can identify their ingredients and recreate the wanderer's potent brews.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brewmaster-drohn-16b851e5d13e266b6ac0/1-0000.mp3", duration = 61.675102, start = 0},
  },
}
P.transport["npc:brine"] = {
  hash = "c7576d",
  fullHash = "f84299",
  text = "Brine. On Blackthorn Ridge, Brine guides shaman initiates toward the spirits of water. This orc shaman teaches them to commune with the tides and earn their Water Totem. Brine lives on a hill in northern Blackthorn Ridge, far from the Barrens' trading posts. Though dry savannas surround her, she has devoted her life to understanding water. Shaman across the Horde seek her wisdom after mastering earth and fire. She teaches that water calls for patience and perspective, qualities few understand as deeply as she does. In her youth, Brine marched with her orc companions across the Hillsbrad Foothills and fought against human settlements. During the campaign, she came to Tarren Mill and found a humble well fed by fresh spring water. The well stayed in her memory as a sign of life amid devastation. It strengthened a lesson she had learned as a child: even in the darkest sorrow, a small token of hope can still be found.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brine-af95d999b2dc849a70bf/1-0000.mp3", duration = 55.9020408, start = 0},
  },
}
P.transport["npc:cairne-bloodhoof"] = {
  hash = "5800f5",
  fullHash = "5b3967",
  text = "Cairne Bloodhoof. Cairne Bloodhoof is the venerable High Chieftain of the united tauren tribes and ruler of Thunder Bluff. A towering warrior of immense wisdom, he bound the fate of the tauren to Thrall's Horde after the orcs aided his people in escaping extinction at the hands of the centaur. For generations, the tauren lived as wandering nomads across the Barrens, continually hunted and driven toward extinction by savage centaur marauders. When Thrall and his orcs arrived on the shores of Kalimdor, Cairne recognized a rare nobility in them. Thrall offered military protection, escorting Cairne's desperate caravan across the plains to the safety of Mulgore in exchange for guidance to the Oracle at Stonetalon Peak. Settling upon the towering mesas of Thunder Bluff, Cairne finally established a permanent, unified home for all tauren tribes. Indebted to Thrall, Cairne followed the orcs to Stonetalon Peak and fought side by side with the Horde and Jaina Proudmoore's humans against the Burning Legion during the Third War. Later, when Admiral Daelin Proudmoore invaded Durotar, Cairne personally took up arms once more to fight alongside Rexxar after his captured son, Baine, was safely recovered. Today, Cairne stands as one of the Horde's most respected elders and Thrall's closest confidant, offering calm council against reckless warmongering.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cairne-bloodhoof-80b3e52626fe6c00a374/1-0000.mp3", duration = 78.2889796, start = 0},
  },
}
P.transport["npc:canaga-earthcaller"] = {
  hash = "64c706",
  fullHash = "338fc8",
  text = "Canaga Earthcaller. In the Valley of Trials, Canaga Earthcaller guides new Horde shamans toward the spirits of the land and their first totems. Canaga Earthcaller guides Darkspear trolls and orcs who begin the shaman’s path from the red bluffs of the Valley of Trials. He teaches newcomers to quiet their minds and listen to Kalimdor’s rumblings. They prepare earth sapta so they can commune with the spirits. Canaga asks each novice to gather sacred reagents and travel to the local spirit rock in Durotar. There, they drink earth sapta and see the elemental spirits firsthand. Through his guidance, they earn their Earth Totem.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_canaga-earthcaller-9317318dc2b1fd1e814f/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["npc:carendin-halgar"] = {
  hash = "de1a60",
  fullHash = "de1a60",
  text = "Carendin Halgar. Carendin Halgar is a prominent Forsaken warlock trainer residing in the Magic Quarter of the Undercity. Sharp-tongued and notoriously short on patience, he oversees the training of fledgling practitioners of the dark arts. He instructs aspiring warlocks on how to subjugate powerful demonic entities from the Twisting Nether, notably teaching the rituals to bind Voidwalkers and Succubi. Within the noxious gloom of the Undercity's Magic Quarter, Carendin Halgar instructs those who delve into the Twisting Nether. He demands focus and obedience, holding little tolerance for failure, hesitation, or weakness. Under his watchful gaze, warlocks are pushed beyond basic incantations into the dangerous mastery of summonings and soul manipulation, cementing the Forsaken's ruthless approach to demonic servitude.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_carendin-halgar-d9757f7fea516b1618ff/1-0000.mp3", duration = 45.322449, start = 0},
  },
}
P.transport["npc:chief-hawkwind"] = {
  hash = "9d1df3",
  fullHash = "76a931",
  text = "Chief Hawkwind. Chief Hawkwind is the tribal leader of Camp Narache, the proving grounds nestled in the Red Cloud Mesa of Mulgore. Responsible for guiding the youth of the Shu'halo, he mentors new adventurers as they embark on their traditional rites of passage. Under his watchful gaze, young braves learn humility, respect for the land, and the strength needed to protect their people. Standing at the heart of Camp Narache, Chief Hawkwind carries the solemn responsibility of preparing the next generation of tauren for the wider world. Red Cloud Mesa serves as a sheltered haven where fledgling hunters, shamans, druids, and warriors undertake the ancient Rites of the Earthmother. Hawkwind oversees these customs, ensuring that every youth learns duty and endurance before venturing beyond the safety of the mesa. Hawkwind's lessons begin with humility rather than martial glory. He sends initiates on simple chores, such as fetching clean spring water, to instill reverence for the natural world and their elders. Only after demonstrating a humble heart are braves guided toward tests of martial prowess, culminating in trials that test their resolve against the aggressive Bristleback quilboar encroaching upon the ancestral plains. Beyond his role as a mentor, Chief Hawkwind must reckon with rising dangers right at his camp's doorstep. The Bristleback tribe has grown increasingly bold, pressing hard against the perimeter of Red Cloud Mesa. Hawkwind coordinates the defense of the settlement, tasking newly proven braves with blunting the quilboar assaults to ensure the sacred training grounds remain secure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chief-hawkwind-7f3dc407ad4798977f05/1-0000.mp3", duration = 92.1338776, start = 0},
  },
}
P.transport["npc:coleman-farthing"] = {
  hash = "e6c443",
  fullHash = "4f6f44",
  text = "Coleman Farthing. Coleman Farthing is a bitter Forsaken survivor residing in the Gallows' End Tavern in Brill. In life, he worked for the wealthy Agamand dynasty at their extensive flour mills in northern Tirisfal. Convinced to stay and defend the estate against the Scourge, he died alongside his fellow laborers, and now dedicates his undeath to exacting vengeance on his former masters. Before the Third War, Coleman Farthing earned an honest living as a laborer at the Agamand Mills, the largest milling and agricultural operation in Tirisfal Glades. When the Scourge poured across Lordaeron, the aristocratic Agamand family refused to flee their valuable lands. Instead, they urged their household and laborers to take up arms alongside them, promising they could hold the farmsteads against the undead horde. Coleman and his fellow workers stayed, believing their masters—a decision that cost every last one of them their lives. Raised into undeath only to break free under the banner of the Forsaken, Coleman harbors a burning hatred for the Agamands. Rather than blaming only the Scourge, he blames the sheer hubris and greed of his employers for tricking their staff into an impossible last stand. Now loitering in Brill's tavern, Coleman enlists Horde champions to march into the blighted mills, cut down the risen Agamand kin, and plunder the heirloom weapons housed within their family crypt so that the last of their honor is stripped away.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_coleman-farthing-8bee3d6dd7c15990381a/1-0000.mp3", duration = 83.5657143, start = 0},
  },
}
P.transport["npc:dalar-dawnweaver"] = {
  hash = "4185b6",
  fullHash = "8d4363",
  text = "Dalar Dawnweaver. Dalar Dawnweaver is a former archmage of Dalaran who now serves the Forsaken at the Sepulcher in Silverpine Forest. Slain during the Scourge's destruction of the magi's city and later freed from the Lich King's control, he turns his magical intellect toward dissecting regional threats. From the shadows of the tomb, he directs efforts to understand Dalaran's lingering presence and undo the madness of Archmage Arugal. In life, Dalar Dawnweaver held high rank among the Kirin Tor, walking the halls of the Violet Citadel when Dalaran was a pinnacle of arcane mastery. His mortal life ended when the Scourge sacked the city to pave the way for Archimonde's summoning. Reanimated into the mindless thrall of the Lich King, Dalar broke free alongside Lady Sylvanas Windrunner when the Scourge's grip faltered. Now stationed at the Sepulcher, he retains the piercing intellect of an archmage, turned entirely toward safeguarding the Forsaken realm. Silverpine Forest is caught between multiple perils, and Dalar serves as the Sepulcher's arcane strategist. To the south, Dalaran wizards occupy Ambermill, meddling in matters Dalar seeks to uncover and disrupt. Even closer looms Shadowfang Keep and the feral worgen loosed upon the woods. Dalar possesses intimate knowledge of his former colleague, Archmage Arugal, and meticulously orchestrates campaigns to neutralize Arugal's beastly creations before they overrun the region.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dalar-dawnweaver-16bfa21cdb365380b7aa/1-0000.mp3", duration = 85.6816327, start = 0},
  },
}
P.transport["npc:darsok-swiftdagger"] = {
  hash = "6cf2c8",
  fullHash = "243131",
  text = "Darsok Swiftdagger. At the Crossroads, Darsok Swiftdagger watches the northern trails for threats. The orc scout directs Horde fighters against Witchwing harpies in the Dry Hills, whose raids endanger travelers and settlements. He is also an old friend of Witch Doctor Jin'Zil in Malaka'jin. Darsok Swiftdagger watches the northern scrubland from the Crossroads. The roads linking Durotar, Mulgore, and the Barrens’ northern reaches face raiders and centaur, as well as organized hunters from the sky. Darsok’s anger falls on the Witchwing harpies. Their roosts lie in the Dry Hills, northwest of the Forgotten Pools, where they threaten caravans traveling north. Darsok has an old friend far northwest of the Barrens: Witch Doctor Jin'Zil, a troll who lives at Malaka'jin in the Stonetalon Mountains, the land the harpies come from. Darsok sends Jin'Zil a letter with news of the harpy campaign. The two friends have not been in touch for many years.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_darsok-swiftdagger-798ce1784c292f14088b/1-0000.mp3", duration = 55.7714286, start = 0},
  },
}
P.transport["npc:deathguard-dillinger"] = {
  hash = "cf2185",
  fullHash = "f5d4af",
  text = "Deathguard Dillinger. Deathguard Dillinger is a Forsaken sentry stationed in Brill within Tirisfal Glades. Standing watch over the town's perimeter, he directs newly arrived undead toward necessary services and tasks recruits with keeping the local Scourge remnants at bay. As a member of the Forsaken Deathguard, Dillinger stands at the entrance of Brill, serving as both a frontline protector and an orienting guide for travelers emerging from Deathknell. He provides directions to town amenities such as the inn, the town hall, and local trainers, helping newly awakened undead navigate their new reality under the Dark Lady's rule. Dillinger actively enlists capable adventurers to purge lingering mindless Scourge from the nearby farms and mills. Through assignments like cullling rotting ghouls and reclaiming infested facilities, he seeks to establish a buffer zone of security around Brill, ensuring the fledgling Forsaken settlements can endure against unending undead predation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-dillinger-1b47bdc48d24a493f215/1-0000.mp3", duration = 57.2604082, start = 0},
  },
}
P.transport["npc:dendrite-starblaze"] = {
  hash = "e0e709",
  fullHash = "fe9e35",
  text = "Dendrite Starblaze. Dendrite Starblaze is a night elf druid residing in the sacred village of Nighthaven within Moonglade. Serving the Cenarion Circle, he acts as a vital mentor and guide for budding druids of both night elf and tauren descent. Through him, practitioners are summoned to the holy grove to master essential rites such as cleansing toxins and communing with nature's forms. Perched within Nighthaven, Dendrite Starblaze represents the nonpartisan, enduring spirit of the Cenarion Circle. When novice druids learn to attune their spirits to Teleport: Moonglade, Dendrite is among the first to welcome them upon arrival. He bridges the gap between ancient Kaldorei tradition and the emerging path of the tauren, treating all who heed the call of the wild as kin beneath the boughs of the sacred haven. Dendrite's primary duty involves initiating druidic apprentices into the deeper mysteries of nature. He directs novices through the trials required to understand poison and pestilence, sending them to examine tainted waters and discover herbal curatives. He also oversees the steps that lead druids to the water trials, testing their patience and endurance beneath the surface before granting communion with aquatic forms.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dendrite-starblaze-2971284127651b4f15cb/1-0000.mp3", duration = 68.8065306, start = 0},
  },
}
P.transport["npc:devrak"] = {
  hash = "5e8cff",
  fullHash = "8779c3",
  text = "Devrak. At the Crossroads, Devrak keeps the Horde’s wind riders ready for the roads across Kalimdor. The orc flight master carries couriers and supplies between Durotar, Mulgore, frontier outposts, and the Horde’s capitals. At the Crossroads, Devrak tends the wind riders that link the Horde’s far-flung holdings. The outpost stands where Kalimdor’s major trade routes meet, exposed beneath the sun and vulnerable to quilboar, centaur, and Alliance scouts. Quick flights matter here. Devrak pairs seasoned travelers and new messengers with trained wind riders that cross the savannah and reach Mulgore’s mountains or Durotar’s stone canyons. Devrak also helps move supplies from the frontier. Barrens hunters bring in meat and pelts, and he helps send them to Orgrimmar’s cooking fires and Thunder Bluff’s tanners. He introduces new couriers to flight masters across the continents, keeping an aerial route open to the Horde’s heartlands. Devrak tends more than beasts at the Crossroads. When the settlement comes under attack, he calls enraged wyverns to strike intruders with venomous stingers and talons. His roost is a dangerous target for anyone who attacks.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_devrak-713550783e4ceccd84d3/1-0000.mp3", duration = 67.3436735, start = 0},
  },
}
P.transport["npc:eitrigg"] = {
  hash = "bc7729",
  fullHash = "07a1ba",
  text = "Eitrigg. In Orgrimmar, Eitrigg stands beside Warchief Thrall as a trusted advisor. A veteran of the First and Second Wars, he left the Blackrock clan’s Horde after its defeat and lived in exile. Now he helps Thrall guide the New Horde toward honor and shamanism. Born on Draenor among the Blackrock clan, Eitrigg fought for the Horde in the First and Second Wars. The battles and the Horde’s defeat in the second war forced him to face how far his people had fallen into bloodlust and demonic corruption. Sickened by what the Horde had become, he left its scattered remnants and sought solitude in the wilds of Lordaeron. During his exile, Eitrigg sheltered in an abandoned tower near Hearthglen. The human paladin Tirion Fordring found him, and their clash brought the tower’s ruins down around them. Eitrigg pulled the unconscious human to safety instead of finishing him. Moved by this act of martial honor, Tirion swore friendship and kept the hermit’s location secret. The local Alliance authorities eventually captured Eitrigg and sentenced him to hang in Stratholme. Tirion cast aside his knighthood, lands, and freedom to attack the city and rescue him. Their bond showed both warriors that honor could cross the hatred between their peoples. In Stratholme, Thrall’s newly united Horde raided the city during Tirion’s attempt to free Eitrigg and carried the aging warrior away. Meeting Thrall convinced Eitrigg that the orcs were casting off demonic corruption and returning to their ancestral shamanic heritage. He crossed the Great Sea with Thrall to Kalimdor and took a revered place in Orgrimmar’s Valley of Wisdom. Now Eitrigg advises the young Warchief inside Grommash Hold. He helps evaluate new recruits and shares the wisdom he earned, so the New Horde does not repeat the tragedies of the past.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_eitrigg-57927e45e7092d9a720d/1-0000.mp3", duration = 104.385306, start = 0},
  },
}
P.transport["npc:executor-arren"] = {
  hash = "659b25",
  fullHash = "842f4b",
  text = "Executor Arren. Executor Arren is a high-ranking Forsaken officer stationed in Deathknell. He oversees the immediate defense and consolidation of the settlement as newly awakened undead emerge from their graves. Arren coordinates the local campaign against mindless Scourge zombies, feral beasts, and the encroaching zealots of the Scarlet Crusade. Standing resolute just outside the chapel in Deathknell, Executor Arren serves as the primary military voice for the nascent Forsaken within their awakening grounds. While the caretakers in the crypts guide newly raised undead through their disorientation, Arren directs their focus outward toward survival. Under Queen Sylvanas Windrunner's banner, he organizes local operations to sweep away mindless zombies that threaten the village borders, establishing secure territory in the shadow of Lordaeron's fall. Deathknell is surrounded by perils far deadlier than confused fledglings. Under Arren's orders, scouts and initiates strike at the vicious arachnids inhabiting Night Web's Hollow and eliminate dangerous predators haunting the woodland fringes. By demanding decisive action from every capable hand, Arren tests the fortitude of new arrivals, ensuring only those capable of defending their second chance at existence remain in the service of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_executor-arren-43ba2351e845c6a62fdf/1-0000.mp3", duration = 74.24, start = 0},
  },
}
P.transport["npc:executor-zygand"] = {
  hash = "4fb161",
  fullHash = "b99af6",
  text = "Executor Zygand. Executor Zygand is a senior Forsaken commander stationed at the town hall in Brill, overseeing defensive and military operations across central Tirisfal Glades. Reporting directly to the Undercity's high command, he coordinates the purge of Scarlet Crusade forces pressing into Forsaken territory. Positioned at the administrative heart of Brill, Executor Zygand coordinates regional defense for the Forsaken after their initial awakening in Deathknell. Serving as the direct superior to regional officers like Executor Arren and field sentries such as Deathguard Linnea, Zygand synthesizes scout intelligence and dispatches able recruits to safeguard Lordaeron's borders from encroachment. Zygand's primary military concern is the fanatic presence of the Scarlet Crusade, which infests outposts across Tirisfal Glades. Under his direction, agents are sent systematically to strike at Crusader scouts, encampments, and forward bases, ensuring the zealots never muster sufficient strength to threaten the approaches to the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_executor-zygand-11547dba88430f2ccb37/1-0000.mp3", duration = 60.1861224, start = 0},
  },
}
P.transport["npc:gan-rul-bloodeye"] = {
  hash = "601fb2",
  fullHash = "387057",
  text = "Gan'rul Bloodeye. In Orgrimmar, Gan'rul Bloodeye trains warlocks beneath the city. In the Cleft of Shadow, Horde initiates learn darker demonic rites and how to bend voidwalkers and succubi to their will. Warlocks study out of sight in the Cleft of Shadow beneath Orgrimmar. Warchief Thrall tolerates them in the new Horde, though Durotar's open sunlight is no place for their dark arts. The cavern gives shadow weavers, rogues, and fel casters room to study unmolested. From there, Gan'rul teaches rising practitioners of fel magic. Ambitious warlocks come to Gan'rul to learn dangerous summoning rites. Those seeking to bind a greater demon, such as a resilient voidwalker or a seductive succubus, must secure ritual components and learn the precise incantations. The summoned creature must be dominated before it consumes its master.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gan-rul-bloodeye-c4ec98732c826c17b99b/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["npc:gann-stonespire"] = {
  hash = "3fa216",
  fullHash = "3fa216",
  text = "Gann Stonespire. Along the southern Barrens road near Bael Modan, Gann Stonespire seeks retaliation for his people’s displacement. The tauren nomad’s tribe hunted on land now occupied by a dwarven excavation. Gann Stonespire camps beside the southern Barrens road after the dwarven expedition arrived from Ironforge and built Bael Modan. The surrounding land had been his tribe’s ancestral territory and hunting grounds. Dwarven miners drove the tauren from their soil with pickaxes, firearms, and heavy machinery, and refused peaceful overtures. Gann will not surrender his heritage quietly. He calls on travelers to strike back at the excavators.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gann-stonespire-85d7bc94774a68b6a6c7/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["npc:gazrog"] = {
  hash = "7eb672",
  fullHash = "d2947b",
  text = "Gazrog. At the Crossroads, Gazrog keeps watch over the Horde’s roads and supply lines. He calls on passing Horde travelers to face threats in the Barrens and search for lost patrols. Gazrog watches over the Crossroads and the roads beyond it. Marauders and beasts threaten the supplies moving through this isolated settlement, so he works with its defenders to keep cargo, coin, and couriers moving. The wilderness demands constant attention, and Gazrog depends on passing travelers to answer trouble beyond the outpost’s stockades. Gazrog’s watch extends across trails where raptors prey on travelers and quilboar clans ambush scouts. He coordinates responses to highway robberies, including the recovery of stolen Horde shipments. He also keeps track of missing soldiers, among them the grunt Dogran, who is injured and held by the quilboar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gazrog-b94022f52ebf8d7b29b7/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["npc:gornek"] = {
  hash = "49e14c",
  fullHash = "eb1309",
  text = "Gornek. In the Valley of Trials, Gornek oversees new orc and Darkspear troll recruits in Durotar. He receives those preparing to prove their worth to the New Horde. At the Valley of Trials, Gornek puts new Horde recruits through their first test of discipline. Warchief Thrall's order is clear: every youth and newcomer must earn a place through grit and perseverance. Gornek assesses those entering the valley, reads their introductory orders, and directs them to trainers around the compound. Whether an initiate carries an encrypted scrawl, a glyphic parchment, or a simple tablet, Gornek receives the credentials and sends them onto a harsh path of survival. The valley's arid canyons test battle skill and teach the New Horde's communal ways. Gornek keeps novices from lingering aimlessly, pointing them toward nearby scorpid burrows, feral boar dens, and veteran instructors. Those who survive the training grounds and slay the threats in the red rock gullies receive Gornek's final acknowledgment before he sends them out into Durotar's wider, perilous landscape.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gornek-61638facf00dd566b6a7/1-0000.mp3", duration = 61.4661224, start = 0},
  },
}
P.transport["npc:gunther-arcanus"] = {
  hash = "aaccd3",
  fullHash = "ae85b0",
  text = "Gunther Arcanus. Gunther Arcanus is an exceptionally powerful necromancer dwelling on an isolated island in Brightwater Lake. Slain during the Third War and raised into undeath, he managed to shatter the Lich King's mental grip entirely on his own. Long believing he was the sole undead possessing free will, he defended his retreat against all outsiders until discovered by the Forsaken. Before the fall of Lordaeron, Gunther was a promising apprentice among the Kirin Tor in Dalaran. Alongside close friends Bethor Iceshard and Thule Ravenclaw, he studied the arcane arts, secretly delving into necromancy despite the Kirin Tor's strict prohibitions against dark magic. To commemorate their brotherhood, the trio once bound their apprentice wands together into a single heirloom. When the Scourge swept across the north during the Third War, Gunther perished to the Plague of Undeath and was raised into servitude. Unlike most who required the Lich King's power to weaken or Lady Sylvanas to break their chains, Gunther's raw arcane mastery and sheer willpower allowed him to shake off the Lich King's mental domination entirely by himself. Convinced that every other walking corpse remained a mindless thrall of the Scourge, he retreated to an island in Tirisfal Glades, surrounding himself with shambling guardians and cutting off all contact with the living and dead alike.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gunther-arcanus-b88e1fb5230bd735443d/1-0000.mp3", duration = 75.0497959, start = 0},
  },
}
P.transport["npc:high-executor-hadrec"] = {
  hash = "a2be37",
  fullHash = "84153f",
  text = "High Executor Hadrec. High Executor Hadrec is the military commander of the Forsaken garrison stationed at the Sepulcher in Silverpine Forest. From this central crypt, he oversees defense against regional threats including the gnolls of the Rot Hide clan and investigates the disappearance of scouts across the zone. He serves as the primary officer directing Horde operations throughout Silverpine. Stationed within the gloom of the Sepulcher, High Executor Hadrec directs Forsaken military operations across Silverpine Forest. While Tirisfal Glades is firmly secured by the Dark Lady's forces, Silverpine remains fraught with peril, bordered by hostile Dalaran mages, feral worgen, and encroaching gnolls. Hadrec bears the grim responsibility of consolidating Forsaken territory and stamping out anything that challenges Undercity authority south of the capital. Much of Hadrec's immediate concern revolves around the Rot Hide gnolls and Fenris Isle. These undead-tainted beasts have infested the Dead Fields and the shores of Lake Lordamere, posing an unpredictable and vicious threat to Forsaken patrols. Hadrec dispatches agents to scour the decrepit ferries and rotting farmsteads for clues, determine what empowers the beasts, and prepare an outright strike against their island stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_high-executor-hadrec-7a25e4962eeb17259891/1-0000.mp3", duration = 73.3257143, start = 0},
  },
}
P.transport["npc:islen-waterseer"] = {
  hash = "442247",
  fullHash = "dc5695",
  text = "Islen Waterseer. Beside the Tidus Stair, respected tauren shaman Islen Waterseer guides Horde initiates through the trials of water. She lives by a quiet fishing hut and teaches shamans to attune to water spirits as they seek their Water Totem. On the Barrens coast, Islen Waterseer keeps to the craggy Tidus Stair, where arid plains meet the Great Sea. Water spirits are raw and near along this shore. Islen chooses this quiet outpost over thunderous halls and busy cities, spending her days listening to the tides. Shamans seeking communion with water come to her for guidance. To know water, a shaman needs inner harmony and spiritual sight as well as study. Islen guides seekers in preparing the Water Sapta, a sacred brew that pierces the veil between mortal senses and elemental manifestations. She teaches that water can be unyielding and deep, yet fluid and restorative. Anyone who calls on its aid must show it great respect. Though Islen lives quietly on the coast, her spiritual ties reach across Kalimdor. She shares a close, enduring friendship with Greta Mosshoof, another wise tauren skilled in the restorative arts. Islen's knowledge of water's purifying nature reaches beyond the Barrens, bringing spiritual aid to lands afflicted by deep corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_islen-waterseer-53d0c0cc43f88ccc4ade/1-0000.mp3", duration = 74.6318367, start = 0},
  },
}
P.transport["npc:kadrak"] = {
  hash = "5a62d3",
  fullHash = "4f2adf",
  text = "Kadrak. At the Mor'shan Rampart, Kadrak guards the northern frontier between the Barrens and Ashenvale. He directs dispatches and reinforcements into the contested forest, where the Horde fights the night elves. At the Mor'shan Rampart, Kadrak guards the main route between the Barrens and Ashenvale. The barricade marks a hard border: Horde-held plains lie to the south, and night elf-guarded woods stretch north. Kadrak keeps watch against Sentinels and hostile woodland creatures, holding the perimeter against incursions. Kadrak also handles military reports between the Barrens and logging camps deeper in Ashenvale. Couriers bring him combat reports from the Warsong Outriders, and he directs supplies and reinforcements to outposts such as Splintertree Post. Those who report to Kadrak are sent onward into the struggle for the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kadrak-c05dc411ac639b95ac8f/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["npc:magatha-grimtotem"] = {
  hash = "ba7a6a",
  fullHash = "cc8140",
  text = "Magatha Grimtotem. Magatha Grimtotem is the matriarch of the Grimtotem tribe and the Elder Crone of Thunder Bluff. A formidable shaman and political schemer, she resides on Elder Rise while continually challenging Cairne Bloodhoof's vision for the tauren nation. Magatha rose to absolute authority over the Grimtotem through an arranged union followed by the sudden, fatal climbing accident of her mate. Operating from Elder Rise with her personal retinue and bodyguards, she stands as the undisputed political and spiritual leader of her reclusive tribe. Unlike Cairne Bloodhoof, Magatha preaches tauren dominance, viewing other mortal races as intruders upon Kalimdor who ought to be eradicated or swept aside. Despite her open disdain for non-tauren, Magatha was among the earliest advocates for admitting the Forsaken into the Horde. She claims the tauren can teach the undead spiritual balance and guide them toward reclaiming their humanity. In practice, however, Magatha collaborates directly with the Royal Apothecary Society beneath Thunder Bluff, consulting figures like Apothecary Zamah on practical alchemy and arcane relic studies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magatha-grimtotem-0d86a7ff373b19119b27/1-0000.mp3", duration = 64.4963265, start = 0},
  },
}
P.transport["npc:magistrate-sevren"] = {
  hash = "3a159d",
  fullHash = "5ad408",
  text = "Magistrate Sevren. Magistrate Sevren is the chief administrative official presiding over the settlement of Brill in Tirisfal Glades. Standing inside the town hall, he organizes early Forsaken defense and directs arriving champions to stabilize the territory around the Undercity. Operating from the town hall in Brill, Magistrate Sevren coordinates civil authority and strategic efforts in the lands just north of the Undercity. As new Forsaken step forth into Tirisfal Glades, Sevren assesses local crises and dispatches adventurers to restore order, secure ruined infrastructure, and suppress persistent threats lingering in the surrounding hills. Sevren's primary concerns center on the preservation and recovery of the Tirisfal dead. Local graverobbers, rot hides, and rogue undead disrupt burial grounds, threatening the emerging dominion of Sylvanas Windrunner. Sevren ensures that ancestral tombs—such as the Agamand Family Crypt—are reclaimed and that deserters or uncooperative forces do not subvert Forsaken authority in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magistrate-sevren-41d2a1f2ce1fe18e738e/1-0000.mp3", duration = 58.88, start = 0},
  },
}
P.transport["npc:mangletooth"] = {
  hash = "89fc01",
  fullHash = "3372e4",
  text = "Mangletooth. At Camp Taurajo, Mangletooth faces execution in a Horde cage and bargains with those who visit him. He offers knowledge of his rivals and Agamaggan's ancient lore in return for their help. Tauren hunters and orc sentries keep Mangletooth in a cage at Camp Taurajo. The captured Razormane quilboar awaits execution, but he still tries to sway his captors and visiting Horde adventurers. He urges them to strike at the enemies of his tribe, hoping to prove his worth or win his freedom. Mangletooth knows the religious history of his people. During the ancient War of the Ancients, Agamaggan's spilled blood gave rise to the Barrens' massive thorns. Mangletooth gathers red crystalline Blood Shards from fallen Bristlebacks and channels the lingering divine power within them, granting ancient blessings to those who help him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mangletooth-296fe2c0e3efc011c145/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["npc:master-apothecary-faranell"] = {
  hash = "9c1246",
  fullHash = "847203",
  text = "Master Apothecary Faranell. Master Apothecary Faranell is the head of the Royal Apothecary Society, stationed within the depths of the Apothecarium in the Undercity. In life a respected Dalaran scholar, in undeath he directs the Forsaken's search for a devastating New Plague to eradicate both the Scourge and the living. Before the Third War, Faranell was an esteemed alchemist who spent decades studying alongside the learned mages of Dalaran. He spent his mortal days seeking cures, remedies, and potions to improve mortal health. When the Scourge plague claimed his life and he arose as a free-willed Forsaken, his former scientific curiosity curdled into cruelty. Retaining his encyclopedic intellect, he traded healing salves for catastrophic reagents, quickly becoming one of Queen Sylvanas Windrunner's most valued researchers in the bowels of Lordaeron's fallen capital. Operating out of the noxious laboratories of the Apothecarium, Faranell coordinates the far-flung research of the Royal Apothecary Society. He oversees the construction of lumbering abominations and directs subordinate apothecaries stationed throughout Lordaeron and beyond. Every batch of strange venom, tainted blood, and cursed flora gathered by field researchers across the continents eventually passes through his vats for distillation and refinement.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_master-apothecary-faranell-e21221a9c934df70af88/1-0000.mp3", duration = 74.7363265, start = 0},
  },
}
P.transport["npc:master-gadrin"] = {
  hash = "745add",
  fullHash = "f8ae4f",
  text = "Master Gadrin. In Sen'jin Village, Master Gadrin guides the Darkspear through exile and loss. The elder witch doctor once trained the tribe's priests and mages with Zalazane. Now he helps his people and seeks to break the dark curse over their home on the Echo Isles. Before the Darkspear reached Kalimdor, Master Gadrin guided generations of his people in the South Seas. He served as a witch doctor on the islands they called home, teaching the tribe's mystical ways. On the Echo Isles, Master Gadrin and the young witch doctor Zalazane trained the tribe's priests and mages together. Zalazane fell under the pull of the dark voodoo he sought to wield, and madness took hold. He enslaved the minds of his people and drove Vol'jin and the uncorrupted Darkspear onto the mainland of Durotar. Now in Sen'jin Village, Gadrin bears the grief of watching a companion become a tyrant. He works to lay slain tribesfolk to rest and end Zalazane's rule. Master Gadrin knows more of troll spiritualism and loa lore than almost anyone alive in the Horde. Scholars, shamans, and the Royal Apothecary Society seek his counsel on arcane and alchemical mysteries. When the Burning Blade threatens Durotar, or distant researchers need forgotten rites, Gadrin draws on what he knows. He can decipher the ancient tablets of Zul'Farrak and invoke Shadra the spider loa, then craft the bindings such a rite requires.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_master-gadrin-cb2c7c256858f7bebd84/1-0000.mp3", duration = 83.5918367, start = 0},
  },
}
P.transport["npc:mebok-mizzyrix"] = {
  hash = "b2c0d1",
  fullHash = "dd42bd",
  text = "Mebok Mizzyrix. Mebok Mizzyrix is an enterprising goblin entrepreneur residing in the port town of Ratchet. Ever eager to turn bizarre wilderness reagents into profit, he hires passing adventurers to gather unusual flora and fauna from across the Barrens and beyond. His most notorious project involves concocting a commercial intellect-enhancing beverage out of raptor horns. Operating out of the bustling, neutral port of Ratchet, Mebok Mizzyrix embodies the classic Steamwheedle spirit of relentless opportunism. While Ratchet caters to sailors, pirates, and merchants of all stripes, Mebok focuses his keen eye on Kalimdor's wilderness. Rather than mining standard ore or trading mundane cloth, he seeks out rare biological curiosities that he believes can be refined into highly lucrative concoctions and commodities. Mebok's premier commercial endeavor is a proprietary 'smart drink' intended to artificially boost the intellect of whoever consumes it. Convinced that the natural cunning and ferocity of local raptors stems from the horns crowning their snouts, Mebok commissions hunters to harvest intact horns across the Barrens. To him, ethics and taste take a backseat to raw market potential, so long as paying customers believe the brew delivers results. Beyond raptor-derived elixirs, Mebok maintains a constant demand for other bizarre specimens. From collecting volatile Deepmoss spider eggs to commissioning the retrieval of rare Blueleaf tubers buried deep within the brambles of Razorfen Kraul, his pursuits consistently push intrepid mercenaries into perilous territory. If an organism possesses strange properties, Mebok is certain there is a way to bottle and sell it.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mebok-mizzyrix-07486e6af37ab2641f54/1-0000.mp3", duration = 97.1232653, start = 0},
  },
}
P.transport["npc:melor-stonehoof"] = {
  hash = "a9a451",
  fullHash = "1b75cf",
  text = "Melor Stonehoof. Melor Stonehoof is a veteran tauren huntsman stationed atop Hunter Rise in Thunder Bluff. As a mentor in the ways of the hunt, he tests the tracking prowess and mettle of Horde hunters by sending them after the most dangerous predatory beasts across the Barrens and Thousand Needles. Perched upon the breezy expanse of Hunter Rise, Melor Stonehoof observes the plains below with a practiced eye. The art of the hunt is sacred to the tauren, entwined with survival, spiritual balance, and respect for nature's greatest predators. Melor ensures that those who carry bow and blade in the name of the Horde understand this balance, directing promising stalkers to master their craft through trials against legendary beasts. Melor challenges hunters to seek out legendary and elusive beasts that terrorize the wild. He directs trackers across the plains of the Barrens, from aiding the huntress Sergra Darkthorn at the Crossroads to pursuing Steelsnap, a cunning and vicious hyena in Thousand Needles. Through these trials, hunters prove they can outsmart and outfight the deadliest creatures of central Kalimdor. For those whose skills exceed the Barrens, Melor points toward far-off lands. He charges seasoned hunters with bringing down beasts of terrifying strength, including Deadmire, an ancient crocolisk lurking in the swamps of Dustwallow Marsh, and the savage yeti Frostmaw of the Alterac Mountains. Each hunt serves to test whether a stalker has truly mastered the Hunter's Way.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_melor-stonehoof-f33164ec8f405197b5c1/1-0000.mp3", duration = 81.5281633, start = 0},
  },
}
P.transport["npc:menara-voidrender"] = {
  hash = "c6949f",
  fullHash = "5e5ad8",
  text = "Menara Voidrender. In Ratchet, Menara Voidrender teaches warlocks from both factions the dark arts. The human warlock shares her knowledge of demon-binding artifacts and arcane craft from a refuge in Kalimdor, far from orthodox authorities. Menara Voidrender works from Ratchet, the neutral goblin port in the Barrens. Many warlocks in the Eastern Kingdoms study in cellars or hidden slaughterhouses beneath their cities, but Ratchet keeps Menara away from the Kirin Tor, Stormwind's guards, and Orgrimmar's overseers. There, she can pursue occult studies in plain sight. She teaches any capable apprentice, whatever their faction, making her a rare meeting point for practitioners of the dark arts. Veteran conjurers know Menara as an authority on orbs that imprison and harness demonic spirits. She works with intricate reagents and guides apprentices through demanding rituals to make enchanted attire and binding implements. Her skill is known as far as Ironforge and the Undercity, and senior warlocks across Azeroth send their most promising students across the sea to seek her counsel.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_menara-voidrender-59ac5e5d37e3342b1bb0/1-0000.mp3", duration = 61.9102041, start = 0},
  },
}
P.transport["npc:morin-cloudstalker"] = {
  hash = "c9dc97",
  fullHash = "4745df",
  text = "Morin Cloudstalker. Morin Cloudstalker is a tauren scout keeping watch along the road leading east from Bloodhoof Village toward the Barrens in Mulgore. Standing vigil over the plains, he monitors local trade routes and investigates the encroaching threats endangering tauren travelers. Positioned beside the dirt path winding east toward the Barrens, Morin Cloudstalker acts as both a scout and a guardian for travelers through Mulgore. The grassy plains here are usually peaceful, but the opening of trade routes and shifting territories have drawn opportunists and bandits dangerously close to the heart of the tauren homeland. Morin's scouts recently attacked and burned a Venture Co. caravan on the northern shore of Stonebull Lake. When goblin salvagers were spotted near the burned wagons, he sent adventurers to examine the surviving supply crates and learn what the Venture Co. was hauling.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_morin-cloudstalker-dca4e56ab26a6e17f3e3/1-0000.mp3", duration = 47.4906122, start = 0},
  },
}
P.transport["npc:mull-thunderhorn"] = {
  hash = "e83d54",
  fullHash = "e83d54",
  text = "Mull Thunderhorn. Mull Thunderhorn is a tauren elder residing in Bloodhoof Village in Mulgore. Deeply devoted to the Earth Mother and the balance of the land, he watches over the sacred water wells scattered across the plains. As outside exploiters threaten the region's lifegiving waters, Mull guides young tauren through the rituals required to cleanse the ancestral springs. Standing watch in Bloodhoof Village, Mull Thunderhorn carries the weight of Mulgore's spiritual well-being. The nomadic tribes have gathered under High Chieftain Cairne Bloodhoof to establish a permanent home, yet their lands are already under siege by greed and reckless expansion. Mull serves as a spiritual anchor for the young braves stepping out of Camp Narache, calling upon them to safeguard the vital resources of their ancestors.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mull-thunderhorn-16c6b2dbe3e079280cc0/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["npc:orgnil-soulscar"] = {
  hash = "76e0b7",
  fullHash = "76e0b7",
  text = "Orgnil Soulscar. At Razor Hill, Orgnil Soulscar watches for threats within Durotar. He gathers intelligence and coordinates defenses against dangers to the young orc nation, especially the Burning Blade cult in the canyons. At Razor Hill, Orgnil Soulscar tracks hidden threats across Durotar. While grunt patrols watch for Alliance forces and centaur raiders, he looks for danger among the orcs themselves. Scouts bring him reports from across the region, and he searches them for signs of corrupt rituals and secret gatherings.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orgnil-soulscar-f5e6cb688aadd5c98e5d/1-0000.mp3", duration = 30.9028571, start = 0},
  },
}
P.transport["npc:shadow-priest-allister"] = {
  hash = "2322b9",
  fullHash = "62aa61",
  text = "Shadow Priest Allister. Shadow Priest Allister is a Forsaken priest stationed at the Sepulcher in Silverpine Forest. Overseeing intelligence and tactical efforts in the region, he coordinates operations to monitor Dalaran's wizards and secure the borders of Lordaeron for the Dark Lady. Operating out of the Sepulcher, Shadow Priest Allister directs Forsaken reconnaissance throughout Silverpine Forest. From this central crypt settlement, he tracks nearby threats ranging from renegade humans and beastly incursions to the arcane machinations unfolding around Dalaran. Allister's chief concern lies with the surviving mages of Dalaran, particularly those occupying Ambermill and probing across the borders. Unwilling to let the Kirin Tor entrench themselves in Forsaken lands, he dispatches agents to intercept Dalaran messengers, decipher arcane runes, and determine the wizards' long-term ambitions. Beyond his duties as a field strategist, Allister is a cynical philosopher of the shadow. He is the author of 'Holy Bologna: What the Light Won't Tell You'—a scathing treatise criticizing traditional holy doctrine. The text explores the harsh realities of undeath and how the Holy Light fails those discarded by life, a work that has somehow circulated as far afield as the ruins of Dire Maul in Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shadow-priest-allister-c341ea2a51e68dde6b1b/1-0000.mp3", duration = 76.5387755, start = 0},
  },
}
P.transport["npc:shadow-priest-sarvis"] = {
  hash = "e2b908",
  fullHash = "65b8ad",
  text = "Shadow Priest Sarvis. Shadow Priest Sarvis stands inside the ruined chapel of Deathknell, serving as one of the primary guides for newly awakened Forsaken. He introduces fresh corpses to their grim reality, directing them to purge mindless undead and gather intelligence on local threats. Under Lady Sylvanas's banner, Sarvis works tirelessly to shape bewildered undead into disciplined servants of the Forsaken. Within the shadowy chapel of Deathknell, Shadow Priest Sarvis waits for those who have just clawed their way out of the grave. The awakening of a Forsaken soul is jarring and horrific, with many immediately losing their minds to mindless frenzy or despondency. Sarvis acts as an anchor, giving purpose to the newly risen. He assigns new recruits to put down the shambling, mindless corpses roaming the cemetery and directs them to secure Deathknell's borders against the encroaching Scourge. Beyond acclimating new recruits, Sarvis oversees crucial local defenses against lingering threats in Tirisfal Glades. He coordinates the containment of Scourge forces probing Deathknell's perimeter. By directing novices toward vital intelligence and martial trials, Sarvis ensures that the town remains a fortified bastion for the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shadow-priest-sarvis-328c7b096ee8593a0dda/1-0000.mp3", duration = 69.0938776, start = 0},
  },
}
P.transport["npc:shael-dryn"] = {
  hash = "409904",
  fullHash = "409904",
  text = "Shael'dryn. Shael'dryn is an inquisitive dryad residing beside the Moonwell of Purity, east of Iris Lake in Ashenvale. She serves as a vital contact for night elf scouts investigating forest corruption. She plays a pivotal role in aiding Astranaar's sentinels with cleansing relics to combat demonic and foul influences spreading across the wilderness. Stationed beside the Moonwell of Purity, Shael'dryn keeps watch alongside the night elf sentinels guarding the eastern approaches of the forest. When corruption surfaces among the local wildlife or tainted relics threaten the land's harmony, her deep natural understanding allows her to guide adventurers through the steps required to restore spiritual balance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shael-dryn-22d2737897674d1b38bc/1-0000.mp3", duration = 39.6277551, start = 0},
  },
}
P.transport["npc:shenthul"] = {
  hash = "22f6dc",
  fullHash = "da7bc1",
  text = "Shenthul. In Orgrimmar's Cleft of Shadow, Shenthul trains rogues and serves the Shattered Hand. He directs covert work across Kalimdor and brings promising rogues into its ranks. Shenthul trains rogues in Orgrimmar's Cleft of Shadow. While warriors and shamans march openly across Durotar, he teaches stealth, ambush, and subterfuge. His students learn fieldcraft and lethal arts for work in Kalimdor's harsh wilderness and unforgiving politics. Shenthul speaks for the Shattered Hand, once an orcish clan and now the Horde's intelligence network and secret service. He describes it as a watchful presence across Kalimdor, investigating, judging, and carrying out its own sentences. Pragmatic and independent of shifting politics, Shenthul reminds outsiders that the Shattered Hand existed before Warchief Thrall took power and will endure after him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shenthul-2da54aa9e0da536879fd/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["npc:sputtervalve"] = {
  hash = "5b5869",
  fullHash = "bd7973",
  text = "Sputtervalve. Under pressure in Ratchet, Sputtervalve races to finish shredder research for the Tinkers' Union. Director Riddlevox holds him to crushing deadlines, and he hires adventurers to steal designs from the rival Venture Company. In Ratchet, Sputtervalve answers to Director Riddlevox of the Tinkers' Union. The goblin engineer oversees shredder development and has found the work brutal. Modern mechanization moves fast, the Venture Company presses hard, and his own prototypes are few. With the deadline closing in, Sputtervalve fears admitting failure to the Union. He turns to a familiar goblin practice: stealing better designs from those who built them first. The Venture Company's drilling operation at the Sludge Fen, to the northwest, is Sputtervalve's chief target. Its latest shredders have interchangeable hands, refined control grips, and advanced inner workings, including the elusive samophlange. Sputtervalve sent his associate Wizzlecrank into the Fen for field research, but Wizzlecrank became trapped. Now Sputtervalve hires wandering mercenaries to recover the stolen technology and rescue his partner. Sputtervalve also helps with strange curiosities that pass through the Barrens. Adventurers sometimes bring him bizarre artifacts infused with corruption from the Wailing Caverns, such as a glowing shard. He knows the local landscape well enough to point them away from machinery and toward the isolated druids encamped above the caverns.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sputtervalve-df922f3ed2c5b40fb1a8/1-0000.mp3", duration = 85.002449, start = 0},
  },
}
P.transport["npc:strahad-farsan"] = {
  hash = "cb26a9",
  fullHash = "2a9c06",
  text = "Strahad Farsan. Above Ratchet, Strahad Farsan teaches warlocks to bind demons. The human warlock lives in a stone tower in the Barrens, beyond the reach of ordinary Alliance and Horde politics. Students of fel magic come from Stormwind, Orgrimmar, and the Undercity to learn from him. Strahad Farsan keeps to a stone tower on the bluffs above Ratchet. The goblin port's neutral ground lets him practice dangerous summonings away from Alliance magistrates and Horde shamans. His acolytes gather around him as he studies the Twisting Nether, apart from the struggles over territory below. Strahad learned the danger of demonic binding firsthand. His first attempt to bind a felhunter nearly cost him his life, leaving him cautious and exacting. Despite being human, he has earned the respect of Gakin the Darkbinder in Stormwind and demonic scholars in the Undercity and Orgrimmar. Warlocks of either faction seeking to command felhunters or fiery steeds are sent to his tower.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_strahad-farsan-1e8dc7e6567a9611c680/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["npc:sylvanas-windrunner"] = {
  hash = "c2c158",
  fullHash = "0bd2db",
  text = "Sylvanas Windrunner. Lady Sylvanas Windrunner is the Banshee Queen and supreme ruler of the Forsaken, holding court in the Undercity beneath the ruins of Lordaeron. Once the brave Ranger-General of Silvermoon, she was slain and raised into undeath by Arthas Menethil before breaking free from the Lich King's grip. Now allied with Thrall's Horde out of mutual survival, she is fiercely dedicated to securing a future for her free-willed undead and exacting vengeance upon the Scourge. In life, Lady Sylvanas was the celebrated Ranger-General of Silvermoon, commanding the defense of Quel'Thalas during the Third War. When Prince Arthas Menethil marched the Scourge into the high elven kingdom to reach the Sunwell, Sylvanas fought fiercely to delay his advance. Frustrated by her resistance, Arthas murdered her, but denied her a clean death. He ripped her soul from her corpse and twisted it into a vengeful banshee, forcing her to serve the Scourge and assist in the slaughter of her own people. When the Lich King's magical grip fractured after the Third War, Sylvanas broke free of his dominion and repossessed her preserved body. Amassing other undead who had regained their free will, she overthrew the dreadlords occupying the ruins of Lordaeron, dubbed her people the Forsaken, and established the subterranean realm of the Undercity. Recognizing the precarious isolation of her people—threatened by Scourge remnants, zealous Scarlet crusaders, and suspicious human realms—she forged an uneasy alliance of convenience with Warchief Thrall and the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sylvanas-windrunner-b302cd8ab31c84aa799b/1-0000.mp3", duration = 86.804898, start = 0},
  },
}
P.transport["npc:telf-joolam"] = {
  hash = "5ffcf3",
  fullHash = "e58bdc",
  text = "Telf Joolam. At the Shrine of the Dormant Flame, Telf Joolam guides Horde initiates through the trials of fire. The Darkspear shaman teaches them to commune with and command the volatile element. Telf Joolam tends the Shrine of the Dormant Flame among the crags overlooking the borderlands. Fire spirits demand sharp discipline and unwavering focus, unlike the calm certainty of earth or the patient depth of water. Telf prepares young shamans for trials that test their worth before the wild embers consume them. Under Telf's direction, initiates brew and drink a ritual Fire Sapta, opening their mortal eyes to the unseen elemental planes. He sends them up the rocky summits to face burning spirits. Those who earn the flame must respect its ravenous hunger and resist reckless pride.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_telf-joolam-864bac321fe7995371c0/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["npc:thork"] = {
  hash = "b4da80",
  fullHash = "2adbb5",
  text = "Thork. At the Crossroads, Thork keeps watch over the settlement’s defenses. He sends Horde adventurers against raiders and works to keep supply routes open. Thork commands the defenses at the Crossroads, where roads link Durotar, Mulgore, and lands beyond. The town faces threats from every side. Quilboar raids, centaur attacks, and harpies on the prowl stretch his forces thin. Thork calls on capable travelers to meet dangers his guards cannot handle alone. Thork’s watch reaches beyond the Crossroads walls. He sends scouts and messengers north to the Mor’shan Rampart, where they report to Kadrak. The northern and eastern routes carry supplies through the Barrens. Keeping those roads open sustains the Horde’s presence across the scrublands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thork-f5b28fbca500ee1159b2/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["npc:thotar"] = {
  hash = "04d3c4",
  fullHash = "20269d",
  text = "Thotar. In Razor Hill, Thotar teaches young Horde hunters the ways of tracking and taming beasts. He trains orcs and trolls who have left the Valley of Trials to face Durotar’s wildlife. In Razor Hill, Thotar trains Horde hunters for the wilderness of Durotar. New recruits learn the basics in the Valley of Trials, then come to him as they face more dangerous predators. He teaches marksmanship and the respect needed to live alongside and direct Kalimdor’s deadliest creatures, drawing on traditions passed down through generations of orcs. Thotar guides young hunters through the ancient art of taming beasts. He sends them into arid canyons to calm and bond with native creatures, including venomous scorpids, armored surf crawlers, and cunning boars. His instruction teaches Horde trackers to build a bond with nature rather than rely on force.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thotar-e77994d00f6ad5533c07/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["npc:thrall"] = {
  hash = "e81f33",
  fullHash = "93ac5f",
  text = "Thrall. Thrall now rules from the Valley of Wisdom in Orgrimmar, Warchief of the Horde and ruler of Durotar. Once a human slave raised as an arena fighter, he freed his people, restored their shamanic traditions, and led them across the Great Sea to a new homeland. Thrall was born Go'el, son of Frostwolf chieftain Durotan and Draka. Gul'dan's assassins murdered his parents when he was an infant, and human commander Aedelas Blackmoore found him and named him Thrall, meaning slave. At Durnholde Keep, Blackmoore raised him as an arena fighter and taught him human tactics. With help from his foster sister Taretha Foxton, Thrall escaped. The Frostwolf exile Drek'Thar guided him away from demonic corruption and taught him to master the elemental spirits. Thrall became the first orcish shaman of a new generation. After the Second War, Thrall joined Orgrim Doomhammer to free the orcs languishing in Alliance internment camps. Doomhammer fell in battle and passed his black plate armor and mighty warhammer to Thrall, naming him Warchief. The mysterious Prophet Medivh brought prophetic visions, and Thrall led his people aboard captured human ships across the Great Sea. They reached Kalimdor and escaped the doom falling upon the Eastern Kingdoms. In Kalimdor, Thrall reshaped the Horde from a warmongering force into an alliance built on survival and honor. He rescued Vol'jin's Darkspear trolls and allied with Cairne Bloodhoof's tauren. With human and night elf forces, the coalition defeated the Burning Legion atop Mount Hyjal. Thrall then founded Durotar and its capital, Orgrimmar, named for his father and mentor. He keeps an uneasy peace with Jaina Proudmoore's Theramore while defending his fragile nation and weighing controversial alliances, including the Forsaken of Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thrall-d99a027bf08a9877a279/1-0000.mp3", duration = 105.900408, start = 0},
  },
}
P.transport["npc:tonga-runetotem"] = {
  hash = "a0d213",
  fullHash = "ad62cc",
  text = "Tonga Runetotem. At the Crossroads, Tonga Runetotem watches the Barrens' oases grow sick. Sent from Thunder Bluff, the tauren druid studies a corruption harming the region's wildlife and seeks its source before the fragile ecosystem fails. At the Crossroads, Tonga Runetotem studies the Barrens' changing land. His elders in Thunder Bluff sent him from Mulgore, and he knows the dry savannah well. Where travelers see scrub and predators, Tonga watches for signs of the land's health. Lately, those signs have turned troubling. He seeks travelers who can help him investigate the scattered oases, the heart of life across the savannah. Tonga bears the Runetotem clan name and the druidic heritage championed by Archdruid Hamuul Runetotem. Hamuul keeps ties with the Cenarion Circle and studies in Moonglade's sacred groves, while scouts like Tonga serve on the frontier. Tonga draws on Moonglade's botanical wisdom to prepare healing salves and counter poisons. His work puts the young tauren druidic tradition to use within the fledgling Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tonga-runetotem-375f2bbdfeb9fac39fdc/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["npc:turak-runetotem"] = {
  hash = "80cfa9",
  fullHash = "d9c4a7",
  text = "Turak Runetotem. Turak Runetotem is a revered tauren druid trainer residing in the Hall of Elders atop Thunder Bluff's Elder Rise. Serving as a trusted assistant to Archdruid Hamuul Runetotem, he guides novice tauren along the sacred paths of nature and balance. Through Turak, young druids undertake foundational trials to commune with spirits and master animal aspects. Within the serene confines of the Hall of Elders, Turak Runetotem stands as one of the Horde's foremost druidic mentors. Renowned for his deep patience and balanced demeanor, he assists Archdruid Hamuul Runetotem in reviving the ancient druidic arts among the tauren people. Turak ensures that every aspiring druid honors the will of the Earthmother, teaching that physical power must always be grounded in spiritual respect and harmony with nature. When a fledgling druid is prepared to embrace animal forms, Turak directs them into the wider world. He initiates their communion with the Cenarion Circle, teaching the art of teleporting across Kalimdor to the sacred haven of Moonglade. Recalling the bewilderment and intensity of his own youthful audience with the Great Bear Spirit, Turak tests his students' courage by sending them to face Lunaclaw and obtain the strength of body and heart needed to walk the Path of the Claw. Turak's guidance expands beyond primal combat forms to environmental stewardship. He sends his disciples back to Dendrite Starblaze to learn about poison, and Dendrite dispatches them to a rash of animal poisonings near the Crossroads, a situation that surprises even Turak. Through these trials, along with the arduous rituals beneath the tides to awaken the aquatic form, Turak shapes novices into enduring protectors capable of healing Azeroth's deepest wounds.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_turak-runetotem-849a2c466647cc70861e/1-0000.mp3", duration = 98.0636735, start = 0},
  },
}
P.transport["npc:varimathras"] = {
  hash = "be061f",
  fullHash = "903fbd",
  text = "Varimathras. Varimathras is a dreadlord of the nathrezim race who serves as the chief lieutenant and military advisor to Lady Sylvanas Windrunner. Forced to pledge loyalty to the Banshee Queen after suffering defeat during the civil war for Lordaeron, he now stands at her right hand in the Royal Quarter of the Undercity. Before the Third War, Kil'jaeden sent Varimathras and his fellow dreadlords to Azeroth as the Lich King's jailors, to make sure the spirit of Ner'zhul served the Legion's plans. Bound alongside his brothers Detheroc and Balnazzar, he oversaw the Scourge in Lordaeron while Archimonde invaded Kalimdor. When the Legion fell at Mount Hyjal, the triumvirate remained entrenched in the ruins of the Capital City, entirely unaware of their master's demise until Prince Arthas returned to drive them into hiding. As the Lich King's hold over his undead forces fractured, Varimathras attempted to coerce the newly freed banshee Sylvanas Windrunner into serving the dreadlords' new regime. Sylvanas refused, rallying liberated undead to crush Varimathras's outpost. Facing execution, the dreadlord fell to his knees and bartered for his life, trading tactical secrets and knowledge of his brothers' fortifications in exchange for survival. Sylvanas accepted, binding him to her service as a living weapon against his kin.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_varimathras-0da40bdc2b6229e0f0d5/1-0000.mp3", duration = 74.9191837, start = 0},
  },
}
P.transport["npc:vol-jin"] = {
  hash = "d0e9dc",
  fullHash = "dd47f0",
  text = "Vol'jin. In Orgrimmar, Vol'jin advises Warchief Thrall while seeking a lasting home for his people. The Darkspear chieftain is a master shadow hunter. Vol'jin leads the Darkspear after his father, Sen'jin, dies on their ancestral island. Sea witch-worshipping murlocs and human forces nearly destroy the isolated tribe, but Thrall's orcs intervene and forge a deep bond with the trolls. After fleeing the ruined islands, Vol'jin pledges his people to the New Horde and brings them across the Great Sea to Kalimdor. The Darkspear settle in Durotar, but Zalazane's betrayal on the Echo Isles drives many refugees to the mainland at Sen'jin Village. Vol'jin spends much of his time in Grommash Hold in Orgrimmar, giving Thrall his strategic counsel and shadow hunter skill. From the orcish capital, he watches over the young Horde and works to reclaim his people's lands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_vol-jin-f08a24f4fd477a17ed49/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["npc:yaw-sharpmane"] = {
  hash = "b315d3",
  fullHash = "6da706",
  text = "Yaw Sharpmane. Yaw Sharpmane is an experienced tauren hunter trainer stationed in Bloodhoof Village in Mulgore. He guides young hunters venturing out from Camp Narache, helping them master the wild beasts of their ancestral plains. Positioned amidst the tents and fires of Bloodhoof Village, Yaw Sharpmane serves the Shu'halo as an instructor in the ways of marksmanship, tracking, and survival. Young hunters who have proven themselves in Red Cloud Mesa are directed to Yaw to hone their craft as they step onto the broader plains of Mulgore. Yaw's most essential role is guiding novice hunters through the ancient rite of taming wild beasts. He tasks initiates with bonding with the native fauna of Mulgore, testing their patience and respect for the natural balance before instructing them on how to properly care for and train a permanent companion.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_yaw-sharpmane-9944d111805038cc6497/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["subzone:agama-gor"] = {
  hash = "979eca",
  fullHash = "dda521",
  text = "Agama'gor. Agama'gor stands north of the road from Camp Taurajo toward Mulgore. Bristleback quilboar hold this encampment in the southern Barrens, keeping pressure on the nearby Horde outpost. Agama'gor is a Bristleback stronghold in the southern Barrens. Its huts, brambles, and crude totems lie close to Camp Taurajo. The quilboar threaten travelers moving between the Barrens and Mulgore’s grassy hills, and Horde scouts and hunters fight to contain them. Bristleback quilboar in Agama'gor carry crimson stones called Blood Shards. Mangletooth, an exiled quilboar held captive at Camp Taurajo, seeks these stones because of ancient beliefs about Agamaggan’s sacred essence. Horde adventurers raid the encampment for shards and trade them to Mangletooth for tribal charms.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_agama-gor-a53bdb22b2557e17bf88/1-0000.mp3", duration = 43.52, start = 0},
  },
}
P.transport["subzone:agamand-family-crypt"] = {
  hash = "7002e9",
  fullHash = "7002e9",
  text = "Agamand Family Crypt. Tucked into the hills just north of Agamand Mills, the Agamand Family Crypt is the ancient resting ground of one of Tirisfal's wealthiest farming dynasties. Now claimed by the Scourge under Captain Dargol, its tombs have been ripped open, and the slumbering ancestors raised as mindless terrors. Before the Third War, the Agamand family held expansive estates across northern Tirisfal Glades, entombing their forebears within this hillside mausoleum. When the Plague brought ruin to the kingdom, the crypt fell into the clutches of Captain Dargol, an agent of the Scourge. Rather than letting the wealthy lineage rest in peace, Dargol employed dark necromancy to awaken the entombed skeletons and vengeful apparitions, transforming a sacred burial ground into an aggressive Scourge foothold right on the edge of Forsaken territory.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_agamand-family-crypt-10adc0f483603d05d52b/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["subzone:agamand-mills"] = {
  hash = "6bc02f",
  fullHash = "fae041",
  text = "Agamand Mills. Agamand Mills is a sprawling farm and windmill complex nestled in the northern heights of Tirisfal Glades. Once the proud estate of the wealthy Agamand dynasty, it has fallen into ruin and stands as the largest Scourge stronghold in the region. The wealthy Agamand family built their estate around a vast milling network across northern Tirisfal. When the Third War broke out and the Scourge swept across Lordaeron, the patriarch Gregor Agamand refused to flee, fortifying the compound and convincing his retainers and laborers to make their stand. Their provisions and stone walls might have held, but their youngest son, Devlin Agamand, betrayed his blood. Devlin slaughtered the estate watchmen and let the walking dead into the sleeping quarters. Crippled from within, the remaining defenders were wiped out, and the family joined the mindless ranks of the undead. Today, the Agamand Mills are the most entrenched bastion of the Scourge in Tirisfal Glades, posing an immediate threat to the Forsaken realm. The rotting windmills now churn above infested fields of wights, zombies, and skeletal horrors. Beneath the estate, Captain Dargol commands the garrison from the deep Agamand Family Crypt, practicing necromancy to reanimate generations of Agamand ancestors. From Brill, Magistrate Sevren and the Deathguards wage an active campaign to clear the mills and purge the Scourge presence before it can march upon the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_agamand-mills-f06b5a6840fe46eeaa34/1-0000.mp3", duration = 80.3526531, start = 0},
  },
}
P.transport["subzone:ambermill"] = {
  hash = "09465b",
  fullHash = "09465b",
  text = "Ambermill. Ambermill is a fortified human settlement in southeastern Silverpine Forest, situated just southwest of Lordamere Lake. Once a quiet lumber village, it is now occupied by surviving wizards and apprentices of Dalaran. Their presence represents a dangerous outpost of human resistance on the southern borders of the Forsaken realm. Before the Third War, Ambermill was a quiet lumber town of little importance. In the chaotic aftermath of Lordaeron's fall, the surviving wizards of the Kirin Tor moved in and fortified the settlement. Dalaran spellscribes, conjurors, and apprentices now patrol its buildings and stables, using Ambermill as a forward redoubt against the undead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ambermill-176f3169cd955480650b/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["subzone:apothecarium"] = {
  hash = "47efe4",
  fullHash = "84c0ea",
  text = "Apothecarium. The Apothecarium is the southwestern quarter of the Undercity and the headquarters of the Royal Apothecary Society. Within these noxious laboratories, Forsaken alchemists labor tirelessly under Master Apothecary Faranell to concoct virulent plagues, toxins, and engineered horrors. It stands as the grim heart of Undercity's biological research, vital to Lady Sylvanas's campaign against the living and the Scourge. Occupying the southwestern terrace of the subterranean capital, the Apothecarium is a labyrinth of bubbling vats, dissection tables, and pungent chemical fumes. Led by Master Apothecary Faranell, the Royal Apothecary Society utilizes this district to advance their understanding of mortality and rot. Here, alchemists and surgeons experiment on tissue grafts, vivisection, and the assembly of mighty abominations. Their overriding purpose, mandated by Lady Sylvanas Windrunner, is the formulation of a new plague capable of eradicating both the Scourge and the lingering human presence across Lordaeron. Beyond grand military ambitions, the quarter serves as the premier center of practical alchemy and herbalism for the Horde in the Eastern Kingdoms. Initiates and masters alike gather beside toxic canals to distill concoctions, study botanical blights, and consult master practitioners.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_apothecarium-8f3e7d55955c8bf1a6f3/1-0000.mp3", duration = 78.315102, start = 0},
  },
}
P.transport["subzone:bael-dun-digsite"] = {
  hash = "1da3fe",
  fullHash = "9f6fb8",
  text = "Bael'dun Digsite. The Bael'dun Digsite is a dwarven excavation carved deep into the mountains along the western edge of Mulgore. Established by Prospector Khazgorm's team out of Bael Modan, the quarry is viewed by the local tauren as a direct desecration of their ancestral homeland and an insult to the Earth Mother. Perched on the mountain slopes of western Mulgore, the Bael'dun Digsite represents the southernmost reach of the dwarven Explorers' League expedition based out of Bael Modan in the southern Barrens. Unconcerned with territorial borders or the spiritual traditions of the newly settled tribes, dwarven prospectors arrived with picks, shovels, and blasting powder to unearth ancient Titan relics buried beneath the plains. The Bloodhoof tribe viewed this invasive quarrying as an outright assault on the Earth Mother. Baine Bloodhoof initially urged caution and attempted to warn the interlopers away, but the dwarves flatly refused to abandon their trenches. Concluding that diplomacy had failed, the tauren resolved to break the expedition's tools and forcibly expel the miners before their destructive digging tears further into Mulgore's sacred earth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bael-dun-digsite-cd3daf4513861665796e/1-0000.mp3", duration = 66.1942857, start = 0},
  },
}
P.transport["subzone:bael-dun-keep"] = {
  hash = "6ce2f8",
  fullHash = "ccb0fa",
  text = "Bael'dun Keep. Dwarven forces hold Bael'dun Keep above the Bael Modan excavation in the southern Barrens. Under General Twinbraid, this imposing fortification anchors the Alliance's controversial presence in the region and brings it into violent conflict with the surrounding Horde territories. Bael'dun Keep rises over the Bael Modan excavation as the fortified military heart of Ironforge's presence in the southern Barrens. Dwarven architect Haggis Boatmurder designed the stronghold to protect the Prospectors and archaeologists searching the trenches for ancient titan artifacts. Ironworks and artillery arm its garrison, which keeps a vigilant watch, secures dwarven supply lines, and projects Alliance military power into Kalimdor's heartland. The keep and its adjoining digsite displaced the local Stonespire tribe of tauren from their ancestral home. Bael'dun remains a flashpoint in the Barrens, and nearby Horde outposts see it as a flagrant military intrusion. Gann Stonespire wages a personal war of vengeance against the invaders. Aggrieved tauren, opportunistic scouts, and suspicious outposts such as Camp Taurajo keep the fortress under threat of raids and sabotage.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bael-dun-keep-a81bfdb115c4c667d5e6/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["subzone:bael-modan"] = {
  hash = "2c2c97",
  fullHash = "2c2c97",
  text = "Bael Modan. Dwarven crews blast into the red earth at Bael Modan, searching for Titan relics. Their fortified outpost has driven the Stonespire tauren from their sacred land and kindled a bitter fight. Bael Modan's walls guard Bael'dun Keep, siege cannons, gyrocopter landing pads, and a deep excavation pit. Dwarven prospectors came to Kalimdor convinced an ancient Titan facility lay beneath the red earth. Their blasting tore through sacred ground of the Stonespire tauren. The expedition answered no call to negotiate. Gunfire and explosives drove the tribe from its ancestral lands, leaving survivors scattered and vengeful.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bael-modan-16dffecf76bc3f5b6782/1-0000.mp3", duration = 39.444898, start = 0},
  },
}
P.transport["subzone:balnir-farmstead"] = {
  hash = "542d38",
  fullHash = "dc1bf8",
  text = "Balnir Farmstead. The Balnir Farmstead is a derelict estate in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron. Once a working farm of the Balnir family, the lands now lie ruined and infested by wandering Scourge that slip past the Bulwark. For generations, the Balnir family worked their homestead in the rolling hills of eastern Tirisfal, and their garden of snapdragons still blooms among the ruins. When the Scourge swept through Lordaeron during the Third War, the farm was overrun and its people lost, leaving the buildings to rot. In the wake of the Third War, the ruins serve as a foothold for mindless Scourge slipping past the Bulwark. Forsaken deathguards watch the farm warily, while Undercity magi harvest surviving snapdragons from the garden to test how deeply plague corruption has crept into the soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_balnir-farmstead-e24412efd3f31930fa0a/1-0000.mp3", duration = 47.5167347, start = 0},
  },
}
P.transport["subzone:bandarion-keep"] = {
  hash = "99d14c",
  fullHash = "3bdf1f",
  text = "Bandarion Keep. Bandarion Keep is a fortified redoubt associated with Tyr's Watch, nestled in the western reaches of Tirisfal Glades near the Whispering Forest. Named in honor of Garek Bandarion, the outpost serves as an isolated bulwark amidst lingering threats across the woodland frontier. Its defenders contend with everything from hostile coastal murlocs to roving zealots and unstable undead. Situated near the secluded Whispering Forest in western Tirisfal Glades, Bandarion Keep stands as a solitary sentinel for the Forsaken. Named after Garek Bandarion, this stronghold is closely tied to Tyr's Watch. Quartermasters like Jorin Croge work diligently to keep the garrison supplied despite its remote and challenging position far from the bustling courtyards of the Undercity. Holding the keep is no quiet assignment. The outpost faces constant danger from Vile Fin murloc raids along nearby waters, probing skirmishes by the Scarlet Crusade, and stray, mindless Scourge thralls shambling through the gloom. Worse still are internal perils: certain paladins struggling to adjust to their unlife as Forsaken have succumbed to madness, turning their weapons against their own kindred.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bandarion-keep-68b80d985e6e1760eab6/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["subzone:beren-s-peril"] = {
  hash = "37d645",
  fullHash = "37d645",
  text = "Beren's Peril. Beren's Peril is a secluded mountain cavern tucked in the rocky hills southwest of Ambermill in Silverpine Forest. It serves as an entrenched redoubt for rogue Scourge loyalists serving the necromancer Thule Ravenclaw, plotting against the nearby Forsaken. Tucked away high in the crags southwest of Ambermill, Beren's Peril consists of a shadowed cave and winding mountain path hidden from the main roadway. Following the devastation of the Third War, rogue Scourge undead under the command of the renegade necromancer Thule Ravenclaw fortified this enclave. Rather than bowing to the Dark Lady or retreating north, Ravenclaw's thralls—regents, guardians, and drudgers—gathered here in secret to muster an assault against the Forsaken base at the Sepulcher. Their presence was uncovered by Forsaken scouts, turning the quiet cliffside into an active warzone for Horde operatives sent to eliminate the threat before an attack could materialize.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_beren-s-peril-dcf4f789e76bd46ef9ca/1-0000.mp3", duration = 54.1518367, start = 0},
  },
}
P.transport["subzone:blackthorn-ridge"] = {
  hash = "04cac5",
  fullHash = "04cac5",
  text = "Blackthorn Ridge. At Blackthorn Ridge, Razormane quilboar guard the southern Barrens north of Razorfen Kraul. Brine, an orc shaman, keeps watch from a camp above a pool of unusually pure mountain water. Blackthorn Ridge rises beside Razorfen Kraul, its slopes crowded with dense thickets of sharp briars. The Razormane quilboar claim the ground as ancestral territory, using the thorny barriers to ambush outsiders and skirmish across the southern Barrens. Travelers seek out the ridge despite the danger, drawn to Brine, a hermit orc shaman. His camp sits above a spring famed across Kalimdor for its clear, spiritually pure water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_blackthorn-ridge-89e20b8ecc8188a10a09/1-0000.mp3", duration = 38.3216327, start = 0},
  },
}
P.transport["subzone:bladefist-bay"] = {
  hash = "b75c90",
  fullHash = "0461f5",
  text = "Bladefist Bay. Bladefist Bay opens onto the Great Sea along eastern Durotar, just beyond Orgrimmar's gates. Craggy bluffs rise above its shore, with Azshara's southern coast across the water. Bladefist Bay meets the Great Sea along Durotar's northeastern edge. Rocky cliffs rise above its treacherous surf, just east of Orgrimmar, the Horde capital. Across the water to the north, Azshara's ancient red cliffs and ruins mark the far shore. The bay forms a boundary between Durotar and the open sea. Kargath Bladefist gave the bay its name. Chieftain of the Shattered Hand clan, he severed his own hand and replaced it with a blade during the old Horde's trials on Draenor. Skull Rock lies nearby, where cultists and hidden rogue networks work in the shadows. The coast recalls the fierce, ruthless legacy of the clan's chieftain.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bladefist-bay-f258510606f0cb125bf1/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["subzone:bloodhoof-village"] = {
  hash = "0fb75e",
  fullHash = "855a90",
  text = "Bloodhoof Village. Bloodhoof Village is a central tauren settlement resting along the banks of Stonebull Lake in Mulgore. Named in honor of the Bloodhoof tribe, it serves as the first major gathering hub for young hunters and braves journeying out from Camp Narache toward Thunder Bluff. Led by Baine Bloodhoof, the village coordinates local defense, trade, and traditional rites across the plains. Situated around the clear waters of Stonebull Lake, Bloodhoof Village is a bustling center of commerce, craft, and ceremony in central Mulgore. Young tauren departing their trials at Camp Narache arrive here to hone their skills before venturing onward to the great mesas of Thunder Bluff. It is also home to the patient breeders who tame wild kodo beasts for travel. Day-to-day governance and the defense of the region fall under Baine Bloodhoof, son of High Chieftain Cairne Bloodhoof. Under his watchful eye, braves are dispatched to secure the grasslands against aggressive wildlife, quilboar encroachers, and the shadowy presence of the Venture Company. Alongside Baine, spiritual guides such as Zarlman Two-Moons tend to the inner life of the tribe, directing novices through sacred journeys like the Rite of Vision.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bloodhoof-village-0c4cdd27f977de8a385b/1-0000.mp3", duration = 66.8995918, start = 0},
  },
}
P.transport["subzone:boulder-lode-mine"] = {
  hash = "bb8084",
  fullHash = "e4b10f",
  text = "Boulder Lode Mine. In the northeastern Barrens, the Venture Company tears into Boulder Lode Mine for its riches. Orcish banners and watchtowers mark a claim the Horde once held. Weathered orcish works frame the mine mouth, signs that the Horde once held or founded the claim. Now Venture Company overseers and enforcers answer to Boss Copperplug. The goblin syndicate strips the canyon for minerals, gems, and machinery, with little care for the land or its workers. Riches from the mine have drawn attention from Ratchet. Wharfmaster Dizzywig has sent mercenaries after a rumored massive emerald found in the tunnels. Engineers seeking to understand goblin machinery also know that Boss Copperplug keeps key operating manuals in his camp.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_boulder-lode-mine-c0b5f3344e1fd3d013a7/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["subzone:brambleblade-ravine"] = {
  hash = "9bd08d",
  fullHash = "9bd08d",
  text = "Brambleblade Ravine. Brambleblade Ravine is a rugged canyon cutting into the northeastern edge of Red Cloud Mesa. It serves as a fortified den for the Bristleback quilboar tribe, who persistently raid the nearby tauren settlement of Camp Narache. Young tauren braves are sent here to prove their strength and protect their homeland from these fierce interlopers. Carved into the sun-scorched earth of Red Cloud Mesa, Brambleblade Ravine is choked with dense, thorny briars and quilboar encampments. The Bristleback tribe uses this natural fortress as a staging ground for raids against Camp Narache, threatening the safety of young tauren coming of age. Bristleback shamans and warriors, led by Chief Sharptusk Thornmantle, dwell deep within the ravine among trained battleboars. For the Shu'halo, striking into the heart of the canyon is a crucial rite of passage and a grim necessity to secure the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brambleblade-ravine-d906b54229f77946ccbf/1-0000.mp3", duration = 51.3567347, start = 0},
  },
}
P.transport["subzone:bramblescar"] = {
  hash = "319923",
  fullHash = "2c1544",
  text = "Bramblescar. Across the southern Barrens, Bramblescar's Razormane wage war with the Bristleback across the Gold Road. Thick brambles fortify their settlement. Bramblescar is carved into the jagged briars of the southern Barrens. The thick, sharp thorns make a vital redoubt for the Razormane quilboar and deter casual wanderers. The tribe is fiercely territorial and hostile to outsiders. They skirmish with anyone who approaches, treating all who are not quilboar as intruders on land blessed by their ancient boar gods. Bramblescar sits in perpetual tension with Agama'gor, the Bristleback encampment directly across the Gold Road. The rival tribes wage an unrelenting war for dominion over the southern Barrens. Razormane warriors fight Horde travelers along the highway and repel Bristleback raiding parties, keeping them on constant, violent alert.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bramblescar-855b237f72c918bf6647/1-0000.mp3", duration = 50.5730612, start = 0},
  },
}
P.transport["subzone:brightwater-lake"] = {
  hash = "81d5fb",
  fullHash = "81d5fb",
  text = "Brightwater Lake. Brightwater Lake is the largest body of water in Tirisfal Glades, stretching across the mist-shrouded lowlands northeast of Brill. Once a tranquil retreat for the kingdom of Lordaeron, its waters now lie cold and dark, surrounding a central isle where an outcast necromancer conducts his forbidden research. Spanning the northern plains between the town of Brill and the Scarlet Watch Post, Brightwater Lake is a quiet and eerie landmark in the heart of Tirisfal. In the peaceful centuries under the Kingdom of Lordaeron, the lake served as a scenic country haven. Today, like the rest of the glades, its pristine character is long gone. The Plaguelands lie not far to the east, and the murky, chilled waters reflect only grey skies, withered trees, and the constant threat of roving murlocs and hostile undead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brightwater-lake-f98264812d26e4ca0d9e/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["subzone:brill"] = {
  hash = "7657f6",
  fullHash = "9c997a",
  text = "Brill. Brill is the primary Forsaken settlement in the heart of Tirisfal Glades, situated just north of the Ruins of Lordaeron. Once a prosperous human town, it now serves as the administrative and military hub for newly awakened undead stepping beyond the confines of Deathknell. Before the Third War, Brill was a lively village under the sway of regional nobles such as the Barov and Agamand families. That prosperity ended when Kel'Thuzad chose the area for the Cult of the Damned's earliest experiments with the Plague of Undeath. The devastating blight swept through the population so quickly that local militia were driven out, leaving a sprawling mass graveyard in its wake.\n\nNow rebuilt by the Forsaken under the leadership of Magistrate Sevren, the town retains its weathered Lordaeron architecture beneath an atmosphere of grim purpose. Brill functions as the regional command center, coordinating defenses against Scarlet Crusade incursions, roaming Scourge remnants, and native beasts warped by necromantic decay. Beyond local defense, Brill is an essential crossroads linking Tirisfal Glades to the wider Horde. Overhead, the goblin-operated zeppelin tower provides transit south toward Durotar and deep into Stranglethorn Vale. Within the settlement, Gallows' End Tavern serves not only as a dark shelter for travelers, but also as a makeshift laboratory where captured Scarlet zealots are interrogated and subjected to apothecarial testing.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brill-fa7ad7f30f8d6a127dae/1-0000.mp3", duration = 83.3306122, start = 0},
  },
}
P.transport["subzone:brill-town-hall"] = {
  hash = "6f3d1f",
  fullHash = "6f3d1f",
  text = "Brill Town Hall. Brill Town Hall is the administrative heart of the settlement of Brill in central Tirisfal Glades. Standing as the most prominent structure in town, it serves as the civic headquarters from which the Forsaken govern their local holdings and coordinate the defense of the glades. While much of Lordaeron lies shattered and ruined, Brill Town Hall remains standing as a functioning civic center under undead rule. Inside, Magistrate Sevren directs town affairs from his podium, handing out vital commissions and directives to Forsaken adventurers. Aside from the Defiler's Den in the Arathi Highlands, it is one of the only recognized town halls in the known world actively run by the Forsaken, serving as a bleak parody and functional continuation of old Lordaeron's municipal bureaucracy.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brill-town-hall-4083d38d45c22ba8b619/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["subzone:burning-blade-coven"] = {
  hash = "4cc8e8",
  fullHash = "17aebf",
  text = "Burning Blade Coven. In the northern cliffs of the Valley of Trials, the Burning Blade Coven threatens the Horde’s newest recruits. Corrupted cultists and summoned demons haunt the old mineral caves, using them as a staging ground for dark magic on Durotar’s doorstep. Dark rituals now trouble the caves along the Valley of Trials’ northern edge. Imps and lesser fiends spill from the cavern mouth, stirring chaos and threatening the young orcs and Darkspear trolls who train here for service to the Horde. The Burning Blade cult has entrenched itself deep inside, led by the shadowy warlock Yarrog Baneshadow. What was a testing wilderness is now an active battleground against demonic corruption. Before demons took root in the caves, local overseers hoped to harvest their raw materials for the settlement. Foreman Thazz'ril ventured inside on a mineral survey, but the cultists drove him out in haste, and he left valuable equipment behind. Driving back Baneshadow's coven is now the ultimate proving trial for aspiring warriors, rogues, and spellcasters before they are deemed ready to venture into greater Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_burning-blade-coven-9d28d08cbb8ee3a814c8/1-0000.mp3", duration = 63.1118367, start = 0},
  },
}
P.transport["subzone:camp-taurajo"] = {
  hash = "5bd430",
  fullHash = "5bd430",
  text = "Camp Taurajo. Camp Taurajo holds the eastern mouth of the pass into Mulgore. The tauren camp offers travelers an inn, supplies, mentors, and wind rider routes across the plains and central Kalimdor. At Camp Taurajo, you reach the eastern mouth of the pass into Mulgore. For young tauren leaving Bloodhoof Village, the camp is often their first glimpse of the wider Barrens. Dry scrubland and rugged mesas surround this outpost and trading hub. Hunters, leathercrafters, and field herbalists find shelter here, while wind riders connect the camp to Thunder Bluff, the Crossroads, and Freewind Post deeper south.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_camp-taurajo-2559cc5e72bd0d8e73fe/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["subzone:canals-undercity"] = {
  hash = "8e5c0e",
  fullHash = "8e5c0e",
  text = "Canals (Undercity). The Canals form a murky, circular moat winding between the distinct quarters of the Undercity. Filled with an unnatural, noxious green slime rather than fresh water, they serve as both a sewage system and a grim symbol of the Forsaken's subterranean stronghold. Carved into the subterranean depths beneath the ruins of Lordaeron, the Canals encircle the heart of the Undercity, dividing its quarters with wide channels of sluggish green sludge. While mortal cities channel flowing river water to clean their avenues, the Forsaken have filled these stone conduits with industrial refuse, chemical runoff, and alchemical waste. The liquid emits a faint, sickly glow and foul vapors, making it impossible to traverse by ordinary magical means like water walking. Despite the lethality of the slurry, desperate anglers occasionally haul bizarre, tainted curiosities from the muck.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_canals-undercity-696909f8b9887d645ad5/1-0000.mp3", duration = 50.677551, start = 0},
  },
}
P.transport["subzone:cavern-of-mists"] = {
  hash = "8bdf48",
  fullHash = "8bdf48",
  text = "Cavern of Mists. The Cavern of Mists is the expansive outer antechamber leading into the depths of the Wailing Caverns. Fed by subterranean geysers that erupt through the rock, its central pool and hanging fog harbor strange, mutated wildlife roaming just outside the portal threshold. Before descending into the true heart of the Wailing Caverns, travelers must navigate the Cavern of Mists. Thick, warm vapor hangs permanently in the air, fed by natural geysers erupting from the cavern floor into a deep central pool. Though it serves as an entryway, it is far from peaceful. Swarms of raptors, serpents, oozes, and semi-aquatic threshadons wander the ledges and waters, alongside notorious beasts like the hydra Trigore the Lasher. It provides adventurers an ominous preview of the unnatural growth festering deeper below.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cavern-of-mists-24cb433f0457f5500938/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["subzone:cleft-of-shadow"] = {
  hash = "351799",
  fullHash = "76305b",
  text = "Cleft of Shadow. Rogues, warlocks, and their teachers gather in the Cleft of Shadow beneath Orgrimmar. The caverns give them room to practice their arts under the Horde's watch. Below Orgrimmar, the Cleft of Shadow holds rogues of the Shadowswift Brotherhood and warlocks of the Darkfire Enclave. Thrall's Horde honors shamanism and strength of arms, yet its leaders make room for subtler arts. In these caverns, practitioners of poison and fel energy work away from the valley districts and under Orgrimmar's watch. At the Cleft's lowest point, a passage opens into Ragefire Chasm. Volcanic caves honeycomb the ground beneath Orgrimmar, and their danger draws defenders and sinister cultists to the cavern's edge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cleft-of-shadow-8e606e156631b611ec7a/1-0000.mp3", duration = 41.4302041, start = 0},
  },
}
P.transport["subzone:cold-hearth-manor"] = {
  hash = "627d29",
  fullHash = "627d29",
  text = "Cold Hearth Manor. Cold Hearth Manor is a blighted farmstead located just west of Brill along the main road of Tirisfal Glades. Once a bustling, hospitable estate known for bountiful crops, the outbreak of the Plague of Undeath wiped out its residents, leaving the surrounding fields choked with mindless Scourge. Today, the Forsaken have secured the main farmhouse as an outpost and waystation for travelers. Before the Third War, this homestead bore a reputation for warmth and hospitality, supporting rich harvests in the heart of Lordaeron. When the Plague swept through the kingdom, the entire family and their laborers succumbed, rising again as husks bound to the Scourge. While feral undead still stumble through the ruined fields, Forsaken forces managed to push the mindless dead out of the main farmhouse, reclaiming the structure to serve as a trading post and foothold along the road toward the eastern glades.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cold-hearth-manor-411f518c0688686fdc01/1-0000.mp3", duration = 50.442449, start = 0},
  },
}
P.transport["subzone:crag-of-the-everliving"] = {
  hash = "adb7a9",
  fullHash = "9387fe",
  text = "Crag of the Everliving. The Crag of the Everliving is a verdant cavern chamber nestled deep within the Wailing Caverns. Dominated by lush, corrupted flora and predatory plant creatures, it serves as the domain of the Fanglord Lord Pythas. Its towering upper reaches shelter the ancient entity after whom the crag is named. While much of the Wailing Caverns is carved of damp subterranean stone, the Crag of the Everliving bursts with unruly, twisted vegetation fueled by the Nightmare corrupting Naralex's slumber. Towering mossy platforms and winding paths are choked with Deviate Shamblers—living plant hulks prowling the undergrowth. Lord Pythas, one of Naralex's fallen disciples, watches over the crag's central reaches, having traded his noble druidic vows for the venomous rites of the Druids of the Fang. The chamber draws its name from Verdan the Everliving, a colossal, primordial plant elemental who resides in the crag's upper heights. Corrupted by the Emerald Nightmare that grips the cavern, Verdan now acts as a fearsome line of defense rather than a peaceful natural guardian. Beyond his towering form lurks Lord Serpentis, the self-proclaimed chief of the Fanglords, who oversees the sect's descent into serpentine madness.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crag-of-the-everliving-e50312049b77c4244369/1-0000.mp3", duration = 69.355102, start = 0},
  },
}
P.transport["subzone:cragpool-lake"] = {
  hash = "20297c",
  fullHash = "20297c",
  text = "Cragpool Lake. Cragpool Lake is a body of water tucked inside Windshear Crag in the Stonetalon Mountains. Looming above its dark waters sits a massive timber structure erected by the Venture Company. Nestled within Windshear Crag, Cragpool Lake lies directly beneath the towering logging apparatus built by the Venture Company. An enormous wooden structure spans above the water, serving as the vantage point from which Gerenzo Wrenchwhistle oversees operations across the mountain valley. Venture Company workers occupy the platforms overhead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cragpool-lake-9b4be49d139897042572/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["subzone:crossroads"] = {
  hash = "fbb431",
  fullHash = "04de94",
  text = "Crossroads. At Crossroads, Horde travelers meet where the Gold Road crosses the route from Ratchet to the Stonetalon Mountains. The outpost handles trade, military staging, and travel between Durotar, Mulgore, and the northern frontlines. Crossroads sits where the Gold Road meets the route from the goblin port of Ratchet into the Stonetalon Mountains. Its lodgings are modest, but travelers find wind rider masters, merchants, blacksmiths, and trainers beneath the watchtowers. For young warriors from Durotar or Mulgore, the outpost reveals how the new Horde links its far-flung fronts and supplies. Keeping order at Crossroads is a constant struggle. Plains raptors prowl close enough to steal payroll silver from the guard towers, while harpies, quilboar, and centaur tribes press against the perimeter. Neutral Ratchet lies nearby, and Ashenvale's contested forests are within reach. Alliance scouts often strike near the outpost's defensive barricades.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crossroads-a0fdaf8c3d8eab06a4e9/1-0000.mp3", duration = 55.0661224, start = 0},
  },
}
P.transport["subzone:crusader-outpost"] = {
  hash = "585b99",
  fullHash = "a84283",
  text = "Crusader Outpost. Crusader Outpost is a fortified watchtower perched atop the rugged hills of eastern Tirisfal Glades. Manned by zealous members of the Scarlet Crusade, it guards the approaches leading toward their stronghold at the Scarlet Monastery. From this height, Crusaders observe travel along the road and stand ready to repel any Forsaken incursion. Built into the bluffs overlooking the eastern road, the Crusader Outpost serves as a primary early-warning station for the Scarlet Crusade. From their elevated tower, sentries watch over movement between Brill and the eastern reaches of Lordaeron, ensuring that wandering undead or scouting parties are spotted long before reaching the Monastery gates. The tower also grants the garrison tactical flanking capability against any force seeking to march up the valley toward their holy bastion. Under the command of Scarlet officers like Captain Vachon, the garrison stationed here maintains unwavering vigilance. They see the surrounding woods not as sovereign territory of the Forsaken, but as unhallowed soil stolen from humanity by monstrosities. For travelers loyal to the Undercity, the outpost represents an ever-present ambush point where crossbow bolts and cleansing steel await anyone straying too close to the bluffs.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crusader-outpost-e8e5f0136ff4b61059ad/1-0000.mp3", duration = 71.0530612, start = 0},
  },
}
P.transport["subzone:crusader-s-outpost"] = {
  hash = "1721dd",
  fullHash = "a18e44",
  text = "Crusader's Outpost. Crusader's Outpost is a fortified scout tower manned by the Scarlet Crusade in western Tirisfal Glades. Situated adjacent to the Solliden Farmstead, it serves as the Crusade's westernmost position in all of Lordaeron. Its perilous distance from the main Scarlet bastions leaves its garrison isolated in the heart of hostile Forsaken territory. Perched inside the western Tirisfal hills just north of Deathknell, this stone tower represents the farthest reach of the Scarlet Crusade's power in Lordaeron. The garrison stationed here works in tandem with the surviving human laborers of the nearby Solliden Farmstead, attempting to hold back the encroaching undead. From the top of the tower, lookouts keep watch over the surrounding pumpkin fields and forest paths, vigilant against both roaming Scourge fiends and patrols from the Undercity. Holding the western frontier carries extreme risk. Cut off from their primary strongholds in the Scarlet Monastery and far to the east in Tyr's Hand, the crusaders at this outpost cannot expect swift reinforcements should an attack breach the palisade. Any siege by the Forsaken forces massing across Tirisfal means either holding the tower on their own or facing total annihilation before help can ever arrive.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crusader-s-outpost-ffcafb91ae1991591259/1-0000.mp3", duration = 72.0457143, start = 0},
  },
}
P.transport["subzone:darkspear-strand"] = {
  hash = "688187",
  fullHash = "688187",
  text = "Darkspear Strand. At Darkspear Strand, the tribe’s refuge begins on Durotar’s southern coast. The trolls came ashore after exile from the Echo Isles and built Sen'jin Village nearby under Vol'jin’s leadership. The Darkspear trolls came ashore here after losing the Echo Isles. When witch doctor Zalazane seized their home, survivors crossed the narrow waters and landed on this coast. They gathered just yards inland rather than scatter into Durotar’s hostile red wastes, and built Sen'jin Village. The strand looks across the surf toward the islands they still hope to reclaim.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_darkspear-strand-6ee121f548ec9ae9411c/1-0000.mp3", duration = 32, start = 0},
  },
}
P.transport["subzone:dawning-isles"] = {
  hash = "bcbfa8",
  fullHash = "8dc242",
  text = "Dawning Isles. The Dawning Isles are a cluster of low-lying islets situated within Lordamere Lake along the eastern edge of Silverpine Forest. Once idyllic retreats, they have succumbed to the blight of the Plague of Undeath and are overrun by aggressive murlocs. Before the Third War, the Dawning Isles were known as scenic keys resting on the calm, clear waters of Lordamere Lake. When the Plague of Undeath swept across Lordaeron, corruption seeped into the lake's shallows. The vegetation turned pallid and rotting, driving away idyllic peacefulness. Today, the Vile Fin murloc tribe dominates the muddy shores and tangled brush, aggressively defending their burgeoning colonies from anyone seeking to traverse the lake. Murlocs were not always the only danger on the isles. Bog beasts once prowled the blighted islets alongside them, but the bog beasts have since vanished. In their absence the Vile Fin population has swelled to the point that the murlocs now control the isles outright, turning what was once a quiet chain of keys into their stronghold on Lordamere Lake.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dawning-isles-bc22302cb2654a6a94f3/1-0000.mp3", duration = 60.8653061, start = 0},
  },
}
P.transport["subzone:dead-field"] = {
  hash = "ed3690",
  fullHash = "ed3690",
  text = "Dead Field. The Dead Field is a blighted, abandoned farmstead situated in northern Silverpine Forest. Once quiet rural farmland, it has been seized by the Rot Hide gnolls and transformed into a forward staging ground for Scourge forces. Repeated Forsaken attempts to clear the area have faltered under the command of the banshee Nightlash. Little remains of the original farmstead in the northern reaches of Silverpine Forest, its previous living occupants long lost to the Third War. Today, the ruined plot serves as a base of operations for the Rot Hide gnolls, who act as willing servants to the Scourge. As their numbers swelled, Deathstalker scouts passing through the region noted signs of imminent military mobilization threatening Forsaken supply lines and outposts. Small Forsaken assaults against the farm have repeatedly failed, turned back by the wailing apparition Nightlash—a banshee who manifests whenever her gnoll thralls are endangered.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dead-field-0083295d18ff55b0abbd/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["subzone:deadeye-shore"] = {
  hash = "87d73f",
  fullHash = "87d73f",
  text = "Deadeye Shore. Deadeye Shore lies windswept along Durotar’s eastern edge, east of Drygulch Ravine. Named for Kilrogg Deadeye, the Bleeding Hollow chieftain, its barren sands are roamed by raptors, scorpids, and feral boars. Deadeye Shore runs beneath central Durotar’s red bluffs, with sand and rocky outcrops that faintly resemble a skull missing an eye socket. The coast takes its name from Kilrogg Deadeye, the one-eyed Bleeding Hollow chieftain who fought in the First and Second Wars. No major settlement or military outpost holds the shore. It is far from peaceful: aggressive wildlife rules the sands, and Burning Blade cultists from nearby ravine hideouts have been seen prowling toward the water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_deadeye-shore-f522e80f9e199026003b/1-0000.mp3", duration = 39.8628571, start = 0},
  },
}
P.transport["subzone:decrepit-ferry"] = {
  hash = "7557a1",
  fullHash = "3b2fb7",
  text = "Decrepit Ferry. The Decrepit Ferry is a ruined dock on the eastern shore of Silverpine Forest that once provided passage across Lordamere Lake to Fenris Isle. Following the fall of Lordaeron, the ferry was destroyed, its operator murdered, and the shoreline overrun by undead and vicious Rot Hide gnolls. Before the Third War, this dock bustled with daily traffic across Lordamere Lake. Local farmers brought fresh produce down to the water, selling their crops directly to the wealthy lord of Fenris Isle and his household. For a modest fee, the ferryman carried trade goods, messengers, and visiting nobles back and forth between the mainland and the keep. That peaceful commerce ended abruptly when the Scourge swept through the kingdom. The ferryman was brutally killed, the boats were smashed, and the pier fell into decay. Today, the docks are a hazard to any traveler passing along the lake shore. With the ferry out of commission, Fenris Isle sits isolated across the water, while the ruins themselves crawl with ghouls, skeletal warriors, and roving Rot Hide gnolls. What was once an orderly point of transit has become another festering pocket of danger in Silverpine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_decrepit-ferry-15c34a258ca3cb24dd5c/1-0000.mp3", duration = 67.9706122, start = 0},
  },
}
P.transport["subzone:deep-elem-mine"] = {
  hash = "0ab3ca",
  fullHash = "0ab3ca",
  text = "Deep Elem Mine. Deep Elem Mine is an excavation site nestled in the heart of Silverpine Forest. Once an active operation, it was overrun when Archmage Arugal's dark magic swept through the region, transforming its miners into savage worgen. Situated central to Silverpine Forest, the Deep Elem Mine once served the living inhabitants of Lordaeron as an ordinary resource vein. When Archmage Arugal unleashed the lupine nightmare upon the forest, his feral curse spread deep into the tunnels. The laborers inside succumbed to the affliction, turning into vicious worgen who abandoned their pickaxes to claim the cavern as a predatory lair.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_deep-elem-mine-5fb6711df1dc5a09ade0/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["subzone:drag"] = {
  hash = "1a62df",
  fullHash = "4d5136",
  text = "Drag. In Orgrimmar, the Drag links the Valley of Strength, Valley of Honor and Valley of Wisdom. Crafters and traders line its shaded red-rock canyon, where the descent to the Cleft of Shadow also lies. The Drag runs between Orgrimmar’s red canyon walls, where crafters and traders fill the Horde capital’s streets. Unlike the Valley of Strength, with its military musters and commands, the Drag is where daily city life unfolds. High cliffs and hides shade the street, where tanning vats, alchemical cauldrons and tinkers’ gears fill the air with their sounds and smells. Craftsmen gather to practice their trades and teach aspiring adventurers. Their work ranges from leatherworking and tailoring to the goblin workshops of Nogg’s Machine Shop. Merchant storefronts and salvage houses line the Drag, beside the guarded entrance to the underground Cleft of Shadow. The street brings honest tradesmen together with shamans on their way to the Valley of Wisdom and secretive practitioners of dark arts. They cross paths beneath the canyon’s dim, dusty overhangs.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_drag-17a3d6e26219e6253804/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["subzone:dreadmist-den"] = {
  hash = "34a390",
  fullHash = "34a390",
  text = "Dreadmist Den. In the northern Barrens, Burning Blade cultists keep their rites beneath Dreadmist Peak. Red haze fills the cavern they use as a shrine to demons. Dreadmist Den cuts into the jagged slopes of Dreadmist Peak, where Burning Blade cultists gather in a dark sanctuary. Thick crimson vapor hangs through its stone tunnels, dimming the cavern in red twilight. Away from the Horde's watch in the plains below, the cult performs demonic rites, guards its blasphemous relics, and plots to spread corruption across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dreadmist-den-8581cc1b9112be2245d9/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["subzone:dreadmist-peak"] = {
  hash = "a09c25",
  fullHash = "a09c25",
  text = "Dreadmist Peak. Red haze cloaks Dreadmist Peak, northwest of the Crossroads in the Barrens. The Burning Blade cult keeps a hidden refuge on its crags. Dreadmist Peak rises above the Barrens, its crags swallowed by a dense red haze that dims the sky. At the crest and in the hollows below, Burning Blade cultists shelter warlocks and toxicologists. They poison nearby water and scheme against the new powers claiming central Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dreadmist-peak-ad1e60e70655f7a6b866/1-0000.mp3", duration = 25.7828571, start = 0},
  },
}
P.transport["subzone:dreamer-s-rock"] = {
  hash = "f71e26",
  fullHash = "f71e26",
  text = "Dreamer's Rock. Dreamer's Rock is a secluded natural sanctuary tucked deep within the Wailing Caverns past the Screaming Gully. Here lies the sleeping night elf druid Naralex, whose noble effort to revive the Barrens has instead birthed a living nightmare. It serves as both a sacred barrow chamber and the epicenter of the corruption mutating the surrounding subterranean ecosystem. Located in the heart of the Wailing Caverns, Dreamer's Rock functions much like an improvised barrow den. Here, the night elf druid Naralex entered a deep trance to tap the underground springs and channel the Emerald Dream into the arid soil of the Barrens. Instead of bringing life, his connection was seized by dark forces. The nightmare twisting his thoughts now spills physically into this chamber, twisting the local wildlife, turning his followers into the venomous Druids of the Fang, and manifesting terrifying aberrations into the waking world.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dreamer-s-rock-3bec1510965c2ebebe09/1-0000.mp3", duration = 52.7673469, start = 0},
  },
}
P.transport["subzone:dry-hills"] = {
  hash = "4c27aa",
  fullHash = "39a2d2",
  text = "Dry Hills. Witchwing harpies menace the Dry Hills, where greener slopes rise above the Barrens. The Dry Hills grow greener than the dry plains below, on the Barrens' northwestern edge beneath the Stonetalon Mountains. Travelers find little safety among the bluffs. Serena Bloodfeather leads the Witchwing harpies from their roosts along the crags. Their raiding parties swoop down on supply caravans along the northern Gold Road. Abandoned orcish fortifications and derelict siege engines lie rotting in the brush. Witchwing harpies strike out from the hills to bleed trade routes and harass nearby settlements, so the Horde keeps a standing bounty on their feathers. In the rocky ravines, their nests and roosts are heavily defended. Hecklefang hyenas prowl there, and fierce Sunscale raptors hunt across the highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dry-hills-0269e7c7407a3f31341a/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["subzone:drygulch-ravine"] = {
  hash = "1821a1",
  fullHash = "59786a",
  text = "Drygulch Ravine. Dustwind harpies hold Drygulch Ravine, where they menace nearby supply caravans. The gorge lies among eastern Durotar's rocky bluffs, reached by a cave passage from Razorwind Canyon or a perilous drop from above. In the crags east of Orgrimmar, Drygulch Ravine forms a sheltered depression and a lawless pocket of Durotar. A cramped natural tunnel from Razorwind Canyon is its only ground-level route. Dustwind harpies roost along the steep cliffs, where they nest their broods and stockpile goods stolen from Horde supply trains on the regional trails. Dustwind harpies are the ravine's immediate danger. Their matriarchs fiercely defend clutches of eggs tucked along the high ledges. Horde scouts often send young warriors to thin the flock, recover plundered trade crates, and break the harpies' hold on the ravine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_drygulch-ravine-5dac95c22658822d3332/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["subzone:dustwind-cave"] = {
  hash = "f4b0c3",
  fullHash = "b196d1",
  text = "Dustwind Cave. Burning Blade initiates train in Dustwind Cave, high above Razorwind Canyon northeast of Razor Hill. The cave is both a training ground and a covert refuge for the cult in Durotar. Dustwind Cave overlooks Razorwind Canyon, close to Razor Hill and a perilous threat to the town. The Burning Blade trains new recruits here beneath the notice of Horde authorities. Cultists teach initiates forbidden dark magic and demonology, preparing them to undermine the young orcish realm from within Durotar's borders. Those who enter Dustwind Cave risk the Burning Blade's corruptions. Cultists channel volatile dark arts, including felblood afflictions. Their work shows how firmly the cult holds to the demonic legacy Thrall fought to banish. Clearing the cabal from the cave matters to Durotar's fragile peace.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dustwind-cave-9f923fa7bf8e3175fbcf/1-0000.mp3", duration = 46.7330612, start = 0},
  },
}
P.transport["subzone:echo-isles"] = {
  hash = "e70f1a",
  fullHash = "6cc940",
  text = "Echo Isles. The Darkspear have fled the Echo Isles, leaving their home under Zalazane's control. The tribe first settled here after crossing the Great Sea with Thrall, but now seeks to reclaim the islands. The Darkspear made the Echo Isles their home after fleeing across the Great Sea with Thrall. Their peace broke when Grand Admiral Daelin Proudmoore's naval forces invaded Durotar during Kul Tiras' attack. The trolls drove back Proudmoore's fleet, but another threat rose within the tribe. Zalazane, one of their witch doctors, seized dark arts and enslaved the minds of his kin. Chieftain Vol'jin and the free Darkspears fled the islands once more, finding temporary refuge across the narrow strait at Sen'jin Village. Aggressive predators, tainted wildlife, and Zalazane's thralls now overrun the tropical islands. The rogue witch doctor uses malevolent hexes, voodoo fetishes, and ju-ju heaps across the isles to bend beasts and captive trolls to his will. Vol'jin's scouts and warriors set out from their camp at Darkspear Strand on frequent sorties. They seek the remains of their fallen and a chance to strike down the mystic who stole their home.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_echo-isles-422c3994e3d5cf18d3c4/1-0000.mp3", duration = 69.0677551, start = 0},
  },
}
P.transport["subzone:elder-rise"] = {
  hash = "c25d39",
  fullHash = "5d3a20",
  text = "Elder Rise. Elder Rise sits directly east of Thunder Bluff's central plateau, reachable across long suspension bridges from both the High and Middle Rises. It serves as the spiritual heart of the tauren capital, hosting the Cenarion Circle, tauren druids and priests, and the governing Council of Elders. Connected to the main mesas by swaying rope bridges, Elder Rise is dedicated to quiet reflection, sacred wisdom, and civic governance. Tauren druids and priests gather here to teach acolytes the ways of nature and spiritual devotion. High atop this mesa resides Arch Druid Hamuul Runetotem, the revered leader who brought druidism back to the tauren people and forged close ties with the Cenarion Circle. Alongside these wild sanctuaries stands the Hall of Elders, where tribal leaders convene to deliberate on matters facing their fledgling capital. Despite its role as a peaceful sanctuary, political tension lingers over the rise. Magatha Grimtotem, elder matriarch of the secretive and haughty Grimtotem tribe, maintains her residence in a hut positioned between the two bridges. While Cairne Bloodhoof extends hospitality and formal council seats to all tauren lineages, her watchful presence serves as a constant reminder that not every tribe embraces the Bloodhoof's pacifist ideals or unquestioning alliance with the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_elder-rise-77513afc937e7ea3b41d/1-0000.mp3", duration = 75.5461224, start = 0},
  },
}
P.transport["subzone:faol-s-rest"] = {
  hash = "ea0320",
  fullHash = "d5a0a5",
  text = "Faol's Rest. Faol's Rest is a quiet, neglected gravesite situated in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It was erected as the tomb of Archbishop Alonsus Faol, the revered spiritual patriarch who founded the Knights of the Silver Hand. Today, untended beneath the blighted canopy, it serves as a release graveyard for those who perish near the monastery. Before the Third War devastated Lordaeron, this secluded hollow was a place of solemn pilgrimage. It holds the stone tomb of Archbishop Alonsus Faol, who led the Church of the Holy Light through the dark days of the Second War and instituted the order of paladins to protect humanity. Faol passed away peacefully prior to the arrival of the Scourge, spared the mortal agony of seeing his kingdom fall. In those brighter years, mourners regularly journeyed up the road from Capital City to leave offerings and pay respects to the beloved patriarch. When the Plague of Undeath swept across Lordaeron, Tirisfal withered, and the pilgrims vanished. Today, the monument sits abandoned and cracked in the shadows beneath the Scarlet Monastery's high bluffs. The wild brush has reclaimed the pathways, and the tomb itself lies still amid the damp mist. For adventurers striving against the zealots of the Scarlet Crusade or the lingering terrors of Tirisfal, this forgotten resting place now serves primarily as a quiet threshold where fallen spirits briefly regroup before returning to the fray.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_faol-s-rest-a237b01a0c49331cb757/1-0000.mp3", duration = 87.0922449, start = 0},
  },
}
P.transport["subzone:far-watch-post"] = {
  hash = "4a6ad9",
  fullHash = "4a6ad9",
  text = "Far Watch Post. Horde defenders hold Far Watch Post west of the Southfury River bridge, guarding the homeland's frontier. The outpost protects vital trade caravans from quilboar packs and Alliance incursions. Far Watch Post guards the western foot of the bridge from Durotar into the Barrens. You enter a vast, arid savannah, where this is the first sign of Horde authority. The settlement is spare but built for readiness, with an orcish watchtower, a burrow, and siege catapults aimed across the plains. South of the main road, peons tend riding wolves for messengers or reinforcements. The post keeps the supply road to Crossroads secure, screening travelers and turning back raids by roaming quilboar tribes and Alliance scouts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_far-watch-post-181517461374580ae421/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["subzone:fenris-isle"] = {
  hash = "ecd876",
  fullHash = "ecd876",
  text = "Fenris Isle. Fenris Isle is a large, mist-shrouded island in Lordamere Lake, bordering the eastern edge of Silverpine Forest. Once home to a bustling Lordaeron military stronghold, the island now lies under the iron grip of undead Rot Hide gnolls and a rogue Scourge necromancer. Before the Third War devastated northern Lordaeron, Fenris Isle served as a vital outpost for the kingdom, anchored by Fenris Keep. When the Scourge tore through the realm, the garrison was slaughtered or fled into exile, leaving the island abandoned to the dead. In the years since, the island became a stronghold for the Rot Hide gnolls—vile, plague-ridden creatures who established a crude empire across the lake's shores. The Forsaken of Silverpine Forest keep a vigilant watch on the island, viewing its entrenched inhabitants as a severe threat to their northern territories.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fenris-isle-8e8d0dd6651476f0deb6/1-0000.mp3", duration = 49.0840816, start = 0},
  },
}
P.transport["subzone:fenris-keep"] = {
  hash = "075952",
  fullHash = "075952",
  text = "Fenris Keep. Fenris Keep is an isolated stone fortress situated atop Fenris Isle in the heart of Lordamere Lake. Once a strategic stronghold housing Lordaeron troops, it has fallen into the hands of the Scourge under the rogue mage Thule Ravenclaw. Before the Third War, Fenris Keep held strategic importance for the Kingdom of Lordaeron, stationing a sizable contingent of troops to safeguard Lordamere Lake. When the undead Scourge swept across the land, the island fortress was overwhelmed along with the rest of the realm. Rather than crumbling into forgotten ruin, it was seized by Thule Ravenclaw, a traitorous former wizard of the Kirin Tor. Ravenclaw allied himself with the Scourge, subjugated the resident gnolls with foul necromancy to create the ravenous Rot Hide pack, and entrenched himself deep inside the keep's stone halls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fenris-keep-0e468d73c52b9c68d8cd/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["subzone:field-of-giants"] = {
  hash = "6539dd",
  fullHash = "1f246b",
  text = "Field of Giants. The Field of Giants spreads across the southern Barrens, from Camp Taurajo to Dustwallow's marshes. Towering kodo, thunder lizards, and other great beasts graze its dry scrub, while silithids make the plain more dangerous. The Field of Giants follows the southern Gold Road, far from the Barrens' better-defended north. Wooden watchtowers along the road sit largely abandoned, while great herds roam the open flats. Hunters and naturalists come to see Kalimdor's enormous beasts, but the land is not safe. Dwarven excavators from Bael Modan dig aggressively to the south, and a more sinister threat has begun burrowing underground. Silithid hives have recently broken through the ground across the Field of Giants. They mark the northernmost known sighting of these ravenous creatures in Kalimdor. Their strange mounds and aggressive swarms have alarmed the Horde. Korran, a troll scout from the Crossroads, and Ruga Ragetotem, a tauren warrior at Camp Taurajo, urge adventurers to investigate the hives and learn what draws these horrors so far from the deep deserts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_field-of-giants-cc2152be01b87d48bd3f/1-0000.mp3", duration = 63.9216327, start = 0},
  },
}
P.transport["subzone:forgotten-pools"] = {
  hash = "62332d",
  fullHash = "b640d9",
  text = "Forgotten Pools. The Forgotten Pools draw wildlife, Kolkar centaur, and the Horde into a contest for water in the northern Barrens. Northwest of the Crossroads, subterranean springs feed an oasis amid the dry savanna. Fresh water gathers in the Forgotten Pools, where thick reeds, palm trees, and Laden Mushrooms grow beside the parched Barrens. Plainstriders, snapjaw turtles, and zhevras come to drink. Kolkar centaur keep a camp along the banks and guard the water from travelers, bringing them into conflict with Horde travelers from the Crossroads. Wildlife, Kolkar, and the Horde all contend for the oasis. Deviate Fish thrive in the Forgotten Pools, one of the region’s rare surface waters where they can be found. Their presence hints at deeper ties to the strange transformative energies altering the Barrens’ water table. Horde naturalists and scouts watch the waters and unusual fungi along the banks, wary of what may be seeping into the soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forgotten-pools-fb4f4f7f918cadd009cd/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["subzone:fray-island"] = {
  hash = "a45c2f",
  fullHash = "9a30b3",
  text = "Fray Island. Warriors gather on Fray Island, just off the Merchant Coast of the Barrens. The rocky islet holds a rough training ring where fighters from across Azeroth test their skill. Fray Island lies off the eastern bluffs of the Barrens, beyond the watchful eyes of Orgrimmar and Theramore. Warriors of every race and creed train here. At the island's heart, Klannoc Macleod oversees a fighting arena where seasoned fighters and raw recruits meet in brutal brawls. The ring on Fray Island follows a simple code of martial combat, despite the hostile waters around it. Warriors come at their trainers' direction to face The Affray, a grueling gauntlet against waves of challengers that ends with a bout against champion Big Will. Here, Horde and Alliance allegiance gives way to strength and martial discipline.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fray-island-75356a34fdef70b7ad02/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["subzone:gallows-end-tavern"] = {
  hash = "40c938",
  fullHash = "3fae5b",
  text = "Gallows' End Tavern. Gallows' End Tavern is the principal inn of Brill and the heart of Forsaken hospitality in Tirisfal Glades. Beyond offering shelter and spirits to weary travelers, it serves as an essential hub for class mentors, trade instructors, and covert interrogations. Standing prominently along the road in Brill, Gallows' End Tavern serves as the primary gathering place for newly awakened Forsaken leaving Deathknell and journeying south toward the Undercity. Despite their undead condition, Forsaken still frequent its halls for fellowship, trade, and refuge. The inn houses various class instructors—guiding young warriors, priests, mages, rogues, and warlocks—as well as vendors and medical practitioners. Beneath the creaking floorboards and tavern laughter lies a far grimmer purpose. Down in the cellars, the Forsaken keep prisoners of war bound and guarded away from public view. Among them are a captured Scarlet Zealot and a Dwarven Mountaineer, held beneath the tavern for interrogation and experimentation as the Forsaken fight to secure their borders against both zealous crusaders and Alliance scouts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gallows-end-tavern-3e893ad6154ce802f088/1-0000.mp3", duration = 65.1232653, start = 0},
  },
}
P.transport["subzone:garren-s-haunt"] = {
  hash = "bf3c2a",
  fullHash = "b4c037",
  text = "Garren's Haunt. Garren's Haunt is an abandoned farmstead nestled in northern Tirisfal Glades. Once a prosperous human homestead, the farm fell to ruin when the Scourge wiped out the Garren family, leaving the overgrown grounds overrun by feral Rot Hide gnolls. Before the Third War, this farmstead supported a family and produced bountiful harvests under the Kingdom of Lordaeron. When the Plague of Undeath swept across the countryside, the Scourge descended upon the farm and slaughtered Garren and his kin. Today, the fields lie gray and withered, the farmhouse and barn decaying under the perpetual gloom of Tirisfal. Rather than standard Scourge patrols, Garren's Haunt has been claimed by the Rot Hide gnolls—a pack of undead-tainted scavengers led by the vicious Maggot Eye. These scavengers aggressively defend their reclaimed territory, picking clean whatever remains of the farm and savaging any travelers or Forsaken patrols passing along northern Tirisfal.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_garren-s-haunt-97f15af41744eb9340db/1-0000.mp3", duration = 55.9542857, start = 0},
  },
}
P.transport["subzone:gates-of-orgrimmar"] = {
  hash = "ed08c0",
  fullHash = "c8c523",
  text = "Gates of Orgrimmar. At Orgrimmar's southern gate, timber and iron guard the entrance cut into northern Durotar's red rock. The passage leads from the arid wastes to the Valley of Strength, the capital's busy commons. The gate proclaims the Horde's endurance and strength in war. Orgrimmar's main gate guards the great chasm cut into the mountains around the city. Towering wooden palisades, iron spikes, and watchtowers fortify the entrance. Travelers coming from Razor Hill and Durotar's scrublands find a grand welcome and a warning to any who threaten the new Horde. Armed Orgrimmar Grunts patrol the approach and watch everyone entering the city. Beyond the gate's shadowed arch, you enter the Valley of Strength, Orgrimmar's civic and martial heart. The tunnel narrows the way for envoys, merchants, and warriors, with sentries watching those who pass. Here stands Warchief Thrall's dream of a secure refuge carved from the harsh desert, where the Horde's many peoples can walk together without fear.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gates-of-orgrimmar-ad1103d80fafd9bc93ba/1-0000.mp3", duration = 58.3053061, start = 0},
  },
}
P.transport["subzone:gold-road"] = {
  hash = "c08f50",
  fullHash = "6b83ec",
  text = "Gold Road. Horde caravans and warriors travel the Gold Road through the Barrens. It runs from Mor'shan Rampart on the border of Ashenvale, past the Crossroads, toward the south. The Gold Road is a long dirt highway through the center of the Barrens. Near its northern end, Mor'shan Rampart and Mor'shan Base Camp guard against night elf incursions from Ashenvale. Farther south, an eastern roadway connects directly to Durotar before the Gold Road reaches the Crossroads. Beyond the settlement, it passes the waters of local oases and the foothills near the Wailing Caverns. The northern span ends at a dried-up riverbed, where travelers enter the more dangerous southern Barrens. The Gold Road carries Horde trade and military movements between Kalimdor's central territories, but danger follows its length. Quilboar tribes, centaur warbands, plainstriders, and lions threaten supply caravans and lone messengers. The Horde spends considerable resources placing scouts and warriors along the road. Even so, travelers leave the safety of major outposts armed and alert.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gold-road-dcb826909316720abbd1/1-0000.mp3", duration = 63.0334694, start = 0},
  },
}
P.transport["subzone:golden-plains"] = {
  hash = "b5de2d",
  fullHash = "b5de2d",
  text = "Golden Plains. The Golden Plains form a vast, sun-drenched basin stretching southeast of Thunder Bluff in central Mulgore. Cherished by the tauren, these sweeping grasslands serve as prime hunting territory and a vital grazing habitat for wandering herds of kodo. Spreading out beneath the towering mesas of Thunder Bluff, the Golden Plains represent the untamed heart of Mulgore. The shifting sea of golden and green grass offers an abundant sanctuary for local wildlife, making it one of the most treasured traditional hunting grounds of the nomadic tauren. Broad kodo herds roam across the rolling basin, while hunters share stories of legendary quarry, most notably the great kodo Arra'chea, who wanders quietly through the tall stalks.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_golden-plains-badeed2deba76a7782e7/1-0000.mp3", duration = 41.195102, start = 0},
  },
}
P.transport["subzone:greymane-wall"] = {
  hash = "f74ddc",
  fullHash = "f74ddc",
  text = "Greymane Wall. The Greymane Wall is a massive stone bulwark spanning the southern frontier of Silverpine Forest. Built by King Genn Greymane after the Second War, it seals the kingdom of Gilneas away from the outside world behind impenetrable, locked gates. Following the Second War, King Genn Greymane grew resentful of the Alliance of Lordaeron, particularly the taxes required to maintain the orc internment camps. Deciding Gilneas had given enough of its coin and blood for foreign troubles, Greymane withdrew from the Alliance and ordered a colossal barrier raised across the head of the peninsula. When the Third War brought the Plague of Undeath and countless desperate refugees to its foot, the gates remained pitilessly barred.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_greymane-wall-bd1dbf85faa721ee302b/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["subzone:grol-dom-farm"] = {
  hash = "113550",
  fullHash = "fc9bbd",
  text = "Grol'dom Farm. Along the road from Durotar to the Crossroads, Grol'dom Farm raises swine in the northern Barrens. Kranal Fiss and his family work the homestead, despite constant harassment from aggressive local quilboars. Established after Durotar was settled, Grol'dom Farm is an early Horde effort to farm the dry Barrens. Kranal Fiss and his children tend the homestead and raise pigs, while Razormane quilboar raiders prowl the nearby ridges. The farm supplies sustenance to the emerging orcish nation, though life here remains lonely and rugged. Grol'dom Farm is a pig farm, but its purpose reaches beyond that daily work. Kranal Fiss knows the elemental rites and plays a key part in guiding young shaman through their trials. Horde initiates on the spiritual path hold the farm in quiet regard, and seekers traveling west from Orgrimmar are regularly directed here to learn how to commune with the primal spirits of fire.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grol-dom-farm-ebf1473b80d8bc09941c/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["subzone:grommash-hold"] = {
  hash = "5773b2",
  fullHash = "ed7b1d",
  text = "Grommash Hold. In Orgrimmar's Valley of Wisdom, Grommash Hold commands the red cliffs as Thrall's seat. Named for Grommash Hellscream's sacrifice, it is the political heart of the new Horde. Grommash Hold rises from the cliffs of the Valley of Wisdom, where Thrall receives emissaries, petitioners, and warlords. Its thick stone halls stay dim and chilly, a choice meant to keep those who attend his audiences alert and sober. Thrall weighs the defense of Kalimdor with veteran counselors such as Eitrigg, while racial chieftains like Vol'jin visit the hold. Outside the fortress, Mannoroth's shattered armor and horned skull hang from the trunk of an ancient tree. The memorial honors Grom Hellscream, who gave his life to slay the pit lord in Ashenvale. It recalls the orcs' freedom from the demonic blood curse and warns against returning to reckless savagery.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grommash-hold-2675b5d7cf0c6381c7ab/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["subzone:gunther-s-retreat"] = {
  hash = "78b415",
  fullHash = "78b415",
  text = "Gunther's Retreat. Gunther's Retreat is an isolated island sanctuary set in Brightwater Lake in central Tirisfal Glades. It serves as the refuge of Gunther Arcanus, a renegade necromancer who broke free from the Scourge through raw willpower. Distrustful of all outsiders, the recluse surrounds his campsite with loyal undead minions to keep intruders away. Situated amid the misty waters of Brightwater Lake, Gunther's Retreat is an unassuming island encampment easily mistaken for another pocket of the Scourge. Its master, Gunther Arcanus, achieved what few mortal sorcerers could: when raised in undeath, his arcane mastery allowed him to tear away his soul from the Lich King's iron grip without any outside help. Mistrusting everyone, Gunther assumed the rest of the undead wandering Lordaeron were still puppets of the Scourge. He retired to this lonely isle to practice his craft in peace, posting zombie sentinels to tear apart anyone who crosses the water.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gunther-s-retreat-de5f9663ec9822f9a762/1-0000.mp3", duration = 55.3012245, start = 0},
  },
}
P.transport["subzone:hall-of-legends"] = {
  hash = "1a8a9d",
  fullHash = "6b743c",
  text = "Hall of Legends. In Orgrimmar's Valley of Strength, Horde champions gather in the Hall of Legends. Behind its guarded entrance, proven officers confer over battle plans and arm themselves with weapons and armor from conflicts across Azeroth and beyond. Horde officers gather in the Hall of Legends, off the Valley of Strength's busy avenues. Beyond its guarded entrance, strategists and delegates from across the faction confer over maps of contested lands and the military standing of both factions. Among them are Chieftain Earthbind of Thunder Bluff, Blood Guard Hini'wana of the Darkspear, and Advisor Willington of the Undercity. Only warriors who have reached the rank of Stone Guard or higher may enter and claim the arms and spoils kept within. The Hall of Legends holds armories stocked with battle-tested wargear for proven Horde officers. For those rising through the military ranks, its weapons and armor mark honor, martial skill, and victory hard won.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-legends-2b24f9304833d502d526/1-0000.mp3", duration = 53.524898, start = 0},
  },
}
P.transport["subzone:hall-of-the-brave"] = {
  hash = "7d23f2",
  fullHash = "7d23f2",
  text = "Hall of the Brave. Warriors train and gather at the Hall of the Brave in Orgrimmar's Valley of Honor. The barracks and guild house serves the Horde's front-line combatants, drillmasters, and battlemasters. The Hall of the Brave overlooks the Valley of Honor's waters and training rings. Veteran officers and seasoned warriors teach initiates melee combat, stances, and discipline. Training dummies and weapons line the hall, where battlemasters organize combatants for major military engagements across Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-the-brave-e6298f40cac5298308fc/1-0000.mp3", duration = 26.0440816, start = 0},
  },
}
P.transport["subzone:hidden-path"] = {
  hash = "cf7e7a",
  fullHash = "40da32",
  text = "Hidden Path. In Durotar, the Hidden Path climbs above the Valley of Trials toward Spirit Rock. Young shaman follow it to prove their awareness and discipline, while its high reaches look west toward the Barrens. The Hidden Path climbs through red peaks above the Valley of Trials, hard to spot from the canyon floor. Mentors send young shaman along it to test their awareness and discipline before they commune with the spirits at Spirit Rock. From the highest reaches, you can see west across the rolling savannas of the Barrens. The Hidden Path also cuts through the natural defenses around the valley. A low pass leads toward Ratchet and the road to Orgrimmar. It bypasses the usual canyon checkpoints, leaving defenders wary that Alliance infiltrators could use the quiet trail to reach the Horde's proving grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hidden-path-7148be62eb6b132ef973/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["subzone:high-rise"] = {
  hash = "899d50",
  fullHash = "899d50",
  text = "High Rise. The High Rise is the uppermost tier of Thunder Bluff's central mesa, crowning the tauren capital. It hosts a bustling amphitheater centered around a communal bonfire alongside seasoned artisans, weapon merchants, and culinary masters. Unlike the lower tiers, this summit relies entirely on suspension rope bridges and the wind rider roost for travel. The High Rise perches atop Thunder Bluff's core plateau, catching the open winds high above the rolling plains of Mulgore. A focal gathering point for the united tribes, it centers around an open-air amphitheater and fire pit where citizens listen to important tribal announcements and fateful decisions. The surrounding tents and wooden stalls house renowned merchants, armories, and culinary trainers, including Aska's Kitchen and Mountaintop Bait & Tackle. While the lower tiers connect directly to Mulgore's prairie floor via massive wooden elevators, the High Rise stays aloft, accessible primarily through the wind rider roost and sweeping rope bridges linking to the neighboring Elder Rise and Hunter Rise.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_high-rise-272f298341147963dba4/1-0000.mp3", duration = 61.1787755, start = 0},
  },
}
P.transport["subzone:hunter-rise"] = {
  hash = "82a031",
  fullHash = "2dff60",
  text = "Hunter Rise. Hunter Rise is one of the elevated mesas making up the city of Thunder Bluff, situated just south of the central bluff. It serves as the primary training and gathering ground for the tauren's warriors, hunters, trackers, and skinners. Across its windswept platforms, young braves hone their martial skills and prepare for combat. Connected to the neighboring bluffs by swaying rope bridges, Hunter Rise is dedicated to the martial traditions of the tauren. It is anchored by the Hunter's Hall, where experienced marksmen, trackers, and warriors pass down their discipline to younger generations. Surrounding the lodge are practice grounds outfitted with training dummies, weapon racks, and skinning posts, making it a bustling center for those who live by spear, bow, and hide. Beyond hunting wild game across the plains of Mulgore, the inhabitants of Hunter Rise help ensure the defense of Thunder Bluff and the wider Horde. Battlemasters stationed along the rise recruit seasoned fighters to answer the call of skirmishes against Alliance incursions across contested battlegrounds. It remains an essential rallying point for anyone sworn to protect the herd.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hunter-rise-01d154baa1f770c3d491/1-0000.mp3", duration = 64.0261224, start = 0},
  },
}
P.transport["subzone:ivar-patch"] = {
  hash = "a329fb",
  fullHash = "a329fb",
  text = "Ivar Patch. The Ivar Patch is a blighted pumpkin farm located in northern Silverpine Forest. Once a thriving agricultural homestead of Lordaeron, its residents were wiped out during the Third War and transformed into ravenous, mindlessly hostile ghouls. Before the Third War swept through Lordaeron, this pumpkin patch was a prosperous homestead owned by a farmer named Ivar, who employed a lively crew of farmhands and servants. When the Scourge unleashed the Plague of Undeath across the countryside, the farm was consumed completely. Rather than rising with their minds intact like the free-willed Forsaken, Ivar, his family, and his laborers were reduced to rotting, feral ghouls bound to prowl the ruined soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ivar-patch-dc0335aac809daebdbb0/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["subzone:jaggedswine-farm"] = {
  hash = "809fa5",
  fullHash = "aaddd4",
  text = "Jaggedswine Farm. South of Orgrimmar's main gate, Jaggedswine Farm raises swine for the capital. Its shed, pen, and watering hole serve the Horde's nearby stronghold. Jaggedswine Farm shows the harsh work of feeding an urban stronghold like Orgrimmar. Durotar's red soil supports little farming, so hardy livestock helps feed the city's warriors and laborers. A timber storehouse, a broad wooden pen, and a natural watering hole anchor the farm. Swine are herded, bred, and butchered here to keep the Horde's granaries supplied. Swineherds and patrolling Orgrimmar Grunts visit the farm, though the dry heat can leave it looking half-tended. Wild and mature swine roam inside and beyond the enclosures, sometimes testing nearby guards. The farm stands at the edge of the valley approach to the capital, an unassuming but necessary part of Durotar's daily supply work.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jaggedswine-farm-15dfdbaaf1f185fbdd26/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["subzone:kodo-rock"] = {
  hash = "6ab2c5",
  fullHash = "79a932",
  text = "Kodo Rock. Kodo Rock is a natural stone monument located in the plains of Red Cloud Mesa, between Camp Narache and Brambleblade Ravine. Standing quietly amid the grasses of Mulgore, it serves as an early pilgrimage site for young tauren shamans learning to commune with the spirits of the earth. Because of its modest silhouette against the rolling landscape, travelers must keep a keen eye out to spot it. Situated roughly halfway along the path connecting Camp Narache to the hostile quilboar territory of Brambleblade Ravine, Kodo Rock is marked by a patch of worn earth at its base. While it lacks the sheer grandeur of the towering bluffs surrounding Red Cloud Mesa, its distinct profile resembles the revered kodo beasts that wander the grasslands. For wandering tribesfolk, it acts as a quiet natural beacon in the windswept plains of Mulgore. To the Shu'halo, natural formations often carry spiritual weight. Kodo Rock holds special reverence for young tauren shamans beginning their spiritual walk. Novices are directed here on early rites of passage, using the solitary stone monument as a sacred grounds to commune with elemental forces and honor the natural world before venturing into more perilous reaches of the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_kodo-rock-e3fe61ddac2b1b66abd9/1-0000.mp3", duration = 71.4710204, start = 0},
  },
}
P.transport["subzone:kolkar-crag"] = {
  hash = "e81edd",
  fullHash = "e81edd",
  text = "Kolkar Crag. Kolkar centaur watch the southern Durotar flats from Kolkar Crag, a gorge they have claimed for their raids. Warlord Kolkanis leads them against nearby Horde settlements. Kolkar centaur hold a fortified gorge in southern Durotar. They guard its natural choke points and watch the surrounding flats for openings in orc and Darkspear holdings. Scouts and marauders range from the crag, probing those defenses. For young warriors training in the Valley of Trials and patrols along the southern coast, this is the nearest organized centaur threat.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_kolkar-crag-97b355a6ebea2791d523/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["subzone:lushwater-oasis"] = {
  hash = "09e12c",
  fullHash = "09e12c",
  text = "Lushwater Oasis. South of the Crossroads, Lushwater Oasis is one of three life-giving watering holes in the Barrens. Kolkar centaur threaten travelers who come for its water, while the tainted pools draw anglers seeking Deviate Fish. Lushwater Oasis lies a short march south of the Crossroads, beneath the Barrens sun. Its palms and springs draw thirsty beasts, but Kolkar centaur hold the banks and ambush wildlife and travelers. The oasis also marks the entrance to the Wailing Caverns. Energies from its underground passages taint the pools, where unnatural creatures and strange mutations take hold.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_lushwater-oasis-118fb73d92fc9ccfc5b4/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["subzone:magic-quarter"] = {
  hash = "04a440",
  fullHash = "c12adf",
  text = "Magic Quarter. The Magic Quarter is the northeastern district of the Undercity, serving as the center for Forsaken arcane study and dark spellcraft. Dominated by an ominous Temple of the Damned, the quarter houses practitioners of both the arcane and fel arts. Occupying the northeastern quadrant of the subterranean city, the Magic Quarter is where the Forsaken preserve their arcane heritage and delve into darker methodologies. The centerpiece of the district is a looming Temple of the Damned, an architectural relic of Scourge design that has been repurposed by the free-willed undead. Beneath its vaulted, shadowy ceilings, mages practice subtle manipulations of magical energies alongside warlocks communing with demonic entities, making the quarter the nexus of intellectual power and occult research in Lordaeron. Beyond the study of raw evocation and summoning, the Magic Quarter functions as an essential civic hub for spellcasters. Portal trainers maintain transport links across Horde territories, while master tailors work with magically infused fabrics to craft robes and shrouds. Unlike Dalaran's strict segregation between academic wizardry and forbidden magic, the Forsaken blend arcane curiosity and fel power openly within these halls to secure their place against their many enemies.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_magic-quarter-2627847e9fcc74776819/1-0000.mp3", duration = 72.6987755, start = 0},
  },
}
P.transport["subzone:malden-s-orchard"] = {
  hash = "3386b6",
  fullHash = "3386b6",
  text = "Malden's Orchard. Malden's Orchard is a ruined farmstead in northern Silverpine Forest, named after the human owner who fled during the Scourge invasion of Lordaeron. Long abandoned, its dark evergreen trees sit overgrown while vicious black worgs stalk the grounds. The orchard's crumbling cottage served as a temporary refuge for a stranded Forsaken scout cut off from his unit. Before the Third War, this homestead supplied fresh fruit to the towns of Lordaeron, tended by a farmer named Malden. When the Scourge tore through the kingdom, Malden abandoned his land to flee the plague. In the years since, the orchard has choked under the dark, encroaching mists of Silverpine Forest. The evergreen trees remain unpruned and their fruit rots ungathered on blighted boughs, leaving the plot entirely reclaimed by wild predators.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_malden-s-orchard-6008c25346a305042a6f/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["subzone:merchant-coast"] = {
  hash = "abbcfe",
  fullHash = "abbcfe",
  text = "Merchant Coast. Trade and piracy shape the Merchant Coast along the Barrens' eastern shore. Ratchet handles sea trade, while pirates contest the coast. The Merchant Coast runs along the Barrens' eastern edge, where ships link central Kalimdor with the Eastern Kingdoms and Theramore. The Steamwheedle Cartel's neutral port of Ratchet takes cargo from anyone with coin. Southsea Freebooters also haunt the sands and nearby waters, preying on merchant ships and setting up illicit operations along the beaches.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_merchant-coast-2a6d99e05584d0a92520/1-0000.mp3", duration = 29.3093878, start = 0},
  },
}
P.transport["subzone:night-web-s-hollow"] = {
  hash = "ebc28d",
  fullHash = "ebc28d",
  text = "Night Web's Hollow. Night Web's Hollow is a sunken vale and abandoned gold mine located just northwest of Deathknell in Tirisfal Glades. Heavily overrun with arachnids, it serves as a testing ground for freshly awakened Forsaken sent to cull the vermin and prove their combat readiness. Tucked away in the northern hills of Deathknell, Night Web's Hollow was once an ordinary human gold mine before the plague swept through Lordaeron. In the aftermath of the kingdom's fall, the shafts were entirely abandoned to nature. Today, thick strands of webbing shroud the rock walls and suffocating shadows conceal a thriving colony of aggressive night web spiders. Freshly raised Forsaken are routinely dispatched into the hollow and its subterranean tunnels to cull the young and adult spiders so the Forsaken can regain access to the mine's gold.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_night-web-s-hollow-97beaf98a7dec5052dcf/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["subzone:nightmare-vale"] = {
  hash = "ec7664",
  fullHash = "c83b22",
  text = "Nightmare Vale. Nightmare Vale is a shadowed hollow nestled in southwestern Tirisfal Glades, just west of the Crusader's Outpost. Once a lush forest haven, its trees have withered under the blight, and vicious predators now roam among the twisted trunks. Before the Third War, this valley was a verdant part of the Tirisfal countryside, filled with songbirds and standard woodland game. In the wake of the Scourge's plague, the vegetation has blackened and rotted away. Ravenous darkhounds and massive vampire bats have devoured the native wildlife, turning the hollow into a grim haven for scavengers and beasts of prey. Lurking in the shadows of Nightmare Vale is Ressan the Needler, an unusually large, pale vampire bat notorious among local travelers. Wedged uncomfortably between the haunted wilderness and the zealous sentries at the nearby Crusader's Outpost, the vale is an unforgiving expanse where unwary adventurers quickly become prey.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_nightmare-vale-efef08e848e93c14523b/1-0000.mp3", duration = 55.2228571, start = 0},
  },
}
P.transport["subzone:nightsong-woods"] = {
  hash = "1708a3",
  fullHash = "1708a3",
  text = "Nightsong Woods. Nightsong Woods forms the embattled eastern expanse of Ashenvale, reaching from Raynewood Retreat toward the borders of Azshara. It serves as the primary battleground between the night elves defending their sacred forest and the Warsong clan harvesting lumber for the Horde. Across its shadowed glades, ancient groves clash with fortified encampments amidst persistent demonic corruption. Stretching eastward across Ashenvale to Azshara, Nightsong Woods is defined by escalating violence. The Falfarren River bisects the western reaches, creating a volatile boundary between Alliance settlements and Horde encroachments. Further east, the forest fractures into heavily disputed territories where Splintertree Post coordinates Horde campaigns against the Silverwing Sentinels. Orcish axes continuously clear southern groves to fuel the Horde's expansion, leaving clear-cut swaths that infuriate the Kaldorei. Adding to the peril, satyr strongholds like Satyrnaar and Xavian, alongside demonic remnants in Demon Fall Canyon and Felfire Hill, taint the eastern canopies.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_nightsong-woods-54edf191f37214dc9ddf/1-0000.mp3", duration = 62.955102, start = 0},
  },
}
P.transport["subzone:north-coast"] = {
  hash = "6d0ae2",
  fullHash = "947b9e",
  text = "North Coast. The North Coast is a bleak, fog-shrouded stretch of shoreline marking the northern edge of Tirisfal Glades along the Great Sea. Tainted by the fall of Lordaeron, the cold beaches are littered with rotting marine life and aggressively defended by tribes of hostile murlocs. Before the Third War, these northern waters and stony beaches were part of the peaceful northern boundary of Lordaeron. When the Plague of Undeath swept across the continent, its corrupting blight seeped down the bluffs and poisoned the coast. The waters turned chill and murky, washing up the carcasses of giant sea creatures that now rot upon the sand amid the perennial coastal fog. With the human kingdom shattered and the Forsaken focusing their attention around Brill and the Capital City, coastal murlocs claimed the desolate sands. The local Vile Fin tribe maintains huts along the surf, utilizing nearby shallows as spawning grounds. Swarms of ravenous murlocs, including notable figures like Deeb and numerous growing tadpoles, violently guard the tideline against any surface-dwellers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-coast-448718a4bd3cc7bb6a96/1-0000.mp3", duration = 61.3355102, start = 0},
  },
}
P.transport["subzone:north-tide-s-hollow"] = {
  hash = "5a3695",
  fullHash = "f3edca",
  text = "North Tide's Hollow. North Tide's Hollow is a rugged wilderness pocket in Silverpine Forest located just north of the Sepulcher. Haunted by feral Moonrage worgen loyal to the rogue Archmage Arugal, the clearing serves as a base of operations for the beasts stalking the coastal woods. Tucked away in the dense timber north of the Forsaken settlement of the Sepulcher, North Tide's Hollow is dominated by the savage Moonrage pack. These feral worgen, brought into Lordaeron through the reckless sorcery of Archmage Arugal, have established crude encampments throughout the hollow. Built with only the barest necessities required by the hardy beasts, these rough shelters provide a forward staging ground dangerously close to Forsaken travel routes. Unlike ordinary wilderness predators, the worgen of North Tide's Hollow answer to the sinister will emanating from Shadowfang Keep. Their proximity to both the western shoreline and the main road through Silverpine makes them a constant menace to Forsaken couriers and patrols attempting to secure the region.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-tide-s-hollow-827592d608678b0dd597/1-0000.mp3", duration = 57.6, start = 0},
  },
}
P.transport["subzone:north-tide-s-run"] = {
  hash = "7fe903",
  fullHash = "6d0436",
  text = "North Tide's Run. North Tide's Run is the windswept northwestern shoreline of Silverpine Forest, skirting the edge of the Great Sea. Marked by a half-sunken shipwreck, this stretch of sand is known as a secluded trial ground for traveling druids seeking harmony with the waters. Stretching along the northwest edge of Silverpine Forest, North Tide's Run consists of cold sand, pounding surf, and a strip of the Great Sea. Its most unmistakable landmark is a partially submerged shipwreck tilted precariously in the shallows near the beach. Despite its bleak atmosphere, North Tide's Run holds sacred importance for Horde initiates walking the path of Cenarius. Young tauren druids are directed here on pilgrimage to recover underwater relics lost to the waves, testing their lung capacity and endurance to earn the blessing of the aquatic form.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-tide-s-run-bcf41e1c05479cf4db6b/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["subzone:olsen-s-farthing"] = {
  hash = "8341ad",
  fullHash = "8341ad",
  text = "Olsen's Farthing. Olsen's Farthing was once a flourishing farmstead situated along the primary trade road running through Silverpine Forest. In the wake of the Third War, the fields fell into ruin and became overrun by reanimated thralls bound to the renegade necromancer Thule Ravenclaw. Before the plague consumed Lordaeron, Olsen's Farthing was a busy agricultural homestead with direct access to Silverpine's main overland trading route. Today, its tilled fields are choked with weeds, its structures lie broken, and any memory of honest farming has been erased by Scourge necromancy. Undead thralls, bound as slaves and raiders under the command of Thule Ravenclaw, wander the barren grounds to slaughter any travelers who stray too close.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_olsen-s-farthing-66ed3534c16bd57875e5/1-0000.mp3", duration = 41.6653061, start = 0},
  },
}
P.transport["subzone:palemane-rock"] = {
  hash = "1c1260",
  fullHash = "1c1260",
  text = "Palemane Rock. Palemane Rock is a cavern and campsite nestled into the western mountains of Mulgore. It serves as a primary stronghold for the aggressive Palemane gnoll tribe, posing a continual nuisance and threat to the nearby tauren of Bloodhoof Village. Situated along the western rim of the grassy plains of Mulgore, Palemane Rock consists of a sprawling open-air encampment fronting a deep, shadowed cavern carved into the mountainside. The Palemane gnolls have claimed both the cave interior and the immediate foothills outside as their territory. Hostile and territorial, these gnolls aggressively defend their den, attacking hunters, travelers, and scouts who wander too close to their rocky haven.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_palemane-rock-dacfd86d5e1357485c98/1-0000.mp3", duration = 39.157551, start = 0},
  },
}
P.transport["subzone:pools-of-vision"] = {
  hash = "d6c90f",
  fullHash = "2db754",
  text = "Pools of Vision. The Pools of Vision are a subterranean cavern nestled beneath Spirit Rise in Thunder Bluff. Marked by still waters and dim caverns, this secluded subterranean space serves as the primary enclave for the Forsaken within the tauren capital. While the sunlit peaks of Thunder Bluff belong to the wind, earth, and sky, the Pools of Vision plunge directly beneath Spirit Rise into shadowy seclusion. Accessible from a discreet cave path off the bridge leading to the rise, this subterranean grotto offers subterranean respite quite unlike the open-air lodges above. Here, misty waters pool in the dark, creating an isolated atmosphere where Horde spellcasters gather far from the bustling central mesas. Within Thunder Bluff, the Pools of Vision function as the de facto base of operations for the Forsaken. Travelers from the eastern continent find kindred souls here: undead priests practicing their shadowed arts, mages conjuring arcane portals, and emissaries of the Defilers seeking recruits for their campaigns in the Arathi Highlands. Whether tucked away by tauren skepticism or by the Forsaken's own natural preference for the dark, this quiet refuge bridges Lordaeron's undead with their Kalimdor allies.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_pools-of-vision-fa1d4c9cebf44f835c76/1-0000.mp3", duration = 68.7804082, start = 0},
  },
}
P.transport["subzone:pyrewood-village"] = {
  hash = "109325",
  fullHash = "109325",
  text = "Pyrewood Village. Pyrewood Village is an isolated human settlement nestled in southern Silverpine Forest beneath Shadowfang Keep. Originally part of Gilneas before being stranded outside the Greymane Wall, its living residents harbor a horrific secret brought upon them by the mad archmage Arugal. Pyrewood was once a prosperous Gilnean settlement. When King Genn Greymane chose to isolate his kingdom behind the massive Greymane Wall following the Second War, Pyrewood was left on the northern side. Cut off from their homeland, the townsfolk were left entirely defenseless during the Third War as the Scourge marched across Lordaeron. Though they managed to survive the initial wave of the undead, their true nightmare began when the mage Arugal took refuge in the fortress above.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_pyrewood-village-033552729c8f8db13ada/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["subzone:ragefire-chasm-classic"] = {
  hash = "0983e2",
  fullHash = "0983e2",
  text = "Ragefire Chasm (Classic). Ragefire Chasm threatens Orgrimmar from beneath its streets, where troggs have broken into the tunnels. The fiery caverns also shelter a cult whose plans reach beyond Durotar. Ragefire troggs have surged into the volcanic tunnels beneath Orgrimmar. They pushed up from deep fissures and now threaten the city's foundations. Magatha Grimtotem, a tauren, tried to make peace with them, but the troggs answered with violence. Their tunnels run below the stone streets and fortified towers, leaving Orgrimmar at risk if the creatures keep digging upward.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ragefire-chasm-classic-3f0a401934fcc04e82b4/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["subzone:raptor-grounds"] = {
  hash = "b479b6",
  fullHash = "b479b6",
  text = "Raptor Grounds. In the southern Barrens, Sunscale raptors claim a secluded valley in the rocky hills west of Northwatch Hold. Their eerie, tool-using cunning and obsessive theft of bright trinkets set them apart from ordinary beasts. West of Northwatch Hold, Sunscale raptors make their home in the Raptor Grounds. Eerie and far from ordinary beasts, they fashion crude shelters, make primitive tools, and coordinate their hunts. Their obsessive fascination with shiny or unusual things drives them to raid passing caravans and Horde encampments. Coins, trinkets, and supplies disappear into their canyon dens.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_raptor-grounds-c5aeefda62705f53c3ea/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["subzone:ratchet"] = {
  hash = "6f9e6e",
  fullHash = "cece6c",
  text = "Ratchet. Ships crowd Ratchet's docks on the eastern coast of the Barrens. The Steamwheedle Cartel runs this neutral port, linking central Kalimdor to the Eastern Kingdoms by sea. Ratchet gives shelter to anyone who can pay, on the dry coast between Durotar and Dustwallow Marsh. After the Third War, chief engineer Gazlowe founded the port, drawing smugglers, exiles, and daring traders to Kalimdor's frontier. The Steamwheedle Cartel runs the town, which keeps strict neutrality between the Horde and the Alliance. Ships such as The Maiden's Fancy cross the Great Sea to Booty Bay with goods, mercenaries, and raw materials. Ratchet Bruisers watch the docks and beat anyone who starts a fight and disrupts trade. Ratchet's docks, taverns, and workshops serve a town with dealings beyond trade. A secluded tower overlooks the harbor from the hills, where warlocks including Strahad Farsan and Menara Voidrender gather. While townsfolk and sailors tend to cargo and goblin engineering, the warlocks commune with demonic forces without interference. The Steamwheedle Cartel does not enforce the moral restrictions found in traditional faction capitals.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ratchet-ac9216b4a2f9ade543d7/1-0000.mp3", duration = 69.7469388, start = 0},
  },
}
P.transport["subzone:ravaged-caravan"] = {
  hash = "53b146",
  fullHash = "53b146",
  text = "Ravaged Caravan. The Ravaged Caravan is a smoldering wreck located on the northeastern shore of Stonebull Lake in Mulgore. Once a supply convoy bound for Supervisor Fizsprocket's mining operations, it was ambushed and destroyed by local tauren determined to halt goblin exploitation of their homeland. Perched on a rise above Stonebull Lake, the Ravaged Caravan marks an early clash between the tauren of Bloodhoof Village and the encroaching Venture Company. Sent to deliver mining supplies, blueprints, and equipment to Supervisor Fizsprocket's dig site, the caravan was cut off and wrecked by tauren defenders before it could reach its destination. Despite the devastation, stubborn Venture Co. survivors still cling to the ruined wagons and smoldering crates, jealously guarding what little cargo remains.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ravaged-caravan-ccc6391690a3959d1e44/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["subzone:razor-hill"] = {
  hash = "169921",
  fullHash = "b8618c",
  text = "Razor Hill. Razor Hill links the Valley of Trials, the Barrens, and Orgrimmar at a crossroads in central Durotar. Its fortified barracks train young orc and troll warriors for life in the wilderness. Razor Hill joins northern Durotar to the southern coast and the Barrens across the Southfury River. Stone-and-timber barracks and orcish burrows fill the settlement, founded early in Durotar's settlement. After the Third War, human forces from Kul Tiras lured the Horde here with a false offer of an emissary summit. Rexxar went in Thrall's stead and stopped their ambush. Razor Hill now stands fortified against further attacks from the coast. Veteran officers such as Gar'Thok direct Razor Hill's defenses against threats nearby. Human marines still hold Tiragarde Keep on the eastern shore, while quilboar and harpy tribes harass supply lines. Investigators such as Orgnil Soulscar track the Burning Blade cult, whose rituals and corrupted agents lurk in the nearby crags, and work to stamp them out.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razor-hill-28033cd373d0fcccf88a/1-0000.mp3", duration = 57.9918367, start = 0},
  },
}
P.transport["subzone:razor-hill-watchtower"] = {
  hash = "362d09",
  fullHash = "362d09",
  text = "Razor Hill Watchtower. Furl Scornbrow watches Durotar from the Razor Hill Watchtower. From its red stone bluffs, he keeps an eye on the plains and coast, guarding the settlement below. The Razor Hill Watchtower rises above Razor Hill and the canyons around it. Thick timber and iron framing hold the outpost together. Durotar faces threats from Kul Tiras marines along the eastern shore, quilboar raiders across the scrublands, and Burning Blade cultists in nearby crags. From the ridgeline, a lookout can spot warbands, smoke signals, and incursions before they reach the settlement gates.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razor-hill-watchtower-9ce5653964f10a1f8408/1-0000.mp3", duration = 33.044898, start = 0},
  },
}
P.transport["subzone:razorfen-downs-classic"] = {
  hash = "b389b9",
  fullHash = "91ea39",
  text = "Razorfen Downs (Classic). Deep in the southern Barrens, the Scourge now holds Razorfen Downs, the quilboar's ancestral burial ground and capital. Led by the lich Amnennar the Coldbringer, its agents have raised the quilboar dead and threaten to spread their power across central Kalimdor. Razorfen Downs shares the towering, petrified vines of nearby Razorfen Kraul. It lies where the boar demigod Agamaggan fell in the War of the Ancients. For generations, this thorn labyrinth was the quilboar's sacred burial ground and seat of power, guarded by mystics of the Death's Head tribe. The quilboar hold its dense briars holy, for they were soaked in their divine progenitor's blood. The Scourge has broken the sanctity of Razorfen Downs. Amnennar the Coldbringer, a powerful lich who serves the Lich King, subdued the Death's Head quilboar and made their ancestral resting ground an undead stronghold. Reanimated quilboar skeletons and corpses, along with shrieking banshees, prowl the Spiral of Thorns. The Horde in the nearby Barrens and emissaries from Stormwind's Cathedral of Light both see this Scourge power as a grave threat to Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razorfen-downs-classic-f7cb49ea15debd4e3d38/1-0000.mp3", duration = 68.3102041, start = 0},
  },
}
P.transport["subzone:razorfen-kraul-classic"] = {
  hash = "b177b8",
  fullHash = "b177b8",
  text = "Razorfen Kraul (Classic). Razorfen Kraul is the ancestral heartland of the quilboar, carved deep into the colossal thorns that sprang from the blood of the fallen boar demigod Agamaggan. Ruled by the ruthless crone Charlga Razorflank, this fortified labyrinth serves as a staging ground for bloody raids across the southern Barrens. Ten thousand years ago during the War of the Ancients, the colossal boar demigod Agamaggan perished battling the Burning Legion to save Azeroth. Wherever his sacred blood seeped into the soil of southern Kalimdor, massive, impenetrable thorn vines erupted from the earth. The quilboar, believing themselves the mortal progeny of the Great Boar, gathered within these dense briars to dwell and venerate his sacrifice. The dense mass known as Razorfen Kraul stands as their most revered redoubt, thick with quilboar warriors, beast trainers, and earth-shaping shamans.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razorfen-kraul-classic-4e2ac22dab640fbfd26d/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["subzone:razormane-grounds"] = {
  hash = "01cd07",
  fullHash = "01cd07",
  text = "Razormane Grounds. Razormane quilboar push east from the Barrens into central Durotar. Their thorn-choked camp marks the front of their unending clash with Orgrimmar's orcs. At the Southfury River, the Razormane Grounds threaten travelers beneath central Durotar's red cliffs. The camp marks the furthest east the quilboar have spread from the Barrens. Captain Flat Tusk of the Battleguard and Geolord Mottle lead raids on nearby orc settlements and passing supply lines. Patrols set out from Razor Hill and nearby outposts, but the Razormane keep replenishing their ranks among the briars faster than the Horde can clear them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razormane-grounds-acab143a4aa5e208dd8a/1-0000.mp3", duration = 35.7093878, start = 0},
  },
}
P.transport["subzone:razorwind-canyon"] = {
  hash = "11ea08",
  fullHash = "415ce1",
  text = "Razorwind Canyon. Dustwind harpies threaten travelers on Razorwind Canyon’s road between Razor Hill and Orgrimmar. The rocky gulch cuts through Durotar, and the harpies make the route north toward the Horde capital dangerous. Razorwind Canyon runs beside the main road from Razor Hill to Orgrimmar. Its gullies reach into the eastern bluffs and west toward Tor'kren Farm. Dustwind harpies nest among the rocks and attack travelers who stray too close to their roosts. With the canyon so near the capital’s trade route, Durotar’s defenders must keep watch over its gullies. Razorwind Canyon’s winding passages cut through Durotar’s red rock hills. An eastern branch runs deep into the crags, through a cavern, and into Drygulch Ravine. Harpies roost on high perches and descend in flocks, so travelers crossing the passes can be surrounded and cut down.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razorwind-canyon-27d471732000a3b380dc/1-0000.mp3", duration = 49.8677551, start = 0},
  },
}
P.transport["subzone:red-rocks"] = {
  hash = "09bd48",
  fullHash = "3b205e",
  text = "Red Rocks. Red Rocks is a towering sandstone bluff in northeastern Mulgore that serves as a sacred ancestral burial ground for the tauren. Here, the most valiant fallen champions are laid to rest, and young braves travel to its quiet heights to seek the wisdom of their forebears. Rising high above the plains of northeastern Mulgore, the crimson formations of Red Rocks mark a sacred threshold between the living world and the next. Tauren tradition reserves this solemn ground for their most valiant heroes—chieftains, defenders, and champions who gave their lives founding and protecting Thunder Bluff. They are laid to rest here in honor, among the graves of their forebears. It is equally a place of spiritual beginning, where young tauren complete their rites of passage by honoring the ancestral graves and communing with the wind. The enduring peace of Red Rocks has been shattered by the Bristleback quilboar. Creeping out from their dens, these aggressive scavengers have infested the sandstone ledges and desecrated the ancestral graves with filth. This violation deeply affronts the spiritual traditions of Thunder Bluff. Shaman and lorekeepers now summon aid to cleanse the crags, driving out the Bristlebacks and reclaiming the sanctity of their resting dead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_red-rocks-759a16ed28ebddd03253/1-0000.mp3", duration = 71.9934694, start = 0},
  },
}
P.transport["subzone:rocktusk-farm"] = {
  hash = "48849b",
  fullHash = "48849b",
  text = "Rocktusk Farm. Swine feed Orgrimmar from Rocktusk Farm, just beyond the city gates in northern Durotar. The farm supplies meat and provisions to the capital, where dry, stony ground makes crops hard to grow. Rocktusk Farm raises hardy swine on Durotar’s dry, stony ground. Crops are difficult to grow here, so the farm helps feed Orgrimmar’s growing population. Close to the capital’s fortified perimeter, it is safer than homesteads in the wild red canyonlands.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rocktusk-farm-9b45c492b621cc73709b/1-0000.mp3", duration = 26.8277551, start = 0},
  },
}
P.transport["subzone:rogues-quarter"] = {
  hash = "cf11aa",
  fullHash = "c95759",
  text = "Rogues' Quarter. The Rogues' Quarter is a dimly lit district in the southeastern wing of the Undercity. It serves as the staging ground for the Forsaken's scouts, assassins, and underworld operatives, along with the craftsmen who support them. Tucked away in the southeastern quadrant of the subterranean city, the Rogues' Quarter gathers the Forsaken's most cunning and lethal survivors. In life, many were thieves, cutpurses, or silent blades for the Kingdom of Lordaeron; in death, their expertise in stealth, poisons, and misdirection has been repurposed to protect the fledgling nation from the Scourge and the Scarlet Crusade. The district hums with quiet activity, offering a covert haven where operatives sharpen their daggers, brew deadly toxins, and hone clandestine skills. Beyond stealth and assassination, the Rogues' Quarter is home to the specialized trades that enable undercover survival. Artisans gather here to instruct travelers in leatherworking and skinning, turning raw hides into light, silent armor. The clatter of engineering benches echoes through the stone halls as tinkers assemble gadgets, while field medics and apothecaries provide instruction in first aid and vend lethal poisons essential for covert work.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rogues-quarter-92a7eaa7738e0325a997/1-0000.mp3", duration = 68.9371429, start = 0},
  },
}
P.transport["subzone:rolling-plains"] = {
  hash = "e7ba6f",
  fullHash = "f0b9a3",
  text = "Rolling Plains. The Rolling Plains span the southern expanse of Mulgore, stretching between Bloodhoof Village and the border of the Barrens. These windswept grasslands are home to thriving herds of wildlife, but they are also a point of perpetual vigilance due to prowling centaur raiders and aggressive harpies. Spanning south from Bloodhoof Village toward the natural earthen gates leading into the Barrens, the Rolling Plains embody the vast open ranges of the tauren homeland. The area teems with wild game essential to the tribes, including prairie wolves, kodo herds, flatland cougars, and swift tallstriders. For young hunters proving their worth to the elders, these sweeping savannahs serve as an indispensable proving ground where tracking, patience, and reverence for nature are put to the test. Despite Mulgore's naturally fortified ring of bluffs, the Rolling Plains remain uniquely exposed to outside threats. It is the only frontier where aggressive centaur outriders have managed to push past defensive perimeters to harass passing travelers and hunting parties. Adding to the peril, a nest of predatory Windfury harpies roosts in the eastern crags, swooping down upon stray game and vulnerable nomadic camps.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_rolling-plains-165412745b539b4e2dfd/1-0000.mp3", duration = 69.9559184, start = 0},
  },
}
P.transport["subzone:royal-quarter"] = {
  hash = "c93eb6",
  fullHash = "03562e",
  text = "Royal Quarter. The Royal Quarter is the secluded seat of power within the Undercity, serving as the throne room for Lady Sylvanas Windrunner. Here, the Banshee Queen directs the Forsaken alongside her dreadlord enforcer, Varimathras, guarded by an elite cohort of Royal Dreadguards. Tucked away behind towering archways and shadowed corridors, the Royal Quarter—also known as the Hall of the Dark Lady—is the political and military nerve center of the Forsaken. Sylvanas Windrunner holds court in this cavernous subterranean chamber, plotting the survival of her free-willed undead and the destruction of the Scourge. Heavily armored Royal Dreadguards stand vigil along the dais, ensuring that uninvited guests and would-be assassins never reach their queen. Standing beside the Dark Lady is the nathrezim Varimathras, an unexpected and uneasy fixture in the heart of the Undercity. After siding with Sylvanas during the civil war in the ruins of Lordaeron to save his own life, the dreadlord pledged loyalty to her cause. From the Royal Quarter, he commands deathstalkers and coordinates defensive operations across the realm. While his tactical cunning serves the Forsaken well, his demonic nature leaves many Horde allies wary of his true allegiances.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_royal-quarter-7015c1f141e5a80834c8/1-0000.mp3", duration = 72.8032653, start = 0},
  },
}
P.transport["subzone:scarlet-watch-post"] = {
  hash = "8068fd",
  fullHash = "8068fd",
  text = "Scarlet Watch Post. The Scarlet Watch Post is an isolated watchtower stationed in the rocky hills of northeastern Tirisfal Glades, just north of the Scarlet Monastery. Maintained by a vigilant garrison of Crusaders, its sole purpose is to safeguard the monastery's vulnerable northern flank against flanking assaults. Perched in the rugged heights behind the Scarlet Monastery, the Scarlet Watch Post serves as a critical early-warning bastion for the zealots below. While the southern road up to the monastery gate receives heavy traffic and fortifications, the rugged cliffs along Tirisfal's northern coastline provide a tempting back route for infiltrators. To eliminate this blind spot, the Scarlet Crusade maintains this fortified stone tower—one of several Crusader outposts scattered across Tirisfal Glades. Under the stern command of Captain Melrache, a mixed force of Neophytes, Vanguards, and devout Friars keeps ceaseless vigil over the cliffs, ensuring neither the Scourge nor the Forsaken can surprise the order from behind.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_scarlet-watch-post-222eee27bb1df5df836e/1-0000.mp3", duration = 58.6971429, start = 0},
  },
}
P.transport["subzone:screaming-gully"] = {
  hash = "1e60ff",
  fullHash = "1e60ff",
  text = "Screaming Gully. Screaming Gully is the first sprawling subterranean cavern encountered just beyond the entrance of the Wailing Caverns. Bathed in unnatural fungal glow and shallow waters, it serves as the outer redoubt for the corrupted Druids of the Fang and their mutated beasts. Stepping through the threshold of the Wailing Caverns leads directly into Screaming Gully, an echoing chasm where the wind groans through subterranean fissures. Far from the arid Barrens above, the gully is choked with damp overgrowth, humid mist, and aggressive wildlife twisted by the Emerald Nightmare. The Fanglord Lady Anacondra oversees the chamber, surrounded by acolytes of the Druids of the Fang and vicious deviate raptors, while ancient snapping turtles like Kresh patrol the shallow waterways below.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_screaming-gully-4360655d19aa732693a8/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["subzone:scuttle-coast"] = {
  hash = "e4a01d",
  fullHash = "c8e533",
  text = "Scuttle Coast. Between Razor Hill and Tiragarde Keep, wreckage from Daelin Proudmoore’s fleet litters Durotar’s eastern shore. The sunken ships make the Scuttle Coast a place where the Horde scavenges and remembers the recent naval war. Sunken warships line Durotar’s eastern edge, where the shore meets the Great Sea. During Grand Admiral Daelin Proudmoore’s invasion, the Kul Tiras fleet attacked the young nation of Durotar. Fierce battles with the Horde drove many human warships onto jagged shoals, where they broke apart. Barnacled timber, broken rigging, cargo barrels, and sunken ships still mark the coast. For the nearby encampments at Razor Hill, the wreckage recalls how close the Kul Tiran threat remains. The name Scuttle Coast may refer to warships scuttled or grounded in the fighting, or to crabs and makrura picking through the wreckage. Shoreline beasts and dangerous tides keep casual travelers away.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_scuttle-coast-6dd172f33bc0a0a469be/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["subzone:sepulcher"] = {
  hash = "69eb15",
  fullHash = "69eb15",
  text = "Sepulcher. The Sepulcher is the primary Forsaken settlement and stronghold in Silverpine Forest. Once an ordinary Lordaeron graveyard and burial crypt overlooking the western coast, it now serves as a fortified sanctuary for the Horde against surrounding regional threats. Perched in the hills above the Lordaeron coastline, the Sepulcher was originally a quiet cemetery and crypt alongside the western road. In the wake of the Third War, the newly emancipated Forsaken repurposed the ancient stone vault and its grounds into an essential outpost. Surrounded by hostile forces on all sides—the feral worgen to the south, wandering Scourge remnants to the east, and Kirin Tor wizards watching from Ambermill—the Sepulcher provides a rare haven of safety, supplies, and command for travelers marching through Silverpine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sepulcher-847f5afab625ee0839e7/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["subzone:sewers"] = {
  hash = "81da28",
  fullHash = "81da28",
  text = "Sewers. The Sewers are a sprawling subterranean drainage network that provides a secondary entrance directly into the Undercity. Cutting beneath the hills west of the ruined palace of Lordaeron, this conduit allows bat handlers and stealthy travelers to bypass the precarious elevators leading down from the throne room. Before the plague wiped out Lordaeron, these stone culverts served as the mundane sewer lines draining the royal capital. In the hands of Sylvanas Windrunner's Forsaken, however, the runoff tunnels have been integrated into the Undercity's outer defenses. Emerging west of the surface ruins near a contested Scarlet Watchtower in Tirisfal Glades, the passage provides a level, direct slope inside. Forsaken bat handlers use this cavernous conduit to fly riders swiftly into the subterranean rings, avoiding the sluggish cage lifts entirely. Because it circumvents the heavily fortified surface courtyards, it remains a dangerous vulnerability that hostile infiltrators constantly seek to exploit.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sewers-8be4f2247fbb087c2eda/1-0000.mp3", duration = 58.3836735, start = 0},
  },
}
P.transport["subzone:shadow-grave"] = {
  hash = "5f6e86",
  fullHash = "5f6e86",
  text = "Shadow Grave. Shadow Grave is a stone crypt perched atop the sloping burial grounds above Deathknell in Tirisfal Glades. It serves as the physical awakening point where newly liberated Forsaken shake off the stupor of death and the Lich King's faded control. Tucked into the rocky foothills at the top of the graveyard slope above Deathknell, the Shadow Grave is a simple stone mausoleum with an extraordinary purpose. Inside its damp vaults, corpses raised into the mindless servitude of the Scourge gradually awaken to free will. Under the watchful eye of caretakers like Undertaker Mordo, these freshly liberated undead stand up from their stone slabs and take their first shuddering steps into a world that despises them, setting out down the footpath toward Deathknell to pledge themselves to the Banshee Queen.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shadow-grave-a0cdd0982de4a461b79c/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["subzone:shining-strand"] = {
  hash = "50f57c",
  fullHash = "50f57c",
  text = "Shining Strand. The Shining Strand is the strip of shoreline hugging Lordamere Lake along eastern Silverpine Forest, stretching south from the Ruins of Lordaeron toward the rugged foothills of Alterac. Its shallows are home to settlements of aggressive Vile Fin murlocs, making the lakeshore dangerous ground for unseasoned travelers. Running along the eastern edge of Silverpine Forest, the Shining Strand borders the misty waters of Lordamere Lake. The Vile Fin tribe of murlocs has established several aggressive settlements along these shallows, posing a deadly hazard to anyone attempting to travel the lake road, while feral worgen roam the deep woods of Silverpine behind the shore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shining-strand-c678e4795b1cdeafdb1d/1-0000.mp3", duration = 38.8440816, start = 0},
  },
}
P.transport["subzone:shrine-of-the-dormant-flame"] = {
  hash = "532e7c",
  fullHash = "532e7c",
  text = "Shrine of the Dormant Flame. At the Shrine of the Dormant Flame, Horde shaman seek communion with fire atop Durotar’s highest peak northwest of the Valley of Trials. Telf Joolam keeps the secluded sanctuary, where initiates climb to prove their spiritual mastery. A narrow trail winds up from the Southfury River, at the southwestern edge of the Southfury Watershed. The summit rises above Durotar’s red cliffs, with a commanding view and a precipice where one misstep means certain death. Telf Joolam, a solitary hermit, oversees the sacred rites here. Aspiring orc and troll shaman come for the ritual Call of Fire. At the shrine’s brazier, they use the ember of a defeated elemental to kindle the sleeping coals and prove they can commune with fire and respect its destructive spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shrine-of-the-dormant-flame-67aee4e99e1c141bb6b4/1-0000.mp3", duration = 44.7477551, start = 0},
  },
}
P.transport["subzone:shrine-of-the-fallen-warrior"] = {
  hash = "4cd835",
  fullHash = "014327",
  text = "Shrine of the Fallen Warrior. Perched upon a secluded ridge west of the Crossroads lies the Shrine of the Fallen Warrior, a quiet memorial overlooking the sweeping red savannahs of the Barrens. Marked by a stone plinth bearing the initials 'MK' and the body of a fallen orc warrior, it is watched over by the gentle presence of a Spirit Healer named Koiter. Tucked away high upon the hills northwest of the Crossroads, the Shrine of the Fallen Warrior stands as an unusually solemn haven amidst the dust and peril of the Barrens. To find it, travelers must scale a winding ridge pathway southwest of the summit until they reach a gentle mound. Upon the summit rests a carved stone monument, its plinth carved with the initials 'MK'. Before it lies the armored form of an orc warrior at rest, watched over day and night by a named Spirit Healer known as Koiter. There are no battle horns here, only quiet contemplation honoring a champion who walked Kalimdor's lands. Within the world, the shrine stands as an enduring tribute to a departed champion of the Horde whose soul lingers in the care of the spirits. Outside the realm, the monument serves as a heartfelt tribute created by the game's artists to honor Michel Koiter, a beloved illustrator who passed away during the development of the world. The resting warrior is modeled precisely after Koiter's own beta character, Twincruiser, immortalizing his presence forever beneath Kalimdor's open skies.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shrine-of-the-fallen-warrior-a766bae9c82b545d41ab/1-0000.mp3", duration = 84.5583673, start = 0},
  },
}
P.transport["subzone:skittering-dark"] = {
  hash = "3dfd82",
  fullHash = "3dfd82",
  text = "Skittering Dark. The Skittering Dark is an abandoned mine and shadowy woodland hollow in western Silverpine Forest. Infested by aggressive giant spiders, the cavern and its surrounding woods are thick with webbing and danger for unwary beasts and travelers. Tucked into the hills just east of the western coast of North Tide's Run, the Skittering Dark was once a working mine. Today, the shafts are completely choked with cobwebs, serving as the sprawling nest of giant spiders. With the shadowy weaver Krethis haunting the exterior, the spiders hunt anything that strays too close.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_skittering-dark-d405c0733f1a33e10832/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["subzone:skull-rock"] = {
  hash = "c7bf72",
  fullHash = "c7bf72",
  text = "Skull Rock. Burning Blade cultists gather at Skull Rock, hidden in Durotar's eastern coastal cliffs. Their cavern lies east of Orgrimmar, where they plot against Thrall's Horde. Burning Blade cultists gather in Skull Rock, a perilous stronghold beneath northeastern Durotar's crags. Dark cultists, fel-worshipping orcs, and summoners meet in its winding tunnels to practice demonic arts and plot against the young Horde. The warlock Gazz'uz leads the cell. Its work threatens Orgrimmar's nearby gates and travelers along the eastern shore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_skull-rock-787e6b198ef579074aba/1-0000.mp3", duration = 31.0595918, start = 0},
  },
}
P.transport["subzone:sludge-fen"] = {
  hash = "dd925f",
  fullHash = "dd925f",
  text = "Sludge Fen. In northeastern the Barrens, Sludge Fen's clear pool has become an oily industrial field run by the Venture Company. Supervisor Lugwizzle oversees the drilling, while rivals in Ratchet seek to sabotage the operation. Sludge Fen once held a clear pool fed by natural springs in the arid Barrens. The Venture Company built oil-drilling platforms and machinery over the basin, turning the wetland into a reservoir of sludge and industrial waste. Supervisor Lugwizzle oversees goblin drillers, engineers, and overseers as they pump crude oil around the clock. Runoff and toxic byproducts coat the water, choking the native aquatic life beneath the grease.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sludge-fen-88f95a2c46764d7cf447/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["subzone:solliden-farmstead"] = {
  hash = "d466c1",
  fullHash = "f848b9",
  text = "Solliden Farmstead. Solliden Farmstead is an active human pumpkin farm nestled in western Tirisfal Glades, just north of Deathknell. It represents a rare anomaly in northern Lordaeron: living native farmers who survived the Plague of Undeath and cling fiercely to their soil under the shadow of the Scarlet Crusade. While most of Lordaeron fell to ruin and rot, the fields of Solliden Farmstead still produce healthy crops. Today, these surviving human farmers live under the watchful shield of the Scarlet Crusade patrolling from a nearby tower. Traumatized and insular, they defend their homestead with unyielding hostility, striking at any outsiders who draw near—Horde and Alliance alike. To the Forsaken just emerging from Deathknell, Solliden is both a threat and a resource. The Royal Apothecary Society eyes the farm's pristine pumpkins as prime organic testing material for brewing their New Plague. Meanwhile, Forsaken officers like Deathguard Simmer send fledgling recruits to raid the fields, steal those pumpkins for Apothecary Johaan in Brill, and teach the living a lesson.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_solliden-farmstead-b62aff3ba9bcf0cd6a4b/1-0000.mp3", duration = 63.5036735, start = 0},
  },
}
P.transport["subzone:south-tide-s-run"] = {
  hash = "227add",
  fullHash = "227add",
  text = "South Tide's Run. South Tide's Run is the lonely southwestern coastline of Silverpine Forest, stretching along the cold waters of the Great Sea. Flanking the forested interior, these damp sands and surf serve as the southern complement to North Tide's Run. Stretching along the southwestern edge of Silverpine Forest, South Tide's Run forms a desolate boundary between the woods and the Great Sea. Unlike the protected eastern roads that lead down toward the Greymane Wall, this open shore takes the brunt of the western tides, serving as a bleak coastal wilderness largely untouched by the settlements inland.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_south-tide-s-run-0f9d5d994bd948616690/1-0000.mp3", duration = 33.6457143, start = 0},
  },
}
P.transport["subzone:southern-gold-road"] = {
  hash = "003aee",
  fullHash = "eb1e2a",
  text = "Southern Gold Road. Caravans and travelers crowd the Southern Gold Road as it runs through the Barrens toward the Great Lift. Trade links the central plains with distant reaches of Kalimdor. At the stone bridge between the northern and southern Barrens, the Southern Gold Road turns south toward the Great Lift and Thousand Needles. Like the northern stretch, simply called the Gold Road, it takes its name from the lucrative merchant caravans that travel its length. Quilboar tribes and prowling predators harass those who use it, yet the road remains one of the continent’s busiest long-distance routes. Goods pass along it between remote outposts and ports. Horde couriers and patrols share the Southern Gold Road with merchants and explorers bound for distant lands. Travelers journey between Gadgetzan in the southern deserts of Tanaris, Auberdine on the shores of Darkshore, and Nighthaven, among the sacred groves of Moonglade. For those crossing Kalimdor’s interior on foot, surviving the journey down this sun-baked road is a grueling rite of passage.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_southern-gold-road-788c18fc6c106d78e9fd/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["subzone:spirit-rise"] = {
  hash = "df15d2",
  fullHash = "3c058b",
  text = "Spirit Rise. Spirit Rise is the northwest mesa of Thunder Bluff, serving as the tauren capital's premier sanctum for spiritual and shamanic study. Overseen by spiritual guides such as the Skychaser tribe, it features sacred training halls above and descends into the cavernous Pools of Vision below. Perched high upon the bluffs overlooking the plains of Mulgore, Spirit Rise is devoted to communion with the elements and ancestor spirits. Connected to the central mesa by rope bridges, it houses the Hall of Spirits and the Spiritual Healing pavilion, where young and veteran shaman gather to deepen their connection with the earth, air, fire, and water. The Skychaser tribe maintains a strong presence across the rise, guiding seekers through ancient traditions. Beneath the breezy huts and open-air totem shrines lies an entrance burrowing into the mesa itself: the steamy Pools of Vision, a sacred subterranean cavern where seers peer into spirit-touched waters.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_spirit-rise-8e6bd2ee6c0e9fa0d224/1-0000.mp3", duration = 54.7787755, start = 0},
  },
}
P.transport["subzone:spirit-rock"] = {
  hash = "66602d",
  fullHash = "66602d",
  text = "Spirit Rock. Above the Valley of Trials in Durotar, Spirit Rock draws Horde initiates to commune with the elements. A winding trail called the Hidden Path leads to this sacred crag. Spirit Rock overlooks the red canyon where young Horde warriors and scouts train. The Hidden Path winds up the rocky ridgeline to this quiet altar. Aspiring shaman climb to the outcrop and drink sapta, a traditional brew that opens their senses beyond the physical world. They listen for the earth's rumblings and whispers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_spirit-rock-34e1834257fc3ae0e34f/1-0000.mp3", duration = 27.9510204, start = 0},
  },
}
P.transport["subzone:stagnant-oasis"] = {
  hash = "efb088",
  fullHash = "6aa7df",
  text = "Stagnant Oasis. Kolkar centaur guard the Stagnant Oasis in the dry heart of the Barrens. Its waters lie between the Gold Road and Merchant Coast, drawing wildlife to its banks. East of the Gold Road, inland from the Merchant Coast, the Stagnant Oasis breaks up the dusty scrub of the Barrens. Dense foliage grows around the pool, where aggressive snapjaw turtles prowl. Weakened kodos often stray here from the great herds of the Field of Giants. Kolkar centaur keep camps along the banks and fiercely guard the water from anyone entering their territory. Strange life stirs in the pool, though its waters look still. Deviate Fish swim among other unusual creatures. Scholars and shamans watch the Barrens oases closely, studying the strange forces that affect local springheads and the wildlife that drinks from them.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stagnant-oasis-75eeda4fbdadf177bf58/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["subzone:stillwater-pond"] = {
  hash = "49b2dd",
  fullHash = "939955",
  text = "Stillwater Pond. Stillwater Pond is a quiet, stagnant body of water resting just west of Brill in Tirisfal Glades. Once a beloved picnic and swimming spot for the living children of Lordaeron, it has decayed into a murky pool inhabited by skeletal fish and prowled by dangerous scavengers. Before the Third War and the ravages of the Plague of Undeath, Stillwater Pond served as a tranquil retreat for the folk of Tirisfal Glades. Families from nearby hamlets gathered on its grassy banks for afternoon picnics, and children too young to brave the treacherous depths of Brightwater Lake learned to swim in its shallows. Today, the idyllic waters have turned lifeless and gray. The living have long vanished, leaving only skeletal fish darting beneath the surface and wandering undead drifting through the surrounding woods. Though quiet compared to the besieged roads and contested farms of Tirisfal, Stillwater Pond holds its own perils. The murky waters provide water only to the blighted beasts of the glades, most notably a ferocious darkhound named Bayne who stalks the shoreline. Travelers cutting through the western meadows on their way toward Brill must tread carefully, as predatory beasts and aimless zombies frequently linger along the water's edge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stillwater-pond-4fad18a25a40850ed7cd/1-0000.mp3", duration = 70.922449, start = 0},
  },
}
P.transport["subzone:stonebull-lake"] = {
  hash = "a208cd",
  fullHash = "a208cd",
  text = "Stonebull Lake. Stonebull Lake is a serene, horseshoe-shaped body of water wrapping around Bloodhoof Village in central Mulgore. Fed by the pristine natural runoff of the plains, it provides vital fresh water, abundant fish, and peaceful shores for the young tauren coming of age under Cairne Bloodhoof's guidance. Curving around Bloodhoof Village on three sides, Stonebull Lake defines the geography of central Mulgore. A wooden bridge crosses the lake's narrowest stretch, carrying the main dirt road between the settlement and the great mesa of Thunder Bluff to the north. Its calm waters are filled with native fish, making its banks a favored spot for resting hunters, weary travelers, and apprentice fishers learning their trade under the sweeping open sky.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_stonebull-lake-d388ce4f32567b7334df/1-0000.mp3", duration = 43.2587755, start = 0},
  },
}
P.transport["subzone:the-den"] = {
  hash = "0e9c7b",
  fullHash = "d65ce3",
  text = "The Den. The Den is the sheltered cave at the heart of the Valley of Trials in southwestern Durotar. Serving as the primary base of operations for young orc and troll adventurers, it provides martial and magical training before they set out into the wider world. Tucked into the red canyon walls of the Valley of Trials, the Den serves as an austere proving ground. Within its carved, shadowy interior, novice fighters, spellcasters, and hunters report to veterans like Gornek and Zureetha Fargaze. It is here that fledglings receive their foundational combat instruction, supplies, and initial rites of passage, hardening them for the harsh realities of Durotar and the greater struggles facing the new Horde. Beyond housing class trainers and provisions, the Den functions as an active field redoubt. Between dispatching new recruits to cull the local beasts and aggressive quilboars, the overseers maintain a strict, vigilant watch over the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_the-den-816f8ea04b542bd50482/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["subzone:thorn-hill"] = {
  hash = "8dcb29",
  fullHash = "8dcb29",
  text = "Thorn Hill. Razormane warbands strike Horde supply lines from Thorn Hill, east of the Crossroads. The fortified quilboar camp holds the high ridges between Durotar and the Barrens interior. Thorn Hill overlooks the roads between Durotar and the Crossroads. The Razormane gather here with hunters, trained wolves, and geomancers who shape the earth. Elder Mystic Razorsnout guides the quilboar as their attacks on Horde supply caravans grow bolder. The camp sits close to vital routes, making it one of the Crossroads guards' most immediate threats in the central savanna.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thorn-hill-2caf198a7571079faa4e/1-0000.mp3", duration = 33.7763265, start = 0},
  },
}
P.transport["subzone:thunder-ridge"] = {
  hash = "395791",
  fullHash = "395791",
  text = "Thunder Ridge. Thunder Ridge lies southwest of Orgrimmar, where thunder lizards roam a stripped canyon. Along the Southfury River in western Durotar, the former grove was ruined by human logging and dark sorcery. Agitated beasts and lingering cultists threaten nearby settlements. Thunder Ridge was once a green haven in arid Durotar, shaded by ancient trees. Shortly after the Third War, humans from Kul Tiras began felling its timber. The thunder lizards grew wild as their home was cut away. Then the Burning Blade used fel sorcery to destroy what remained of the canopy. Now the gorge lies barren and exposed, with angry, lightning-spewing beasts roaming through it.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thunder-ridge-8124312053dbfac170e9/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["subzone:thunderhorn-water-well"] = {
  hash = "7988e6",
  fullHash = "7988e6",
  text = "Thunderhorn Water Well. Thunderhorn Water Well is a vital water source situated in the rolling plains of central Mulgore along the path between Bloodhoof Village and Thunder Bluff. Like all the wells across the valley, it provides essential nourishment to the tribes and the herds roaming the grasslands. Keeping this water clean and defended is crucial to maintaining life in the tauren homeland. Situated amid the sprawling grasslands of central Mulgore, the Thunderhorn Water Well taps directly into the pure aquifers feeding the valley. For the nomadic tauren and their newly settled villages, these communal wells represent life, sustenance, and the Earth Mother's bounty. Because water is precious across the sun-drenched plains, controlling the wells means controlling the land itself. Intruders such as the Venture Company have repeatedly eyed these sources, attempting to harness them for industrial exploitation and disrupt the fragile balance the tribes fight to preserve.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thunderhorn-water-well-b56182495273686d5e10/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["subzone:tidus-stair"] = {
  hash = "3bd9e0",
  fullHash = "3bd9e0",
  text = "Tidus Stair. At Tidus Stair, two tauren shamans seek insight from the coastal water spirits. Broad stone terraces rise above the Merchant Coast southeast of Ratchet, sheltered beside the Great Sea. Waves crash below the weathered stone terraces of Tidus Stair, cut into the coastal bluffs southeast of Ratchet. The Barrens around you are arid and dusty, and skirmishes trouble the region, but this stretch above the Merchant Coast is quiet. A modest hut stands on the terraces, home to the tauren Islen Waterseer and Mahren Skyseer. Far from the goblin trade docks, they spend their days fishing, watching the horizon, and seeking insight from the coastal water spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tidus-stair-63ad4e5a1367f3480a5e/1-0000.mp3", duration = 41.3779592, start = 0},
  },
}
P.transport["subzone:tiragarde-keep"] = {
  hash = "99f7e6",
  fullHash = "9cccf3",
  text = "Tiragarde Keep. Kul Tiran marines still hold Tiragarde Keep on Durotar's Scuttle Coast, south of Razor Hill. Built during Grand Admiral Daelin Proudmoore's invasion, the ruined stronghold remains garrisoned under Lieutenant Benedict, a hostile thorn in the Horde's own territory. Tiragarde Keep gave Grand Admiral Daelin Proudmoore's fleet a beachhead on Durotar's red shores. He built it during his campaign to destroy Thrall's newly founded realm. The Horde eventually broke the siege and killed Proudmoore at Theramore Isle, but the keep was never fully abandoned. Resupply forces under Lieutenant Benedict reclaimed its shattered stone walls. They follow the late Admiral's standing orders to wage unyielding war against the orcs and reject the peace Lady Jaina Proudmoore forged. White battlements rise above Durotar's crimson cliffs, and Kul Tiran sailors and marines patrol them. The garrison raids supply lines near Razor Hill. For the Horde, the keep remains an ongoing security crisis and a live proving ground: orc and troll commanders send young warriors to assault the fortress and cut down Benedict's soldiers. They seek to contain the garrison before the humans can push farther inland.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tiragarde-keep-fd0e38601dcf245813c7/1-0000.mp3", duration = 69.5902041, start = 0},
  },
}
P.transport["subzone:tor-kren-farm"] = {
  hash = "95c1bf",
  fullHash = "d4bcc7",
  text = "Tor'kren Farm. At Tor'kren Farm in northwestern Durotar, Misha Tor'kren waits anxiously for news of her son Kron. He has not returned from a hunting trip. Tor'kren Farm struggles to raise pigs in Durotar's dry red dirt. The homestead lies southeast of Thunder Ridge, near the Southfury River. Feed and water are scarce, and the farm is isolated beneath nearby bluffs. Its yields are meager. Kron went west several days ago to hunt crocolisks along the Southfury River. Misha Tor'kren warned him about the vicious predators, but he left in anger. Now she asks passing adventurers to search for him or bring back a sign of his fate. She fears the worst, but cannot begin mourning without knowing what happened.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tor-kren-farm-bfd302c5e9c5121702e7/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["subzone:trade-quarter"] = {
  hash = "98a689",
  fullHash = "98a689",
  text = "Trade Quarter. The Trade Quarter forms the central core of the Undercity, resting directly beneath the lifts from the Ruins of Lordaeron. It functions as the beating economic heart of the Forsaken, housing their primary bank vaults, auction market, and essential civic services. From this concentric hub, vaulted corridors branch outward into the surrounding districts. Descending from the shattered surface of Lordaeron, travelers step off the lifts into the echoing stone expanse of the Trade Quarter. Designed around a tiered, circular layout, its central platform holds the city coffers and central bank, framed by bridges spanning noxious runoff canals. Surrounding terraces buzz with vendors, guild registries, and auctioneers bargaining amidst the eerie gloom. Even basic accommodations reflect Forsaken pragmatism: the local inn offers unlined wooden caskets rather than soft beds. From this central nexus, stone archways lead outward into the city's specialized quarters, making it the unavoidable crossroads for any business conducted within the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_trade-quarter-6f72f0b8650d113513aa/1-0000.mp3", duration = 60.16, start = 0},
  },
}
P.transport["subzone:valgan-s-field"] = {
  hash = "6aa3ee",
  fullHash = "6aa3ee",
  text = "Valgan's Field. Valgan's Field is an abandoned wheat farm nestled in northern Silverpine Forest, overlooking Lordamere Lake. Once a picturesque homestead, it now lies desolate and overrun by the feral Moonrage worgen unleashed by Archmage Arugal. Situated just west of the Shining Strand and north of the nearby river, Valgan's Field was once a prosperous wheat farm offering scenic views of Lordamere Lake. That peaceful life vanished when the Scourge tore through Lordaeron, forcing its owner, Valgan, to flee or meet his end. Left untended, the ruined structures fell into the claws of feral Moonrage worgen prowling down from Shadowfang Keep. Before the Third War, the mage Arugal spent time here, leaving behind remnants of his arcane research that now draw the attention of the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valgan-s-field-e62985da55f34a875e81/1-0000.mp3", duration = 46.4457143, start = 0},
  },
}
P.transport["subzone:valley-of-honor"] = {
  hash = "5b627d",
  fullHash = "747ac4",
  text = "Valley of Honor. In the Valley of Honor, Orgrimmar's warriors and hunters prepare for battle. Its barracks, guilds, and battlemasters serve the Horde's forces across Azeroth, while forges and training grounds keep its fighters ready. The Valley of Honor holds Orgrimmar's military quarter behind high canyon ridges. Practice weapons clash, and blacksmiths' anvils ring through the day. The Hall of the Brave draws seasoned warriors and battlemasters who coordinate campaigns in places such as Alterac Valley and Warsong Gulch. Training grounds for beastmasters and hunters flank the hall. Across the valley, the Horde equips, drills, and sends out its frontline defenders. The valley supplies arms and offers a place to rest between duties. The Burning Anvil and Red Canyon Mining provide armor and raw iron, while engineers work nearby in Nogg's Machine Shop. Grunts and visiting adventurers can fish in a quiet pool, taking a brief pause from the dust of the Valley of Strength.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-honor-c10ba1a43575d3c4c5fc/1-0000.mp3", duration = 55.04, start = 0},
  },
}
P.transport["subzone:valley-of-spirits"] = {
  hash = "ecc975",
  fullHash = "1f464a",
  text = "Valley of Spirits. Darkspear trolls make their home in the Valley of Spirits, west of Orgrimmar's main thoroughfares. Thatched lodges, tiki poles, and pools mark their place among the city's red stone and iron. The Valley of Spirits branches west from the Valley of Strength, a quiet enclave for the Darkspear trolls. The tribe settled in Durotar alongside Thrall's orcs, and made this pocket among the crags their gathering place in the city. Trollish craftspeople, spiritualists, and practitioners gather around wooden bridges and winding waters, practicing their arts away from the dry heat of Orgrimmar's main thoroughfares. The valley's lodges and pools draw those who practice magic and wild crafts. Witch doctors, herbalists, and spellcasters gather at the Spirit Lodge and Darkbriar Lodge. At the back, the Talon Gate opens toward the Barrens' open plains, giving wanderers, hunters, and travelers a quick passage beyond the canyon walls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-spirits-2954965123b189e39c8f/1-0000.mp3", duration = 55.3534694, start = 0},
  },
}
P.transport["subzone:valley-of-strength"] = {
  hash = "9cdf88",
  fullHash = "1d5c21",
  text = "Valley of Strength. The Valley of Strength is the bustling central commons of Orgrimmar, greeting all who pass through the city's towering front gates. Housing the city bank, the central auction house, and the Broken Tusk inn, it serves as the beating commercial and administrative heart of the Horde capital. Step past the fortified timber gates of Orgrimmar and you enter the Valley of Strength. Carved deep into the red canyon rock of Durotar, this valley serves as the Horde's front square. Adventurers, merchants, and warriors from all allied nations mingle across its dusty plazas, swapping war stories over flagons from the Broken Tusk inn or attending to vital trade at the central bank and auction house. It is a bustling testament to the strength and unity the orcs fought to establish in their new homeland. Beyond its defensive significance, the valley functions as the capital's foremost marketplace. Shops such as Soran's Leather and Steel Armory sell armor, while various vendors supply provisions for long treks across the Barrens. Grunts stand vigilant watch at every corner, directing newcomers and ensuring order among the diverse peoples who have taken refuge beneath Thrall's banner.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-strength-55284b2327a9dab88b9b/1-0000.mp3", duration = 67.4220408, start = 0},
  },
}
P.transport["subzone:venomweb-vale"] = {
  hash = "f4602e",
  fullHash = "f4602e",
  text = "Venomweb Vale. Venomweb Vale is a shadowed valley in eastern Tirisfal Glades, sitting just south of the Scarlet Monastery. Once a lush woodland teeming with game, the vale has devolved into a blighted nest overrun by aggressive, venomous arachnids. Before the plague consumed Lordaeron, this valley was a peaceful retreat of lush grass and verdant trees, favored by local hunters tracking deer and rabbits. Today, rot and creeping gloom dominate the landscape. Giant, venomous spiders swarm among the trees and hollows, led by the monstrous arachnid Sri'skulk. The vale's northern edge borders the territory of the Scarlet Crusade, where darkhounds prowl near the fortified Scarlet Encampment under Lieutenant Sanders.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_venomweb-vale-82316351008021d20a9e/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["subzone:venture-co-mine"] = {
  hash = "7d3876",
  fullHash = "7d3876",
  text = "Venture Co. Mine. Tucked into the eastern cliffs of Mulgore, the Venture Co. Mine is an unauthorized industrial excavation run by greedy goblin opportunists. Despite being denied rights by the tauren, the Venture Company dug into the hills regardless, threatening the natural balance of the plains. When the Venture Company sought rights to strip Mulgore of its minerals, the tauren flatly refused. The corporate cartel ignored them, tunneling deep into the eastern mountain wall anyway under the direction of Supervisor Fizsprocket. Their sprawling complex features three entrances—a ground tunnel guarded by hired muscle, a sheer cliffside overlook, and an upper passage leading out to a small lumber camp. The encroaching machines, smoke, and slag heaps represent a blatant defilement of sacred land.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_venture-co-mine-3f87c09c58fe10bf5615/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["subzone:war-quarter"] = {
  hash = "87fe29",
  fullHash = "815c7e",
  text = "War Quarter. The War Quarter is the northwestern district of the Undercity, serving as the command post and martial training ground for the Forsaken. Within its echoing stone chambers, the soldiers, priests, and crafters of Lordaeron hone their weapons and shadow magic in defense of their fledgling kingdom. It houses training halls for warriors and priests alongside weapon masters and heavy industry. Occupying the northwest sector of the subterranean metropolis, the War Quarter stands as the bastion of martial strength for the Forsaken. Beneath its gloomy stone arches, rank-and-file guards and elite champions assemble to drill in armed combat. Unlike traditional barracks of living kingdoms, this military center combines ruthless iron warfare with the chilling rites of shadow, housing an ominous Altar of Darkness where spiritual discipline merges with military ambition. Beyond housing warrior and priest guilds, the quarter functions as the heart of Undercity's wartime production. The clatter of blades and armor echoes continually against the stone, supported by the district's blacksmiths, smelters, and weapon masters. Here, iron forged deep in the earth is shaped to outfit the forces defending the ruins of Lordaeron from the Scourge and Scarlet Crusade.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_war-quarter-f37101d3e1ac3fc1f914/1-0000.mp3", duration = 71.0791837, start = 0},
  },
}
P.transport["subzone:whispering-forest"] = {
  hash = "7dacee",
  fullHash = "7dacee",
  text = "Whispering Forest. The Whispering Forest is a secluded, mountainous woodland nestled behind the steep cliffs west of Deathknell. Largely cut off from the rest of Tirisfal Glades, it harbors uncanny wildlife, a mysterious fairy circle, and deep-seated corruption sleeping far beneath the soil. Tucked away behind Northface Rock and Bandarion Keep, the Whispering Forest feels entirely alienated from the surrounding plague-touched kingdom. While it contains afflicted deer and roaming predators, it also features a tranquil lake and a strange ring of giant mushrooms, glowing with an uncanny energy beneath a hovering cloud of mist. The ghostly Knight of Mourning wanders the fairy circle, bound there by oath, amid a natural magic that seems to defy the Scourge-ruined land.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_whispering-forest-e3bdd4db150c96af57a7/1-0000.mp3", duration = 45.3485714, start = 0},
  },
}
P.transport["subzone:whispering-shore"] = {
  hash = "03a14a",
  fullHash = "f5f184",
  text = "Whispering Shore. The Whispering Shore is a somber stretch of coastline in western Tirisfal Glades, resting just north of the Solliden Farmstead. Once a tranquil and bountiful retreat for Lordaeron's fishermen, its cold waters have since been overrun by a violent tribe of murlocs. Before the Third War swept across northern Lordaeron, the Whispering Shore was renowned among locals as a favored fishing haven, celebrated for its calm waters and plentiful catches. Today, the chilling spray of the Great Sea crashes against an empty coast stripped of its peaceful past. The waters have grown cold and dark, devoid of their former bounty, and any unfortunate traveler wandering down from the hills risks being ambushed by territorial coastal dwellers. The beach is now firmly claimed by a band of hostile murlocs who ruthlessly attack anyone approaching the surf. Led by a fierce chieftain named Muad, these aquatic scavengers guard the shallows and tidal flats aggressively, posing a constant danger to nearby roads and the nearby Solliden Farmstead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_whispering-shore-7275ecb02f93260dfd24/1-0000.mp3", duration = 60.7869388, start = 0},
  },
}
P.transport["subzone:wildmane-water-well"] = {
  hash = "ce93d7",
  fullHash = "ce93d7",
  text = "Wildmane Water Well. The Wildmane Water Well is the northernmost of the sacred water wells scattered across Mulgore, resting just north of the mesas of Thunder Bluff. Vital to the plains and their herds, it has become a contested flashpoint targeted by goblin opportunists seeking to choke the tauren's lifeblood. For generations, the nomadic tauren have relied on sacred water wells dug across the golden plains of Mulgore to sustain their people and their wandering kodo herds. The Wildmane Well guards the northern expanse just beyond the shadow of Thunder Bluff. Its vital importance makes it an irresistible target for enemies of the tribes. The goblins of the Venture Company have fouled it with their poisons in a bid to control the regional water supply, and only a cleansing ritual with a totem crafted by the tauren can make its waters pure again.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_wildmane-water-well-4f08e6ff81f1dec9a9f4/1-0000.mp3", duration = 44.0685714, start = 0},
  },
}
P.transport["subzone:windfury-ridge"] = {
  hash = "b8cd47",
  fullHash = "b8cd47",
  text = "Windfury Ridge. Windfury Ridge is a rugged highland area flanking the pastures of Mulgore. Notorious for harboring vicious harpies alongside predatory wolves and cougars, it poses a constant hazard to travelers while offering prized feathers to tauren artisans. Windfury Ridge rises sharply above Mulgore's serene plains, serving as the hunting grounds of the Windfury harpies. These vicious winged creatures nest high along the crags, readily swooping down upon any unwary wanderers who skirt the hills. The rocky terrain is further populated by prowling prairie wolves and wild mountain cougars, making the ridge one of the more treacherous borders of the tauren heartland. Despite the danger, the harpies are frequently hunted by brave tauren warriors; their vibrant, iridescent plumage is highly sought after across Thunder Bluff to adorn ceremonial garments for lavish feasts and wedding celebrations.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_windfury-ridge-58b06f515ac3700a9fab/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["subzone:winterhoof-water-well"] = {
  hash = "92e71a",
  fullHash = "92e71a",
  text = "Winterhoof Water Well. The Winterhoof Water Well is a vital fresh water source situated on the edge of the Rolling Plains in southern Mulgore. Crucial to the local wildlife and nomadic tauren tribes, the well has recently fallen under threat from the exploitative Venture Company, who seek to poison and control the region's water supply. In the arid stretches of central Kalimdor, water is life, and Mulgore's subterranean wells sustain both the herds of the plains and the encampments of the tauren. The Winterhoof Water Well, named for one of the respected tribes of the plains, taps into the deep aquifers beneath the Rolling Plains. Unfortunately, its strategic importance has drawn the avarice of the Venture Company. Rather than sharing the land or negotiating, the ruthless goblin cartel has attempted to poison the water supply to exert leverage over the surrounding territory.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_winterhoof-water-well-bc27d8b61c8524afb77a/1-0000.mp3", duration = 47.9085714, start = 0},
  },
}
